AudioRecorder 基本使用方法
1. 在 Recorder Thread 中创建 Recorder 与相关的 Encoder2. loop 读取 Recorder 里面的 PCM data，不断地将 PCM 喂入 Encoder中3. 外部停止录音后，将 run 这个 flag 置为 false 跳出循环，并且 close 相关 Encoder 并且保存他们的结果。4. release 相关资源。
创建一个新的MediaCodec对象然后调用configure()方法对MediaCodec进行配置
mMediaEncoder = MediaCodec.createEncoderByType(&quot;audio/mp4a-latm&quot;); MediaFormat mediaFormat = new MediaFormat();mediaFormat.setString(MediaFormat.KEY_MIME, &quot;audio/mp4a-latm&quot;);mediaFormat.setInteger(MediaFormat.KEY_AAC_PROFILE, MediaCodecInfo.CodecProfileLevel.AACObjectLC);mediaFormat.setInteger(MediaFormat.KEY_BIT_RATE, 128000);mediaFormat.setInteger(MediaFormat.KEY_CHANNEL_COUNT, 1);mediaFormat.setInteger(MediaFormat.KEY_MAX_INPUT_SIZE, 1024 * 1024);mediaFormat.setInteger(MediaFormat.KEY_SAMPLE_RATE, 44100);// 第四个参数 编码的时候是MediaCodec.CONFIGURE_FLAG_ENCODE 解码的时候是0mMediaEncoder.configure(mediaFormat, null, null, MediaCodec.CONFIGURE_FLAG_ENCODE);
调用MediaCodec的start()方法，此时MediaCodec处于Executing状态，可以通过getInputBuffers()方法和getOutputBuffers()方法获取缓存队列
// start()后进入执行状态，才能做后续的操作mMediaEncoder.start();// 获取输入缓存，输出缓存mAudioInputBuffers = mMediaEncoder.getInputBuffers();mAudioOutputBuffers = mMediaEncoder.getOutputBuffers();// getInput/OutputBuffers()已经被废弃，应通过dequeueOutputBuffer()获取id然后使用getInput/OutputBuffer(int)来获取缓冲区。(见下文官方例子)
返回的整型变量为请求到的输入缓存的index，通过getInputBuffers()得到的是输入缓存数组，通过index和输入缓存数组可以得到当前请求的输入缓存，在使用之前要clear一下，避免之前的缓存数据影响当前数据
// dequeueInputBuffer（time）需要传入一个时间值，-1表示一直等待，0表示不等待有可能会丢帧，其他表示等待多少毫秒int inputIndex = mMediaEncoder.dequeueInputBuffer(-1);...// 获取输入缓存的indexByteBuffer inputByteBuf = mAudioInputBuffers[inputIndex];inputByteBuf.clear();
把数据添加到输入缓存中，并调用queueInputBuffer()把缓存数据入队
// 添加数据inputByteBuf.put(data);// 限制ByteBuffer的访问长度inputByteBuf.limit(data.length);// 把输入缓存塞回去给MediaCodecmMediaEncoder.queueInputBuffer(inputIndex, 0, data.length, 0, 0); // mAudioEncoder.queueInputBuffer(inputBufIndex, 0, data.length, (1000000 * mEncodedSize / AUDIO_BYTE_PER_SAMPLE), 0);// 有些设备不设置好presentationTimeUs会丢帧// 这里的1000000是把秒变成微秒，音频输出的时间戳是微秒，输出到surface的视频是纳秒，源码中是这么说的：// * @param presentationTimeUs The presentation timestamp in microseconds for this// *                           buffer. This is normally the media time at which this// *                           buffer should be presented (rendered). When using an output// *                           surface, this will be propagated as the &#123;@link// *                           SurfaceTexture#getTimestamp timestamp&#125; for the frame (after// *                           conversion to nanoseconds).
获取输出缓存和获取输入缓存类似，首先通过dequeueOutputBuffer(BufferInfo info, long timeoutUs)来请求一个输出缓存，这里需要传入一个BufferInfo对象，用于存储ByteBuffer的信息
// 获取输出缓存的indexint outputIndex = mMediaEncoder.dequeueOutputBuffer(mBufferInfo, 0);
通过返回的index得到输出缓存，并通过BufferInfo获取ByteBuffer的信息，注意一定要调用releaseOutputBuffer方法
// 获取输出缓存的indexint outputIndex = mMediaEncoder.dequeueOutputBuffer(mBufferInfo, 0);while (outputIndex &gt;= 0) &#123;    // 获取缓存信息的长度    int byteBufSize = mBufferInfo.size;    ...    // 处理数据    ...    //释放    mMediaEncoder.releaseOutputBuffer(outputIndex, false);    outputIndex = mMediaEncoder.dequeueOutputBuffer(mBufferInfo, 0);&#125;
使用完MediaCodec后释放资源
mAudioEncoder.stop();mAudioEncoder.release();
上述过程的总结代码如下：PCM数据编码为AAC数据
public void init() &#123;    try &#123;        mMediaEncoder = MediaCodec.createEncoderByType(&quot;audio/mp4a-latm&quot;);         MediaFormat mediaFormat = new MediaFormat();        mediaFormat.setString(MediaFormat.KEY_MIME, &quot;audio/mp4a-latm&quot;);        mediaFormat.setInteger(MediaFormat.KEY_AAC_PROFILE, MediaCodecInfo.CodecProfileLevel.AACObjectLC);        mediaFormat.setInteger(MediaFormat.KEY_BIT_RATE, 128000);        mediaFormat.setInteger(MediaFormat.KEY_CHANNEL_COUNT, 1);        mediaFormat.setInteger(MediaFormat.KEY_MAX_INPUT_SIZE, 1024 * 1024);        mediaFormat.setInteger(MediaFormat.KEY_SAMPLE_RATE, 44100);        // 第四个参数 编码的时候是MediaCodec.CONFIGURE_FLAG_ENCODE 解码的时候是0        mMediaEncoder.configure(mediaFormat, null, null, MediaCodec.CONFIGURE_FLAG_ENCODE);        // start()后进入执行状态，才能做后续的操作        mMediaEncoder.start();        // 获取输入缓存，输出缓存        mAudioInputBuffers = mMediaEncoder.getInputBuffers();        mAudioOutputBuffers = mMediaEncoder.getOutputBuffers();    &#125; catch (IOException e) &#123;        e.printStackTrace();    &#125;&#125; public byte[] encodeData(byte[] data) &#123;    // dequeueInputBuffer（time）需要传入一个时间值，-1表示一直等待，0表示不等待有可能会丢帧，其他表示等待多少毫秒    int inputIndex = mMediaEncoder.dequeueInputBuffer(-1);    // 获取输入缓存的index    if (inputIndex &gt;= 0) &#123;        ByteBuffer inputByteBuf = mAudioInputBuffers[inputIndex];        inputByteBuf.clear();        // 添加数据        inputByteBuf.put(data);        // 限制ByteBuffer的访问长度        inputByteBuf.limit(data.length);        // 把输入缓存塞回去给MediaCodec        mMediaEncoder.queueInputBuffer(inputIndex, 0, data.length, 0, 0);    &#125;     // 获取输出缓存的index    int outputIndex = mMediaEncoder.dequeueOutputBuffer(mBufferInfo, 0);    while (outputIndex &gt;= 0) &#123;        // 获取缓存信息的长度        int byteBufSize = mBufferInfo.size;        // 添加ADTS头部后的长度        int bytePacketSize = byteBufSize + 7;         ByteBuffer outPutBuf = mAudioOutputBuffers[outputIndex];        outPutBuf.position(mBufferInfo.offset);        outPutBuf.limit(mBufferInfo.offset + mBufferInfo.size);         byte[] targetByte = new byte[bytePacketSize];        //添加ADTS头部        addADTStoPacket(targetByte, bytePacketSize);        /*        get（byte[] dst,int offset,int length）:ByteBuffer从position位置开始读，读取length个byte，并写入dst下        标从offset到offset + length的区域         */        outPutBuf.get(targetByte, 7, byteBufSize);         outPutBuf.position(mBufferInfo.offset);         try &#123;            fileOutputStream.write(targetByte);        &#125; catch (IOException e) &#123;            e.printStackTrace();        &#125;        //释放        mMediaEncoder.releaseOutputBuffer(outputIndex, false);        outputIndex = mMediaEncoder.dequeueOutputBuffer(mBufferInfo, 0);    &#125;    return data;&#125; /** * 给编码出的aac裸流添加adts头字段 * @param packet    要空出前7个字节，否则会搞乱数据 * @param packetLen */private void addADTStoPacket(byte[] packet, int packetLen) &#123;    int profile = 2;  // AAC LC    int freqIdx = 4;  // 44.1KHz    int chanCfg = 1;  // SCE    packet[0] = (byte) 0xFF;    packet[1] = (byte) 0xF9;    packet[2] = (byte) (((profile - 1) &lt;&lt; 6) + (freqIdx &lt;&lt; 2) + (chanCfg &gt;&gt; 2));    packet[3] = (byte) (((chanCfg &amp; 3) &lt;&lt; 6) + (packetLen &gt;&gt; 11));    packet[4] = (byte) ((packetLen &amp; 0x7FF) &gt;&gt; 3);    packet[5] = (byte) (((packetLen &amp; 7) &lt;&lt; 5) + 0x1F);    packet[6] = (byte) 0xFC;&#125;
附带贴上一段官方提供的代码思路（学习思路）：官方给出的一段同步典型代码
MediaCodec codec = MediaCodec.createByCodecName(name);codec.configure(format, …);MediaFormat outputFormat = codec.getOutputFormat(); // option Bcodec.start();for (;;) &#123;  int inputBufferId = codec.dequeueInputBuffer(timeoutUs);  if (inputBufferId &gt;= 0) &#123;    ByteBuffer inputBuffer = codec.getInputBuffer(…);    // fill inputBuffer with valid data    …    codec.queueInputBuffer(inputBufferId, …);  &#125;  int outputBufferId = codec.dequeueOutputBuffer(…);  if (outputBufferId &gt;= 0) &#123;    ByteBuffer outputBuffer = codec.getOutputBuffer(outputBufferId);    MediaFormat bufferFormat = codec.getOutputFormat(outputBufferId); // option A    // bufferFormat is identical to outputFormat    // outputBuffer is ready to be processed or rendered.    …    codec.releaseOutputBuffer(outputBufferId, …);  &#125; else if (outputBufferId == MediaCodec.INFO_OUTPUT_FORMAT_CHANGED) &#123;    // Subsequent data will conform to new format.    // Can ignore if using getOutputFormat(outputBufferId)    outputFormat = codec.getOutputFormat(); // option B  &#125;&#125;codec.stop();codec.release();

MediaCodec编码例子（异步）使用AudioRecord录制音频，MediaCodec编码为AAC
设置回调方法必须在MediaCodec创建之后，并且在configure方法之前。
其中index是指向缓冲区的BufferId，利用这个index用户可以获得缓冲区；format是变化后的Mediaformat。
// 当inputbuffer可用时回调此方法void onInputBufferAvailable(MediaCodec codec, int index) // 当outputbuffer可用时回调此方法void onOutputBufferAvailable(MediaCodec codec, int index, MediaCodec.BufferInfo info) // 当输出格式变化时回调此方法void onOutputFormatChanged(MediaCodec codec, MediaFormat format) // 发生错误时回调此方法void onError(MediaCodec codec, MediaCodec.CodecException e)
基于同步的方法做对应修改，如下给出官方示例：官方给出的一段异步典型代码
MediaCodec codec = MediaCodec.createByCodecName(name);MediaFormat mOutputFormat; // member variablecodec.setCallback(new MediaCodec.Callback() &#123;   @Override   void onInputBufferAvailable(MediaCodec mc, int inputBufferId) &#123;     ByteBuffer inputBuffer = codec.getInputBuffer(inputBufferId);     // fill inputBuffer with valid data     …     codec.queueInputBuffer(inputBufferId, …);   &#125;    @Override   void onOutputBufferAvailable(MediaCodec mc, int outputBufferId, …) &#123;     ByteBuffer outputBuffer = codec.getOutputBuffer(outputBufferId);     MediaFormat bufferFormat = codec.getOutputFormat(outputBufferId); // option A     // bufferFormat is equivalent to mOutputFormat     // outputBuffer is ready to be processed or rendered.     …     codec.releaseOutputBuffer(outputBufferId, …);   &#125;    @Override   void onOutputFormatChanged(MediaCodec mc, MediaFormat format) &#123;     // Subsequent data will conform to new format.     // Can ignore if using getOutputFormat(outputBufferId)     mOutputFormat = format; // option B   &#125;    @Override   void onError(…) &#123;     …   &#125;&#125;);codec.configure(format, …);mOutputFormat = codec.getOutputFormat(); // option Bcodec.start();// wait for processing to completecodec.stop();codec.release();

MediaCodec解码例子硬解码AAC音频文件并播放
初始化结束后，调用play()传入音频文件即可
配置播放器initAudioTrack()
private void initAudioTrack() &#123;    // 配置播放器    int streamType = AudioManager.STREAM_MUSIC;    int sampleRate = 44100;    int channelConfig = AudioFormat.CHANNEL_OUT_MONO;    int audioFormat = AudioFormat.ENCODING_PCM_16BIT;    int mode = AudioTrack.MODE_STREAM;    int minBufferSize = AudioTrack.getMinBufferSize(sampleRate, channelConfig, audioFormat);    mAudioTrack = new AudioTrack(streamType, sampleRate, channelConfig, audioFormat,            Math.max(minBufferSize, 2048), mode);&#125;
配置解码器initDecoder()
private void initDecoder() &#123;    try &#123;        // 需要解码数据的类型        String mine = &quot;audio/mp4a-latm&quot;;        // 初始化解码器        mDecoder = MediaCodec.createDecoderByType(mine);        // MediaFormat用于描述音视频数据的相关参数        MediaFormat mediaFormat = new MediaFormat();        // 数据类型        mediaFormat.setString(MediaFormat.KEY_MIME, mine);        // 声道个数        mediaFormat.setInteger(MediaFormat.KEY_CHANNEL_COUNT, 2);        // 采样率        mediaFormat.setInteger(MediaFormat.KEY_SAMPLE_RATE, 48000);        // 比特率        mediaFormat.setInteger(MediaFormat.KEY_BIT_RATE, 128000);        // 用来标记AAC是否有adts头，1-&gt;有        mediaFormat.setInteger(MediaFormat.KEY_IS_ADTS, 1);        // 用来标记aac的类型        mediaFormat.setInteger(MediaFormat.KEY_AAC_PROFILE, MediaCodecInfo.CodecProfileLevel.AACObjectLC);        byte[] data = new byte[]&#123;(byte) 0x11, (byte) 0x90&#125;;        ByteBuffer csd_0 = ByteBuffer.wrap(data);        mediaFormat.setByteBuffer(&quot;csd-0&quot;, csd_0);        // 解码器配置        mDecoder.configure(mediaFormat, null, null, 0);         mDecoder.start();        // 输入ByteBuffer        mCodecInputBuffers = mDecoder.getInputBuffers();        // 输出ByteBuffer        mCodecOutputBuffers = mDecoder.getOutputBuffers();    &#125; catch (IOException e) &#123;        e.printStackTrace();    &#125;&#125;
传入文件即可播放aac音频play()
public void play(File audioRecordFile) &#123;    // 这个值用于找到第一个帧头后，继续寻找第二个帧头，如果解码失败可以尝试缩小这个值    int FRAME_MIN_LEN = 50;    // 一般AAC帧大小不超过200k,如果解码失败可以尝试增大这个值    int FRAME_MAX_LEN = 100 * 1024;    // 从文件流读数据    FileInputStream fis = null;    byte[] mBuffer = new byte[2048];    try &#123;        // 循环读数据，写到播放器去播放        fis = new FileInputStream(audioRecordFile);        Log.d(TAG, audioRecordFile.toString());        // 保存完整数据帧        byte[] frame = new byte[FRAME_MAX_LEN];        // 当前帧长度        int frameLen = 0;        // 每次从文件读取的数据        byte[] readData = new byte[10 * 1024];        // 循环读数据，写到播放器去播放 只要没读完，循环播放        mAudioTrack.play();        int readLen;        while ((readLen = fis.read(mBuffer)) != -1) &#123;            // 当前长度小于最大值            if (frameLen + readLen &lt; FRAME_MAX_LEN) &#123;                // 将readData拷贝到frame                System.arraycopy(readData, 0, frame, frameLen, readLen);                // 修改frameLen                frameLen += readLen;                // 寻找第一个帧头                int headFirstIndex = findHead(frame, 0, frameLen);                while (headFirstIndex &gt;= 0 &amp;&amp; isHead(frame, headFirstIndex)) &#123;                    // 寻找第二个帧头                    int headSecondIndex = findHead(frame, headFirstIndex + FRAME_MIN_LEN, frameLen);                    // 如果第二个帧头存在，则两个帧头之间的就是一帧完整的数据                    if (headSecondIndex &gt; 0 &amp;&amp; isHead(frame, headSecondIndex)) &#123;                        // 视频解码                        decodeData(frame, headFirstIndex, headSecondIndex - headFirstIndex);                        // 截取headSecondIndex之后到frame的有效数据,并放到frame最前面                        byte[] temp = Arrays.copyOfRange(frame, headSecondIndex, frameLen);                        System.arraycopy(temp, 0, frame, 0, temp.length);                        // 修改frameLen的值                        frameLen = temp.length;                        // 继续寻找数据帧                        headFirstIndex = findHead(frame, 0, frameLen);                    &#125; else &#123;                        // 找不到第二个帧头                        headFirstIndex = -1;                    &#125;                &#125;            &#125; else &#123;                //如果长度超过最大值，frameLen置0                frameLen = 0;            &#125;        &#125;        Log.d(TAG, &quot;播放完毕！&quot;);    &#125; catch (Exception e) &#123;        e.printStackTrace();    &#125; finally &#123;        closeInputStream(fis);        // 播放器释放        resetQuietly(mAudioTrack);    &#125;&#125;
play()中的aac解码+播放函数decodeData()
/** * aac解码+播放 */private void decodeData(byte[] data, int offset, int length) &#123;    int inputIndex = mDecoder.dequeueInputBuffer(-1);    if (inputIndex &gt;= 0) &#123;        // 获取当前的ByteBuffer        ByteBuffer inputByteBuf = mCodecInputBuffers[inputIndex];        // 清空ByteBuffer        inputByteBuf.clear();        // 填充数据        inputByteBuf.put(data, offset, length);        // 将指定index的input buffer提交给解码器        mDecoder.queueInputBuffer(inputIndex, 0, length, 0, 0);    &#125;    // 编解码器缓冲区    MediaCodec.BufferInfo info = new MediaCodec.BufferInfo();    int outputBufferIndex = mDecoder.dequeueOutputBuffer(info, -1);    ByteBuffer outputBuffer;    while (outputBufferIndex &gt;= 0) &#123;        // 获取解码后的ByteBuffer        outputBuffer = mCodecOutputBuffers[outputBufferIndex];        // 用来保存解码后的数据        byte[] outData = new byte[info.size];        outputBuffer.get(outData);        // 清空缓存        outputBuffer.clear();        // 播放解码后的数据        mAudioTrack.write(outData, 0, info.size);        // 释放已经解码的buffer        mDecoder.releaseOutputBuffer(outputBufferIndex, false);        // 解码未解完的数据        outputBufferIndex = mDecoder.dequeueOutputBuffer(info, -1);    &#125;&#125;
play()中的找缓存中aac帧头起始位置findHead()
/** * 寻找指定buffer中AAC帧头的开始位置 * * @param startIndex 开始的位置 * @param data       数据 * @param max        需要检测的最大值 * @return */private int findHead(byte[] data, int startIndex, int max) &#123;    int i;    for (i = startIndex; i &lt;= max; i++) &#123;        // 发现帧头        if (isHead(data, i))            break;    &#125;    // 检测到最大值，未发现帧头    if (i == max) &#123;        i = -1;    &#125;    return i;&#125;
play()中的判断aac帧头方法isHead()
/** * 判断aac帧头 */private boolean isHead(byte[] data, int offset) &#123;    boolean result = false;    if (data[offset] == (byte) 0xFF &amp;&amp; data[offset + 1] == (byte) 0xF1            &amp;&amp; data[offset + 3] == (byte) 0x80) &#123;        result = true;    &#125;    return result;&#125;

AudioTrackAudioTrack属于更偏底层的音频播放，MediaPlayerService的内部就是使用了AudioTrack。
AudioTrack用于单个音频播放和管理，相比于MediaPlayer具有精炼、高效的优点，更适合实时产生播放数据的情况。如加密的音频， MediaPlayer是束手无策的，AudioTrack却可以。
AudioTrack用于播放PCM（PCM无压缩的音频格式）音乐流的回放，如果需要播放其它格式音频，需要响应的解码器，这也是AudioTrack用的比较少的原因，需要自己解码音频。

AudioTrack实现PCM音频播放
配置基本参数

获取最小缓冲区大小

创建AudioTrack对象

获取PCM文件，转成DataInputStream

开启/停止播放


AudioTrack常见参数StreamType 音频流类型：区分系统不同功能的音频流。
sampleRateInHz 采样率：播放的音频每秒钟会有多少次采样，MediaRecoder 的采样率通常是8000Hz AAC的通常是44100Hz。 设置采样率为44100为常用的采样率。
channelConfig 声道数（通道数）：一般可选的就两种，单声道CHANNEL_IN_MONO，双声道CHANNEL_IN_STEREO，建议选择单声道。
audioFormat 数据位宽：只支持AudioFormat.ENCODING_PCM_8BIT（8bit）和AudioFormat.ENCODING_PCM_16BIT（16bit）两种，后者支持所有Android手机。
bufferSizeInBytes 音频缓冲区大小：建议使用AudioTrack.getMinBufferSize()这个方法获取。
mode 播放模式：MODE_STATIC，一次性将所有数据都写入播放缓冲区中，简单高效，一般用于铃声，系统提醒音，内存比较小的。MODE_STREAM，需要按照一定的时间间隔，不断的写入音频数据，理论上它可以应用于任何音频播放的场景。
AudioTrack例子：播放录音播放录音playAudio()和播放测试音频playAudioTest()
public void playAudio() &#123;    if (!mIsPlaying) &#123;        mExecutorService.submit(() -&gt; &#123;            mIsPlaying = true;            doStartPlay(getLastFile());        &#125;);    &#125;&#125; public void playAudioTest() &#123;    if (mHasPausing &amp;&amp; !mIsPausing &amp;&amp; mAudioTrack != null) &#123;        mIsPausing = true;        mAudioTrack.stop();        mBtStreamPlayerTest.setText(&quot;播放测试录音&quot;);        return;    &#125;    if (mIsPlaying) &#123;        Toast.makeText(mContext, &quot;正在播放&quot;, Toast.LENGTH_SHORT).show();    &#125; else &#123;        mBtStreamPlayerTest.setText(&quot;暂停测试录音&quot;);        mExecutorService.submit(() -&gt; &#123;            if (Build.VERSION.SDK_INT &gt;= Build.VERSION_CODES.KITKAT) &#123;                mHasPausing = true;                mIsPausing = false;                mIsPlaying = true;                doStartPlay(new File(mContext.getExternalFilesDir(Environment.DIRECTORY_DOCUMENTS) + &quot;/AudioRecordDemo/test.pcm&quot;));            &#125;        &#125;);    &#125;&#125;
一个算法，获得文件夹里最新更新的文件getLastFile()
private File getLastFile() &#123;    File realFile = null;    if (android.os.Build.VERSION.SDK_INT &gt;= android.os.Build.VERSION_CODES.KITKAT) &#123;        realFile = new File(mContext.getExternalFilesDir(Environment.DIRECTORY_DOCUMENTS) + &quot;/AudioRecordDemo/&quot;);    &#125;    if (realFile.isDirectory()) &#123;        List files = new ArrayList();        File[] subFiles = realFile.listFiles();        for (File file : subFiles) &#123;            files.add(file);        &#125;        Collections.sort(files, (Comparator&lt;File&gt;) (file, newFile) -&gt; &#123;            if (file.lastModified() &lt; newFile.lastModified()) &#123;                return 1;            &#125; else if (file.lastModified() == newFile.lastModified()) &#123;                return 0;            &#125; else &#123;                return -1;            &#125;        &#125;);        Log.d(TAG, &quot;play &quot; + ((File) files.get(0)).toString());        return (File) files.get(0);    &#125;    return null;&#125;
播放录音具体实现，AudioTrack的使用doStartPlay()
private void doStartPlay(File audioRecordFile) &#123;    if (audioRecordFile == null) &#123;        Log.d(TAG, &quot;请先录制音频！&quot;);        mIsPlaying = false;        return;    &#125;    // 配置播放器    // 音乐类型，扬声器播放    int streamType = AudioManager.STREAM_MUSIC;    // 录音时采用的采样频率，所以播放时同样的采样频率    int sampleRate = 44100;    // 单声道，和录音时设置的一样    int channelConfig = AudioFormat.CHANNEL_OUT_MONO;    // 录音时使用16bit，所以播放时同样采用该方式    int audioFormat = AudioFormat.ENCODING_PCM_16BIT;    // 流模式    int mode = AudioTrack.MODE_STREAM;    // 计算最小buffer大小    int minBufferSize = AudioTrack.getMinBufferSize(sampleRate, channelConfig, audioFormat);    // 构造AudioTrack 不能小于AudioTrack的最低要求，也不能小于我们每次读的大小    mAudioTrack = new AudioTrack(streamType, sampleRate, channelConfig, audioFormat,            Math.max(minBufferSize, BUFFER_SIZE), mode);    // 从文件流读数据    FileInputStream fis = null;    try &#123;        // 循环读数据，写到播放器去播放        fis = new FileInputStream(audioRecordFile);        fis.skip(mOffset);        Log.d(TAG, audioRecordFile.toString());        // 循环读数据，写到播放器去播放 只要没读完，循环播放        int read;        mAudioTrack.play();        Log.d(TAG, String.valueOf(mAudioTrack.getPlayState()));        // write 是阻塞的方法        while ((read = fis.read(mBuffer)) != -1) &#123;            // todo: 处理mBuffer实现元数据处理变音等功能            int status = mAudioTrack.write(mBuffer, 0, read);            updateOffset(read);            Log.d(TAG, String.valueOf(mOffset));            // 检查write的返回值，处理错误            checkStatus(status);        &#125;        Log.d(TAG, &quot;播放完毕！&quot;);    &#125; catch (Exception e) &#123;        e.printStackTrace();        // 读取失败        playFail();    &#125; finally &#123;        mIsPlaying = false;        // 关闭文件输入流        closeInputStream(fis);        // 播放器释放        resetQuietly(mAudioTrack);    &#125;&#125; private void updateOffset(int read) &#123;    if (mAudioTrack.getPlayState() == mAudioTrack.PLAYSTATE_PLAYING) &#123;        mOffset += read;    &#125;&#125;
关闭输入流closeInputStream()和resetQuietly()
private void closeInputStream(InputStream is) &#123;    if (is != null) &#123;        try &#123;            is.close();        &#125; catch (IOException e) &#123;            e.printStackTrace();        &#125;    &#125;&#125; private void resetQuietly(AudioTrack audioTrack) &#123;    try &#123;        audioTrack.stop();        audioTrack.release();    &#125; catch (Exception e) &#123;        e.printStackTrace();    &#125;&#125;
播放失败，更新UI操作playFail()
private void playFail() &#123;    mHandler.post(new Runnable() &#123;        @Override        public void run() &#123;            Toast.makeText(mContext, &quot;pcm播放失败&quot;, Toast.LENGTH_SHORT).show();        &#125;    &#125;);&#125;
onDestroy()释放资源
@Overrideprotected void onDestroy() &#123;    super.onDestroy();    if (mAudioTrackTest.getAudioTrack() != null) &#123;        mAudioTrackTest.getAudioTrack().stop();    &#125;    if (mExecutorService != null) &#123;        mExecutorService.shutdownNow();        mExecutorService = null;    &#125;&#125;

MediaPlayer
MediaPlayer支持AAC、AMR、FLAC、MP3、MIDI、OGG、PCM等格式，MediaPlayer可以通过设置元数据和播放源来音频。
播放Raw文件夹下面音频的元数据
// 直接创建，不需要设置setDataSourceMediaPlayer mMediaPlayer;mMediaPlayer=MediaPlayer.create(this, R.raw.audio);mMediaPlayer.start();
通过设置播放源来播放音频文件的三个方法
setDataSource(String path)

// 如果从sd卡中加载音乐// &lt;uses-permission android:name=&quot;android.permission.READ_EXTERNAL_STORAGE&quot;/&gt;// 利用 Environment.getExternalStorageDirectory() 获取SD卡的根目录了，一般为/storage/emulated/0// 把xxx.wav放到SD的根目录下，就可以获得文件的路径了 String path = Environment.getExternalStorageDirectory()+&quot;/xxx.wav&quot;;mMediaPlayer.setDataSource(path); // 如果从网络加载音乐，如果是从网络中加载那么需要设置网络权限// &lt;uses-permission android:name=&quot;android.permission.INTERNET&quot;/&gt;mMediaPlayer.setDataSource(&quot;http://..../xxx.mp3&quot;); // 需使用异步缓冲mMediaPlayer.prepareAsync();

setDataSource(FileDescriptor fd)

// 资源文件放在assets文件夹AssetFileDescriptor fd = getAssets().openFd(&quot;samsara.mp3&quot;);mMediaPlayer.setDataSource(fd.getFileDescriptor());mMediaPlayer.prepare();

setDataSource(FileDescptor fd,long offset,long length)

// 需将资源文件放在assets文件夹AssetFileDescriptor fd = getAssets().openFd(&quot;samsara.mp3&quot;);mMediaPlayer.setDataSource(fd.getFileDescriptor(), fd.getStartOffset(), fd.getLength());mMediaPlayer.prepare();
设置完数据源，不要忘记prepare()，尽量使用异步prepareAync()，这样不会阻塞UI线程。
MediaPlayer例子：播放录音播放录音playMedia()和播放测试音频playMediaTest()
public void playMedia() &#123;    if (!mIsPlaying) &#123;        mExecutorService.submit(new Runnable() &#123;            @Override            public void run() &#123;                mIsPlaying = true;                doPlay(getLastFile());            &#125;        &#125;);    &#125; else &#123;        Toast.makeText(mContext, &quot;正在播放&quot;, Toast.LENGTH_SHORT).show();    &#125;&#125; public void playMediaTest() &#123;    if (mHasPausing &amp;&amp; mMediaPlayer != null) &#123;        if (mMediaPlayer.isPlaying()) &#123;            mMediaPlayer.pause();            mBtMediaPlayerTest.setText(&quot;播放测试录音&quot;);        &#125; else &#123;            mMediaPlayer.start();            mBtMediaPlayerTest.setText(&quot;暂停测试录音&quot;);        &#125;        return;    &#125;    if (mIsPlaying) &#123;        Toast.makeText(mContext, &quot;正在播放&quot;, Toast.LENGTH_SHORT).show();    &#125; else &#123;        mBtMediaPlayerTest.setText(&quot;暂停测试录音&quot;);        mExecutorService.submit(new Runnable() &#123;            @Override            public void run() &#123;                if (Build.VERSION.SDK_INT &gt;= Build.VERSION_CODES.KITKAT) &#123;                    mHasPausing = true;                    mIsPlaying = true;                    doPlay(new File(mContext.getExternalFilesDir(Environment.DIRECTORY_DOCUMENTS) + &quot;/MediaRecorderDemo/test.m4a&quot;));                &#125;            &#125;        &#125;);    &#125;&#125;
具体播放方法doPlay()
private void doPlay(File mediaFile) &#123;    try &#123;        // 配置播放器 MediaPlayer        mMediaPlayer = new MediaPlayer();         // 设置声音文件        mMediaPlayer.setDataSource(mediaFile.getAbsolutePath());         // 配置音量,中等音量        mMediaPlayer.setVolume(1, 1);         // 播放是否循环        mMediaPlayer.setLooping(false);         // 设置监听回调 播放完毕        mMediaPlayer.setOnCompletionListener(new MediaPlayer.OnCompletionListener() &#123;            @Override            public void onCompletion(MediaPlayer mp) &#123;                Log.d(TAG, &quot;播放完毕！&quot;);                stopPlayer();            &#125;        &#125;);        mMediaPlayer.setOnErrorListener(new MediaPlayer.OnErrorListener() &#123;            @Override            public boolean onError(MediaPlayer mp, int what, int extra) &#123;                stopPlayer();                Toast.makeText(mContext, &quot;播放失败&quot;, Toast.LENGTH_SHORT).show();                return true;            &#125;        &#125;);         // 设置播放        mMediaPlayer.prepare();        mMediaPlayer.start();         // 异常处理，防止闪退    &#125; catch (Exception e) &#123;        e.printStackTrace();        stopPlayer();    &#125;&#125;
播放结束关闭播放器stopPlayer()
private void stopPlayer()&#123;    mIsPlaying = false;    mMediaPlayer.reset();    mMediaPlayer.release();    mMediaPlayer = null;&#125;

SoundPoolSoundPool支持多个音频文件同时播放（组合音频也是有上限的），延时短，比较适合短促、密集的场景，适合游戏开发中音效播放。
SoundPool实例化方式new SoundPool（适用与5.0以下）
new SoundPool(int maxStreams, int streamType, int srcQuality)// 从android5.0开始此方法被标记为过时// maxStreams: 允许同时播放的流的最大值// streamType: 音频流的类型描述// srcQuality: 采样率转化质量，默认值为0
SoundPool.Builder（从5.0开始支持）
//设置描述音频流信息的属性AudioAttributes abs = new AudioAttributes.Builder()                .setUsage(AudioAttributes.USAGE_MEDIA)                .setContentType(AudioAttributes.CONTENT_TYPE_MUSIC)                .build();SoundPool mSoundPoll = new SoundPool.Builder()                .setMaxStreams(100)   //设置允许同时播放的流的最大值                .setAudioAttributes(abs)                .build();
SoundPool一些重要方法// 几个load方法和上文提到的MediaPlayer基本一致，这里的每个load都会返回一个SoundId值，这个值可以用来播放和卸载音乐。int load(AssetFileDescriptor afd, int priority)int load(Context context, int resId, int priority)int load(String path, int priority)int load(FileDescriptor fd, long offset, long length, int priority) // 通过流id暂停播放final void pause(int streamID) // 播放声音，soundID:音频id（这个id来自load的返回值）； left/rightVolume:左右声道(默认1,1)；loop:循环次数(-1无限循环，0代表不循环)；rate:播放速率(1为标准)，该方法会返回一个streamID,如果StreamID为0表示播放失败，否则为播放成功final int play(int soundID, float leftVolume, float rightVolume, int priority, int loop, float rate) //释放资源(很重要)final void release() //恢复播放final void resume(int streamID) //设置指定id的音频循环播放次数final void setLoop(int streamID, int loop) //设置加载监听(因为加载是异步的，需要监听加载，完成后再播放)void setOnLoadCompleteListener(SoundPool.OnLoadCompleteListener listener) //设置优先级(同时播放个数超过最大值时，优先级低的先被移除)final void setPriority(int streamID, int priority) //设置指定音频的播放速率，0.5~2.0(rate&gt;1:加快播放，反之慢速播放)final void setRate(int streamID, float rate) //停止指定音频播放final void stop(int streamID) //卸载指定音频，soundID来自load()方法的返回值final boolean unload(int soundID) //暂停所有音频的播放final void autoPause() //恢复所有暂停的音频播放final void autoResume()

RingtoneRingtone为铃声、通知和其他类似声音提供快速播放的方法，Ringtone实例需要从RingtoneManager获取，RingtoneManager提供系统铃声列表检索方法。
获取实例// 获取实例方法，均为RingtoneManager类提供 // 1.通过铃声uri获取static Ringtone getRingtone(Context context, Uri ringtoneUri) // 2.通过铃声检索位置获取Ringtone getRingtone(int position)
RingtoneManager几个重要的方法// 两个构造方法RingtoneManager(Activity activity)RingtoneManager(Context context) // 获取指定声音类型(铃声、通知、闹铃等)的默认声音的Uristatic Uri getDefaultUri(int type) // 获取系统所有Ringtone的cursorCursor getCursor() // 获取cursor指定位置的Ringtone uriUri getRingtoneUri(int position) // 判断指定Uri是否为默认铃声static boolean isDefault(Uri ringtoneUri) // 获取指定uri的所属类型static int getDefaultType(Uri defaultRingtoneUri) // 将指定Uri设置为指定声音类型的默认声音static void setActualDefaultRingtoneUri(Context context, int type, Uri ringtoneUri)
Ringtone例子：播放铃声// &lt;uses-permission android:name=&quot;android.permission.MEDIA_CONTENT_CONTROL&quot;/&gt;// &lt;uses-permission android:name=&quot;android.permission.READ_EXTERNAL_STORAGE&quot;/&gt; /** * 播放来电铃声的默认音乐 */private void playRingtoneDefault()&#123;    Uri uri = RingtoneManager.getDefaultUri(RingtoneManager.TYPE_RINGTONE) ;    Ringtone mRingtone = RingtoneManager.getRingtone(this,uri);    mRingtone.play();&#125;  /** * 随机播放一个Ringtone(有可能是提示音、铃声等) */private void ShufflePlayback()&#123;    RingtoneManager manager = new RingtoneManager(this) ;    Cursor cursor = manager.getCursor();    int count = cursor.getCount() ;    int position = (int)(Math.random() * count) ;    Ringtone mRingtone = manager.getRingtone(position) ;    mRingtone.play();&#125;

总结
播放大文件音乐，如WAV无损音频和PCM无压缩音频，可使用更底层的播放方式AudioTrack。它支持流式播放，可以读取（可来自本地和网络）音频流，播放延迟较小。
对于延迟度要求不高，并且希望能够更全面的控制音乐的播放，MediaPlayer比较适合。
声音短小，延迟度小，并且需要几种声音同时播放的场景，适合使用SoundPool。
对于系统类声音的播放和操作，Ringtone更适合。

师说树形结构不论在生活中或者是开发中都是一种非常常见的结构，一个容器对象（如文件夹）下可以存放多种不同的叶子对象或者容器对象，容器对象与叶子对象之间属性差别可能非常大。组合模式为解决此类问题而诞生，它可以让叶子对象和容器对象的使用具有一致性。而组合模式的使用场景就是出现树形结构的地方。比如:文件目录显示，多及目录呈现等树形结构数据的操作。比如：Swing中，Button、Checkbox等组件都是树叶，而Container容器是树枝；比如：文本编辑时，可以单个字编辑，也可以整段编辑，还可以全文编辑；文件复制时，可以一个一个文件复制，也可以整个文件夹复制等等情况。
下面我们以公司的层级结构为例，（选自《大话设计模式》）。


这幅图表示的是部分与整体的关系，因此我们就可以考虑使用组合模式。另外，细细分析图中的结构与组成，我们可以得出以下UML图：

组合模式的关键是定义了一个抽象构件类，它既可以代表叶子，又可以代表容器，而客户端针对该抽象构件类进行编程，无须知道它到底表示的是叶子还是容器，可以对其进行统一处理。同时容器对象与抽象构件类之间还建立一个聚合关联关系，在容器对象中既可以包含叶子，也可以包含容器，以此实现递归组合，形成一个树形结构。


组合模式案例：公司的人事管理，就是领导与被领导。

根据这个人事图，最先设计的 UML 图是：

有没有发现，接口里有好多方法重复了呢？

改进版的 UML 看起来很不错额，最起码干掉了一个 IRoot 接口，整个类图看起来简洁很多而且方法也不重复，但仔细看看，真的改好了吗？

现在我们能理解了吧，上一个类图中 ILeaf 接口中的 getInfo() 方法有重大的嫌疑，你再回去仔细瞧瞧
那现在这个类图行了吗？这个时候我们的理解一下接口的作用了：接口的作用：定义共性，凡是其他接口有的，另一个接口就没必要重复了。

上一图中 ICop 中 getInfo() 是不是和 IBranch 中的 getSubordinateInfo() 功能上重复了，所以还得改，最终才有这个版本的类图。
也许你已经发现，怎么和文章中的第一个图那么相似呢？
对的，这个就是组合模式图了，也就是说，如果你把自己的项目优化优化，也许不知不觉中就在使用了组合模式。


组合模式的几个角色：

抽象构件（Component）：定义参加组合的对象的共有方法和属性，可以定义一些默认的行为或属性，比如 getInfo
叶子构件（Leaf）：叶子对象，其下没有分支。
树枝构件（Composit）：树枝对象，它的作用是组合树枝节点和叶子节点。

组合的适用场合：

你想表示对象的部分 - 整体层次结构。
你希望用户忽略组合对象与单个对象的不同，用户将统一地使用组合结构中的所有对象

优点：

组合模式可以很容易的增加新的构件。
使用组合模式可以使客户端变的很容易设计，因为客户端可以对组合和叶节点一视同仁。

缺点：

使用组合模式后，控制树枝构件的类型不太容易。
用继承的方法来增加新的行为很困难。

PS：如果不太明白组合是什么，可以先了解一下组合与继承

装饰模式定义装饰模式（Decorator）动态地给一个对象添加一些额外的职责。就增加功能来说，装饰模式比生成子类更加灵活。
这里可以举一个生活中的例子，一个蛋糕，在蛋糕上摆上水果，这个蛋糕就变成了水果蛋糕，给这个水果蛋糕插上蜡烛，它就变成了一个生日蛋糕。（这是Head First中的一个例子，个人觉得非常的形象，记忆犹新）。

分析如果我们需要扩展一个类的功能，你会怎么做呢？如果直接修改这个类，我们就违反了开闭原则（对修改关闭，对扩展开放）。
我们可以继承这个类，写一个这个类的子类，用于实现扩展功能，也可以使用组合（将这个类作为成员变量），达到相同的效果。
我们将继承这种关系称为is-a，组合这种关系称为use-a。is-a的耦合程度要高于use-a，所以我们经常可以听到这样的说法：组合优于继承，原因就是这两种关系的耦合程度不同。
装饰模式的核心思想，其实就是用组合代替继承。

图解
这里可以看出，装饰者模式的特点是，装饰者实现了被装饰对象的接口，同时又将被装饰对象作为了成员变量

实例这里举一个咖啡店的例子，咖啡的原料是咖啡豆，我们可以使用咖啡豆和牛奶、蜂蜜、摩卡组合出不同价格、不同口味的咖啡。
这里咖啡豆就是被装饰的对象，也就是图示中的ConcreteComponent，饮品类就是我们抽象出的Component，定义了展示价格和材料两个方法。牛奶、蜂蜜、摩卡是装饰对象，也就是图中的ConcreteDecoratorA、ConcreteDecoratorB。他们抽象出的Decorator，同样定义了展示价格和材料两个方法，具体类图与实现如下：


代码/** * 饮品 */public interface Beverage &#123;    /** 获取描述 */    String getDescription();    /** 获取金额 */    double getPrice();&#125;
/** * 咖啡豆1 */public class CoffeeBean1 implements Beverage &#123;    @Override    public String getDescription() &#123;        return &quot;第一种咖啡豆&quot;;    &#125;    @Override    public double getPrice() &#123;        return 10d;    &#125;&#125;
/** * 咖啡豆2 */public class CoffeeBean2 implements Beverage&#123;    @Override    public String getDescription() &#123;        return &quot;第一种咖啡豆&quot;;    &#125;    @Override    public double getPrice() &#123;        return 12.5d;    &#125;&#125;
/** * 装饰器 */public class Decorator implements Beverage&#123;    protected Beverage coffee;    @Override    public String getDescription() &#123;        return &quot;装饰器，由子类重写方法&quot;;    &#125;    @Override    public double getPrice() &#123;        return 0;    &#125;&#125;
/** * 蜂蜜 */public class Honey extends Decorator &#123;    public Honey(Beverage coffee) &#123;        this.coffee = coffee;    &#125;    @Override    public String getDescription() &#123;        return coffee.getDescription() + &quot;加蜂蜜&quot;;    &#125;    @Override    public double getPrice() &#123;        return coffee.getPrice() + 4.5d;    &#125;&#125;
/** * 牛奶 */public class Milk extends Decorator &#123;    public Milk(Beverage coffee) &#123;        this.coffee = coffee;    &#125;    @Override    public String getDescription() &#123;        return coffee.getDescription() + &quot;加牛奶&quot;;    &#125;    @Override    public double getPrice() &#123;        return coffee.getPrice() + 1.5d;    &#125;&#125;
/** * 摩卡 */public class Mocha extends Decorator &#123;    public Mocha(Beverage coffee) &#123;        this.coffee = coffee;    &#125;    @Override    public String getDescription() &#123;        return coffee.getDescription() + &quot;加摩卡&quot;;    &#125;    @Override    public double getPrice() &#123;        return coffee.getPrice() + 2.5d;    &#125;&#125;
/** * 测试类 */public class Main &#123;    public static void main(String[] args) &#123;        CoffeeBean1 coffee1 = new CoffeeBean1();        CoffeeBean2 coffee2 = new CoffeeBean2();        // 加蜂蜜        Beverage honey = new Honey(coffee1);        // 加摩卡        Beverage mocha = new Mocha(honey);        System.out.println(mocha.getDescription());        System.out.println(mocha.getPrice());        // 加牛奶        Milk milk = new Milk(coffee2);        System.out.println(milk.getDescription());        System.out.println(milk.getPrice());    &#125;&#125;
结果：第一种咖啡豆加蜂蜜加摩卡17.0第一种咖啡豆加牛奶14.0

