📖 开篇语还记得你第一次用数据透视表的情景吗？
“哇，拖拽几下就能统计出各种维度的数据，太神奇了！”今天我们要学的pandas，就是Python的“超级数据透视表”。它不仅能做Excel的所有操作，还能做得更快、更智能、更自动化！
想象一下：
几秒钟就能处理几十万行数据 一行代码完成复杂的分组统计 自动识别数据类型，智能处理缺失值 轻松实现Excel做不到的高级分析
这就是pandas——数据处理的终极效率神器！
🎯 今日学习目标 理解DataFrame概念（Excel表格的升级版） 掌握基本的数据筛选和统计（比数据透视表更快） 实战销售数据分析（自动生成分析报告）
🐼 什么是pandas？pandas = Python Data Analysis Library pandas是Python最专业的数据处理库，就像：
Excel的“超级加强版” 数据透视表的“终极形态” 数据处理的“瑞士军刀”
为什么财务人员要学pandas？| Excel操作 | pandas代码 | 效率提升 || —————— | ——————————————— | —— || 手动筛选10000行数据 | df[df[&#39;金额&#39;]&gt;1000] | 10倍 || 数据透视表统计 | df.groupby(&#39;部门&#39;)[&#39;金额&#39;].sum() | 5倍 || VLOOKUP查找 | df.merge(另一个表, on=&#39;客户ID&#39;) | 8倍 || 手动制作图表 | df.plot(kind=&#39;bar&#39;) | 6倍 |
📊 DataFrame：Excel表格的升级版什么是DataFrame？ 想象Excel工作表：
有行号（1,2,3…） 有列名（A,B,C…或自定义） 每个格子有数据 DataFrame就是一样的概念，但更强大！import pandas as pd# 创建财务DataFrame（就像创建Excel表格）销售数据 = pd.DataFrame(&#123; &#x27;日期&#x27;: [&#x27;2024-01-01&#x27;, &#x27;2024-01-02&#x27;, &#x27;2024-01-03&#x27;, &#x27;2024-01-04&#x27;], &#x27;销售员&#x27;: [&#x27;张三&#x27;, &#x27;李四&#x27;, &#x27;王五&#x27;, &#x27;张三&#x27;], &#x27;客户&#x27;: [&#x27;客户A&#x27;, &#x27;客户B&#x27;, &#x27;客户C&#x27;, &#x27;客户A&#x27;], &#x27;产品&#x27;: [&#x27;产品1&#x27;, &#x27;产品2&#x27;, &#x27;产品1&#x27;, &#x27;产品3&#x27;], &#x27;数量&#x27;: [100, 150, 200, 80], &#x27;单价&#x27;: [50, 80, 50, 120], &#x27;金额&#x27;: [5000, 12000, 10000, 9600]&#125;)print(&quot;销售数据表：&quot;)print(销售数据)
输出结果： 日期 销售员 客户 产品 数量 单价 金额0 2024-01-01 张三 客户A 产品1 100 50 50001 2024-01-02 李四 客户B 产品2 150 80 120002 2024-01-03 王五 客户C 产品1 200 50 100003 2024-01-04 张三 客户A 产品3 80 120 9600 DataFrame vs Excel表格| Excel | DataFrame | 优势 || ————— | ——————————————— | ——- || A1, B1, C1 | df[‘日期’], df[‘销售员’] | 列名更直观 || 筛选：手动点击 | df[df[‘金额’]&gt;10000] | 代码自动化 || 统计：数据透视表 | df.groupby(‘销售员’)[‘金额’].sum() | 一行代码 || 查找：VLOOKUP | df.merge(另一个表) | 更灵活强大 | 读取Excel/CVS文件（数据入口）# 从Excel读取财务数据（就像打开Excel文件）财务数据 = pd.read_excel(&#x27;月度财务报表.xlsx&#x27;)# 或财务数据 = pd.read_csv(&#x27;银行流水.csv&#x27;)print(&quot;数据形状：&quot;, 财务数据.shape) # (行数, 列数)print(&quot;列名：&quot;, 财务数据.columns.tolist())print(&quot;前5行：&quot;)print(财务数据.head()) # 就像Excel的前几行print(&quot;数据类型：&quot;)print(财务数据.dtypes) # 自动识别每列的数据类型 基本属性（了解你的数据）# 继续使用上面的销售数据print(&quot;数据基本信息：&quot;)print(f&quot;形状：&#123;销售数据.shape&#125;&quot;) # (4行, 7列)print(f&quot;列名：&#123;销售数据.columns.tolist()&#125;&quot;)print(f&quot;索引：&#123;销售数据.index.tolist()&#125;&quot;)print(&quot;
每列的数据类型：&quot;)print(销售数据.dtypes)# 日期 object# 销售员 object # 客户 object# 产品 object# 数量 int64# 单价 int64# 金额 int64print(&quot;
数据统计摘要：&quot;)print(销售数据.describe()) # 就像Excel的描述性统计
🔍 数据筛选：比Excel筛选更智能基础筛选（类似Excel的自动筛选）# 筛选出张三的销售记录张三的销售 = 销售数据[销售数据[&#x27;销售员&#x27;] == &#x27;张三&#x27;]print(&quot;张三的销售记录：&quot;)print(张三的销售)# 筛选出金额大于10000的记录大额销售 = 销售数据[销售数据[&#x27;金额&#x27;] &gt; 10000]print(&quot;
大额销售（&gt;10000元）：&quot;)print(大额销售)# 多条件筛选（Excel需要高级筛选，pandas只需要&amp;符号）张三的大额销售 = 销售数据[(销售数据[&#x27;销售员&#x27;] == &#x27;张三&#x27;) &amp; (销售数据[&#x27;金额&#x27;] &gt; 5000)]print(&quot;
张三的大额销售：&quot;)print(张三的大额销售)# 筛选特定日期的销售一月上旬销售 = 销售数据[销售数据[&#x27;日期&#x27;].isin([&#x27;2024-01-01&#x27;, &#x27;2024-01-02&#x27;])]print(&quot;
一月上旬销售：&quot;)print(一月上旬销售) 高级筛选（Excel做不到的筛选）# 字符串筛选产品1销售 = 销售数据[销售数据[&#x27;产品&#x27;].str.contains(&#x27;产品1&#x27;)]print(&quot;产品1的销售记录：&quot;)print(产品1销售)# 多值筛选重点客户 = [&#x27;客户A&#x27;, &#x27;客户C&#x27;]重点客户销售 = 销售数据[销售数据[&#x27;客户&#x27;].isin(重点客户)]print(&quot;
重点客户的销售：&quot;)print(重点客户销售)# 范围筛选中等金额销售 = 销售数据[(销售_data[&#x27;金额&#x27;] &gt;= 8000) &amp; (销售_data[&#x27;金额&#x27;] &lt;= 12000)]print(&quot;
中等金额销售（8000-12000元）：&quot;)print(中等金额销售)
📈 数据统计：比数据透视表更快基础统计（一行代码搞定）# 计算总销售额总销售额 = 销售数据[&#x27;金额&#x27;].sum()print(f&quot;总销售额：&#123;总销售额:,&#125;元&quot;)# 平均销售额平均销售额 = 销售数据[&#x27;金额&#x27;].mean()print(f&quot;平均销售额：&#123;平均销售额:,.2f&#125;元&quot;)# 最大/最小销售额最大销售额 = 销售数据[&#x27;金额&#x27;].max()最小销售额 = 销售_data[&#x27;金额&#x27;].min()print(f&quot;最大销售额：&#123;最大销售额:,&#125;元&quot;)print(f&quot;最小销售额：&#123;最小销售额:,&#125;元&quot;)# 销售数量统计总销售数量 = 销售数据[&#x27;数量&#x27;].sum()平均单价 = 销售数据[&#x27;单价&#x27;].mean()print(f&quot;总销售数量：&#123;总销售数量:,&#125;件&quot;)print(f&quot;平均单价：&#123;平均单价:,.2f&#125;元&quot;) 分组统计（超级数据透视表）# 按销售员统计销售额（类似数据透视表）销售员统计 = 销售_data.groupby(&#x27;销售员&#x27;)[&#x27;金额&#x27;].sum()print(&quot;各销售员销售额：&quot;)print(销售员统计)# 按客户统计（多列统计）客户统计 = 销售数据.groupby(&#x27;客户&#x27;).agg(&#123; &#x27;金额&#x27;: &#x27;sum&#x27;, # 总金额 &#x27;数量&#x27;: &#x27;sum&#x27;, # 总数量 &#x27;单价&#x27;: &#x27;mean&#x27; # 平均单价&#125;)print(&quot;
各客户购买统计：&quot;)print(客户统计)# 多层分组（销售员+客户）多层统计 = 销售数据.groupby([&#x27;销售员&#x27;, &#x27;客户&#x27;])[&#x27;金额&#x27;].sum()print(&quot;
销售员-客户销售额：&quot;)print(多层统计)# 重置索引，让结果更美观多层统计_df = 销售数据.groupby([&#x27;销售员&#x27;, &#x27;客户&#x27;]).agg(&#123; &#x27;金额&#x27;: &#x27;sum&#x27;, &#x27;数量&#x27;: &#x27;sum&#x27;&#125;).reset_index()print(&quot;
销售员-客户统计表：&quot;)print(多层统计_df)
🧮 财务实战：销售数据分析 版本1.0：基础销售分析
# 销售数据分析 - 基础版print(&quot;=== 销售数据分析系统 ===&quot;)import pandas as pdimport numpy as np# 创建更真实的销售数据np.random.seed(42) # 保证结果可重复# 生成月度销售数据日期范围 = pd.date_range(&#x27;2024-01-01&#x27;, &#x27;2024-01-31&#x27;, freq=&#x27;D&#x27;)销售员列表 = [&#x27;张三&#x27;, &#x27;李四&#x27;, &#x27;王五&#x27;, &#x27;赵六&#x27;, &#x27;钱七&#x27;]客户列表 = [&#x27;客户A&#x27;, &#x27;客户B&#x27;, &#x27;客户C&#x27;, &#x27;客户D&#x27;, &#x27;客户E&#x27;]产品列表 = [&#x27;产品1&#x27;, &#x27;产品2&#x27;, &#x27;产品3&#x27;, &#x27;产品4&#x27;]销售数据 = []for 日期 in 日期范围: # 每天随机2-5笔销售 日销售笔数 = np.random.randint(2, 6) for _ in range(日销售笔数): 销售员 = np.random.choice(销售员_list) 客户 = np.random.choice(客户_list) 产品 = np.random.choice(产品列表) 数量 = np.random.randint(10, 201) 单价 = np.random.randint(50, 201) 销售数据.append(&#123; &#x27;日期&#x27;: 日期, &#x27;销售员&#x27;: 销售员, &#x27;客户&#x27;: 客户, &#x27;产品&#x27;: 产品, &#x27;数量&#x27;: 数量, &#x27;单价&#x27;: 单价, &#x27;金额&#x27;: 数量 * 单价 &#125;)# 创建DataFramedf = pd.DataFrame(销售数据)df[&#x27;日期&#x27;] = pd.to_datetime(df[&#x27;日期&#x27;]) # 确保日期格式正确print(&quot;📊 销售数据概览：&quot;)print(f&quot;数据形状：&#123;df.shape&#125;&quot;)print(f&quot;日期范围：&#123;df[&#x27;日期&#x27;].min()&#125; 到 &#123;df[&#x27;日期&#x27;].max()&#125;&quot;)print(f&quot;总销售额：&#123;df[&#x27;金额&#x27;].sum():,.2f&#125;元&quot;)# 基础分析print(&quot;
=== 基础销售分析 ===&quot;)# 1. 日销售额统计日销售额 = df.groupby(&#x27;日期&#x27;)[&#x27;金额&#x27;].sum()print(f&quot;
📅 日销售额统计（前5天）：&quot;)print(日销售额.head())# 2. 销售员业绩排名销售员业绩 = df.groupby(&#x27;销售员&#x27;).agg(&#123; &#x27;金额&#x27;: &#x27;sum&#x27;, &#x27;数量&#x27;: &#x27;sum&#x27;, &#x27;日期&#x27;: &#x27;count&#x27; # 销售笔数&#125;).round(2)销售员业绩.columns = [&#x27;总销售额&#x27;, &#x27;总数量&#x27;, &#x27;销售笔数&#x27;]销售员业绩 = 销售员业绩.sort_values(&#x27;总销售额&#x27;, ascending=False)print(f&quot;
🏆 销售员业绩排名：&quot;)print(销售员业绩)# 3. 客户购买分析客户分析 = df.groupby(&#x27;客户&#x27;).agg(&#123; &#x27;金额&#x27;: [&#x27;sum&#x27;, &#x27;mean&#x27;, &#x27;count&#x27;], &#x27;数量&#x27;: &#x27;sum&#x27;&#125;).round(2)客户分析.columns = [&#x27;总购买额&#x27;, &#x27;平均购买额&#x27;, &#x27;购买次数&#x27;, &#x27;总数量&#x27;]客户分析 = 客户分析.sort_values(&#x27;总购买额&#x27;, ascending=False)print(f&quot;
💰 客户购买分析：&quot;)print(客户分析)# 4. 产品销售分析产品分析 = df.groupby(&#x27;产品&#x27;).agg(&#123; &#x27;金额&#x27;: &#x27;sum&#x27;, &#x27;数量&#x27;: &#x27;sum&#x27;, &#x27;单价&#x27;: &#x27;mean&#x27;&#125;).round(2)产品分析 = 产品分析.sort_values(&#x27;金额&#x27;, ascending=False)产品分析.columns = [&#x27;销售额&#x27;, &#x27;销售数量&#x27;, &#x27;平均单价&#x27;]print(f&quot;
📦 产品销售分析：&quot;)print(产品分析)
版本2.0：高级分析功能
# 销售数据分析 - 高级版print(&quot;
=== 高级销售分析 ===&quot;)# 1. 时间序列分析print(&quot;
📈 时间序列分析：&quot;)# 按周统计df[&#x27;周&#x27;] = df[&#x27;日期&#x27;].dt.isocalendar().week周销售额 = df.groupby(&#x27;周&#x27;)[&#x27;金额&#x27;].agg([&#x27;sum&#x27;, &#x27;mean&#x27;, &#x27;count&#x27;])周销售额.columns = [&#x27;周销售总额&#x27;, &#x27;日均销售额&#x27;, &#x27;销售天数&#x27;]print(&quot;按周销售统计：&quot;)print(周销售额)# 工作日vs周末分析df[&#x27;是否周末&#x27;] = df[&#x27;日期&#x27;].dt.dayofweek &gt;= 5周末分析 = df.groupby(&#x27;是否周末&#x27;)[&#x27;金额&#x27;].agg([&#x27;sum&#x27;, &#x27;mean&#x27;, &#x27;count&#x27;])周末分析.index = [&#x27;工作日&#x27;, &#x27;周末&#x27;]周末分析.columns = [&#x27;销售额&#x27;, &#x27;平均日销售额&#x27;, &#x27;天数&#x27;]print(&quot;
工作日vs周末销售对比：&quot;)print(周末分析)# 2. 交叉分析（数据透视表）print(&quot;
📊 交叉分析：&quot;)# 销售员-客户交叉表交叉表 = pd.crosstab(df[&#x27;销售员&#x27;], df[&#x27;客户&#x27;], values=df[&#x27;金额&#x27;], aggfunc=&#x27;sum&#x27;)交叉表 = 交叉表.fillna(0) # 填充NaN为0print(&quot;销售员-客户销售交叉表（金额）：&quot;)print(交叉表)# 销售员-产品交叉表（显示多个指标）透视表 = df.pivot_table(values=&#x27;金额&#x27;, index=&#x27;销售员&#x27;, columns=&#x27;产品&#x27;, aggfunc=&#x27;sum&#x27;, fill_value=0)print(&quot;
销售员-产品销售透视表：&quot;)print(透视表)# 3. 排名和百分比分析print(&quot;
🏅 排名分析：&quot;)# 销售员日销售额排名日销售员排名 = df.groupby([&#x27;日期&#x27;, &#x27;销售员&#x27;])[&#x27;金额&#x27;].sum().reset_index()日销售员排名[&#x27;排名&#x27;] =日销售员排名.groupby(&#x27;日期&#x27;)[&#x27;金额&#x27;].rank(ascending=False, method=&#x27;dense&#x27;)print(&quot;每日销售员排名（前10名）：&quot;)print(日销售员排名.head(10))# 4. 异常检测print(&quot;
⚠️ 异常检测：&quot;)# 检测异常高销售额（超过平均值2个标准差）平均日销售额 = df.groupby(&#x27;日期&#x27;)[&#x27;金额&#x27;].sum().mean()日销售额标准差 = df.groupby(&#x27;日期&#x27;)[&#x27;金额&#x27;].sum().std()异常阈值 = 平均日销售额 + 2 * 日销售额标准差异常日期 = df.groupby(&#x27;日期&#x27;)[&#x27;金额&#x27;].sum()[df.groupby(&#x27;日期&#x27;)[&#x27;金额&#x27;].sum() &gt; 异常阈值]if len(异常日期) &gt; 0: print(&quot;异常高销售额日期：&quot;) for 日期, 金额 in 异常日期.items(): print(f&quot; &#123;日期.strftime(&#x27;%Y-%m-%d&#x27;)&#125;：&#123;金额:,.2f&#125;元（超出正常范围）&quot;)else: print(&quot; 未发现异常高销售额日期&quot;)# 检测异常单价产品单价统计 = df.groupby(&#x27;产品&#x27;)[&#x27;单价&#x27;].agg([&#x27;mean&#x27;, &#x27;std&#x27;])for 产品 in 产品单价统计.index: 平均单价 = 产品单价统计.loc[产品, &#x27;mean&#x27;] 标准差 = 产品单价统计.loc[产品, &#x27;std&#x27;] if pd.notna(标准差) and 标准差 &gt; 0: 异常单价阈值 = 平均单价 + 2 * 标准差 异常记录 = df[(df[&#x27;产品&#x27;] == 产品) &amp; (df[&#x27;单价&#x27;] &gt; 异常单价阈值)] if len(异常记录) &gt; 0: print(f&quot;
&#123;产品&#125;异常高单价记录：&quot;) for _, 记录 in 异常记录.iterrows(): print(f&quot; &#123;记录[&#x27;日期&#x27;].strftime(&#x27;%Y-%m-%d&#x27;)&#125;：单价&#123;记录[&#x27;单价&#x27;]&#125;元（平均&#123;平均单价:.0f&#125;元）&quot;)
版本3.0：专业分析报告
# 销售数据分析 - 专业版print(&quot;
=== 专业销售分析报告 ===&quot;)from openpyxl import Workbookfrom openpyxl.styles import Font, PatternFill, Alignmentfrom openpyxl.chart import LineChart, BarChart, Referenceimport matplotlib.pyplot as pltdef 生成专业销售报告(df, 文件名=&quot;销售分析报告.xlsx&quot;): &quot;&quot;&quot;生成专业的销售分析报告&quot;&quot;&quot; # 创建工作簿 wb = Workbook() # 1. 执行汇总表 汇总表 = wb.active 汇总表.title = &quot;执行汇总&quot; # 标题 汇总表[&quot;A1&quot;] = &quot;销售数据分析报告&quot; 汇总表[&quot;A1&quot;].font = Font(size=18, bold=True, color=&quot;FFFFFF&quot;) 汇总表[&quot;A1&quot;].fill = PatternFill(start_color=&quot;366092&quot;, end_color=&quot;366092&quot;, fill_type=&quot;solid&quot;) 汇总表.merge_cells(&quot;A1:H1&quot;) 汇总表[&quot;A1&quot;].alignment = Alignment(horizontal=&quot;center&quot;) # 基本信息 汇总表[&quot;A3&quot;] = f&quot;报告生成时间：&#123;datetime.now().strftime(&#x27;%Y-%m-%d %H:%M:%S&#x27;)&#125;&quot; 汇总表[&quot;A4&quot;] = f&quot;分析期间：&#123;df[&#x27;日期&#x27;].min().strftime(&#x27;%Y-%m-%d&#x27;)&#125; 至 &#123;df[&#x27;日期&#x27;].max().strftime(&#x27;%Y-%m-%d&#x27;)&#125;&quot; 汇总表[&quot;A5&quot;] = f&quot;数据记录数：&#123;len(df)&#125;笔&quot; # 关键指标 关键指标 = [ [&quot;关键指标&quot;, &quot;数值&quot;, &quot;单位&quot;, &quot;说明&quot;], [&quot;总销售额&quot;, f&quot;&#123;df[&#x27;金额&#x27;].sum():,.2f&#125;&quot;, &quot;元&quot;, &quot;期间内所有销售金额合计&quot;], [&quot;平均日销售额&quot;, f&quot;&#123;df.groupby(&#x27;日期&#x27;)[&#x27;金额&#x27;].sum().mean():,.2f&#125;&quot;, &quot;元&quot;, &quot;日均销售水平&quot;], [&quot;总销售数量&quot;, f&quot;&#123;df[&#x27;数量&#x27;].sum():,&#125;&quot;, &quot;件&quot;, &quot;期间内所有销售数量合计&quot;], [&quot;平均单价&quot;, f&quot;&#123;df[&#x27;单价&#x27;].mean():.2f&#125;&quot;, &quot;元&quot;, &quot;所有产品的平均单价&quot;], [&quot;销售笔数&quot;, f&quot;&#123;len(df):,&#125;&quot;, &quot;笔&quot;, &quot;期间内总销售笔数&quot;], [&quot;客单价&quot;, f&quot;&#123;df[&#x27;金额&#x27;].mean():.2f&#125;&quot;, &quot;元&quot;, &quot;平均每笔销售金额&quot;], [&quot;销售员数量&quot;, f&quot;&#123;df[&#x27;销售员&#x27;].nunique()&#125;&quot;, &quot;人&quot;, &quot;参与销售的销售员人数&quot;], [&quot;客户数量&quot;, f&quot;&#123;df[&#x27;客户&#x27;].nunique()&#125;&quot;, &quot;个&quot;, &quot;购买产品的客户数量&quot;], [&quot;产品种类&quot;, f&quot;&#123;df[&#x27;产品&#x27;].nunique()&#125;&quot;, &quot;种&quot;, &quot;销售的产品种类数量&quot;] ] 起始行 = 7 for 行号, 数据行 in enumerate(关键指标, 起始行): for 列号, 值 in enumerate(数据行, 1): 单元格 = 汇总表.cell(row=行号, column=列号, value=值) if 行号 == 起始行: 单元格.font = Font(bold=True) 单元格.fill = PatternFill(start_color=&quot;D9E2F3&quot;, end_color=&quot;D9E2F3&quot;, fill_type=&quot;solid&quot;) # 调整列宽 for 列 in [&quot;A&quot;, &quot;B&quot;, &quot;C&quot;, &quot;D&quot;]: 汇总表.column_dimensions[列].width = 20 # 2. 销售员业绩表 业绩表 = wb.create_sheet(&quot;销售员业绩&quot;) 业绩表[&quot;A1&quot;] = &quot;销售员业绩排名&quot; 业绩表[&quot;A1&quot;].font = Font(size=14, bold=True) # 获取业绩数据 销售员业绩 = df.groupby(&#x27;销售员&#x27;).agg(&#123; &#x27;金额&#x27;: [&#x27;sum&#x27;, &#x27;mean&#x27;, &#x27;count&#x27;], &#x27;数量&#x27;: &#x27;sum&#x27; &#125;).round(2) 销售员业绩.columns = [&#x27;总销售额&#x27;, &#x27;平均销售额&#x27;, &#x27;销售笔数&#x27;, &#x27;总数量&#x27;] 销售员业绩 = 销售员业绩.sort_values(&#x27;总销售额&#x27;, ascending=False) 销售员业绩[&#x27;排名&#x27;] = range(1, len(销售员业绩) + 1) # 写入表头 表头 = [&#x27;排名&#x27;, &#x27;销售员&#x27;, &#x27;总销售额&#x27;, &#x27;平均销售额&#x27;, &#x27;销售笔数&#x27;, &#x27;总数量&#x27;, &#x27;占比&#x27;] for 列号, 标题 in enumerate(表头, 1): 单元格 = 业绩表.cell(row=3, column=列号, value=标题) 单元格.font = Font(bold=True) 单元格.fill = PatternFill(start_color=&quot;E8F4FD&quot;, end_color=&quot;E8F4FD&quot;, fill_type=&quot;solid&quot;) # 写入数据 总销售额 = df[&#x27;金额&#x27;].sum() for 行号, (销售员, 数据) in enumerate(销售员业绩.iterrows(), 4): 业绩表.cell(row=行号, column=1, value=数据[&#x27;排名&#x27;]) 业绩表.cell(row=行号, column=2, value=销售员) 业绩表.cell(row=行号, column=3, value=数据[&#x27;总销售额&#x27;]) 业绩表.cell(row=行号, column=4, value=数据[&#x27;平均销售额&#x27;]) 业绩表.cell(row=行号, column=5, value=数据[&#x27;销售笔数&#x27;]) 业绩表.cell(row=行号, column=6, value=数据[&#x27;总数量&#x27;]) 业绩表.cell(row=行号, column=7, value=f&quot;&#123;数据[&#x27;总销售额&#x27;]/总销售额*100:.1f&#125;%&quot;) # 添加图表数据 图表数据起始行 = len(销售员业绩) + 6 业绩表.cell(row=图表数据起始行, column=1, value=&quot;图表数据&quot;) 业绩表.cell(row=图表数据起始行, column=1).font = Font(bold=True) for i, (销售员, 数据) in enumerate(销售员业绩.iterrows(), 图表数据起始行 + 1): 业绩表.cell(row=i, column=1, value=销售员) 业绩表.cell(row=i, column=2, value=数据[&#x27;总销售额&#x27;]) # 创建柱状图 图表 = BarChart() 图表.title = &quot;销售员销售额对比&quot; 图表.style = 10 图表.y_axis.title = &#x27;销售额（元）&#x27; 图表.x_axis.title = &#x27;销售员&#x27; 数据 = Reference(业绩表, min_col=2, min_row=图表数据起始行 + 1, max_row=图表数据起始行 + len(销售员业绩), max_col=2) 分类 = Reference(业绩表, min_col=1, min_row=图表数据起始行 + 1, max_row=图表数据起始行 + len(销售员业绩)) 图表.add_data(data) 图表.set_categories(分类) 业绩表.add_chart(图表, &quot;I3&quot;) # 3. 客户分析表 客户表 = wb.create_sheet(&quot;客户分析&quot;) 客户表[&quot;A1&quot;] = &quot;客户购买分析&quot; 客户表[&quot;A1&quot;].font = Font(size=14, bold=True) # 客户分析数据 客户分析 = df.groupby(&#x27;客户&#x27;).agg(&#123; &#x27;金额&#x27;: [&#x27;sum&#x27;, &#x27;mean&#x27;, &#x27;count&#x27;], &#x27;数量&#x27;: &#x27;sum&#x27; &#125;).round(2) 客户分析.columns = [&#x27;总购买额&#x27;, &#x27;平均购买额&#x27;, &#x27;购买次数&#x27;, &#x27;总数量&#x27;] 客户分析 = 客户分析.sort_values(&#x27;总购买额&#x27;, ascending=False) # 写入数据 表头 = [&#x27;客户&#x27;, &#x27;总购买额&#x27;, &#x27;平均购买额&#x27;, &#x27;购买次数&#x27;, &#x27;总数量&#x27;, &#x27;客单价&#x27;, &#x27;等级&#x27;] for 列号, 标题 in enumerate(表头, 1): 单元格 = 客户表.cell(row=3, column=列号, value=标题) 单元格.font = Font(bold=True) 单元格.fill = PatternFill(start_color=&quot;E8F4FD&quot;, end_color=&quot;E8F4FD&quot;, fill_type=&quot;solid&quot;) for 行号, (客户, 数据) in enumerate(客户分析.iterrows(), 4): 客户表.cell(row=行号, column=1, value=客户) 客户表.cell(row=行号, column=2, value=数据[&#x27;总购买额&#x27;]) 客户表.cell(row=行号, column=3, value=数据[&#x27;平均购买额&#x27;]) 客户表.cell(row=行号, column=4, value=数据[&#x27;购买次数&#x27;]) 客户表.cell(row=行号, column=5, value=数据[&#x27;总数量&#x27;]) 客户表.cell(row=行号, column=6, value=数据[&#x27;总购买额&#x27;]/数据[&#x27;购买次数&#x27;]) # 客户分级 if 数据[&#x27;总购买额&#x27;] &gt; 20000: 等级 = &quot;VIP客户&quot; elif 数据[&#x27;总购买额&#x27;] &gt; 10000: 等级 = &quot;重点客户&quot; elif 数据[&#x27;总购买额&#x27;] &gt; 5000: 等级 = &quot;普通客户&quot; else: 等级 = &quot;小客户&quot; 客户表.cell(row=行号, column=7, value=等级) # 4. 时间分析表 时间表 = wb.create_sheet(&quot;时间分析&quot;) 时间表[&quot;A1&quot;] = &quot;时间序列分析&quot; 时间表[&quot;A1&quot;].font = Font(size=14, bold=True) # 日销售额 日销售额 = df.groupby(&#x27;日期&#x27;)[&#x27;金额&#x27;].agg([&#x27;sum&#x27;, &#x27;count&#x27;]).reset_index() 日销售额.columns = [&#x27;日期&#x27;, &#x27;销售额&#x27;, &#x27;笔数&#x27;] # 写入数据 时间表[&quot;A3&quot;] = &quot;日销售额统计&quot; 时间表[&quot;A3&quot;].font = Font(bold=True) 表头 = [&#x27;日期&#x27;, &#x27;销售额&#x27;, &#x27;笔数&#x27;, &#x27;日均单价&#x27;] for 列号, 标题 in enumerate(表头, 1): 单元格 = 时间表.cell(row=5, column=列号, value=标题) 单元格.font = Font(bold=True) for 行号, (_, 数据) in enumerate(日销售额.iterrows(), 6): 时间表.cell(row=行号, column=1, value=数据[&#x27;日期&#x27;].strftime(&#x27;%m-%d&#x27;)) 时间表.cell(row=行号, column=2, value=数据[&#x27;销售额&#x27;]) 时间表.cell(row=行号, column=3, value=数据[&#x27;笔数&#x27;]) 时间表.cell(row=行号, column=4, value=数据[&#x27;销售额&#x27;]/数据[&#x27;笔数&#x27;] if 数据[&#x27;笔数&#x27;] &gt; 0 else 0) # 创建折线图 折线图 = LineChart() 折线图.title = &quot;日销售额趋势&quot; 折线图.style = 2 折线图.y_axis.title = &#x27;销售额（元）&#x27; 折线图.x_axis.title = &#x27;日期&#x27; 数据 = Reference(时间表, min_col=2, min_row=6, max_row=6 + len(日销售额), max_col=2) 分类 = Reference(时间表, min_col=1, min_row=6, max_row=6 + len(日销售额)) 折线图.add_data(data, titles_from_data=True) 折线图.set_categories(分类) 时间表.add_chart(折线图, &quot;F5&quot;) # 保存文件 wb.save(文件名) print(f&quot;✅ 专业销售报告已生成：&#123;文件名&#125;&quot;) return 文件名# 生成专业报告专业报告 = 生成专业销售报告(df)# 额外：生成数据可视化图表（matplotlib）print(&quot;
📊 生成数据可视化图表...&quot;)plt.rcParams[&#x27;font.sans-serif&#x27;] = [&#x27;SimHei&#x27;] # 设置中文字体plt.rcParams[&#x27;axes.unicode_minus&#x27;] = False # 正确显示负号# 1. 销售员业绩柱状图plt.figure(figsize=(10, 6))销售员业绩 = df.groupby(&#x27;销售员&#x27;)[&#x27;金额&#x27;].sum().sort_values(ascending=False)plt.bar(销售员业绩.index, 销售员业绩.values, color=&#x27;skyblue&#x27;)plt.title(&#x27;销售员业绩对比&#x27;, fontsize=16)plt.xlabel(&#x27;销售员&#x27;, fontsize=12)plt.ylabel(&#x27;销售额（元）&#x27;, fontsize=12)plt.xticks(rotation=45)for i, v in enumerate(销售员业绩.values): plt.text(i, v + 1000, f&#x27;&#123;v:,.0f&#125;&#x27;, ha=&#x27;center&#x27;, va=&#x27;bottom&#x27;)plt.tight_layout()plt.savefig(&#x27;销售员业绩对比.png&#x27;, dpi=300, bbox_inches=&#x27;tight&#x27;)plt.close()# 2. 客户购买额饼图plt.figure(figsize=(8, 8))客户购买 = df.groupby(&#x27;客户&#x27;)[&#x27;金额&#x27;].sum()plt.pie(客户购买.values, labels=客户购买.index, autopct=&#x27;%1.1f%%&#x27;, startangle=90)plt.title(&#x27;客户购买分布&#x27;, fontsize=16)plt.axis(&#x27;equal&#x27;)plt.savefig(&#x27;客户购买分布.png&#x27;, dpi=300, bbox_inches=&#x27;tight&#x27;)plt.close()# 3. 日销售额趋势图plt.figure(figsize=(12, 6))日销售额 = df.groupby(&#x27;日期&#x27;)[&#x27;金额&#x27;].sum()plt.plot(日销售额.index, 日销售额.values, marker=&#x27;o&#x27;, linewidth=2, markersize=4)plt.title(&#x27;日销售额趋势&#x27;, fontsize=16)plt.xlabel(&#x27;日期&#x27;, fontsize=12)plt.ylabel(&#x27;销售额（元）&#x27;, fontsize=12)plt.grid(True, alpha=0.3)plt.xticks(rotation=45)plt.tight_layout()plt.savefig(&#x27;日销售额趋势.png&#x27;, dpi=300, bbox_inches=&#x27;tight&#x27;)plt.close()print(&quot;✅ 可视化图表已生成！&quot;)
🏃‍♀️ 进阶小挑战 挑战1：财务比率分析
# 财务比率分析工具print(&quot;=== 财务比率分析工具 ===&quot;)def 计算财务比率(资产负债表, 利润表): &quot;&quot;&quot; 计算常用财务比率 参数： 资产负债表：包含资产、负债、所有者权益的DataFrame 利润表：包含收入、成本、费用的DataFrame 返回： 财务比率字典 &quot;&quot;&quot; # 从数据中提取关键数据 总资产 = 资产负债表[&#x27;总资产&#x27;].iloc[-1] 总负债 = 资产负债表[&#x27;总负债&#x27;].iloc[-1] 所有者权益 = 资产负债表[&#x27;所有者权益&#x27;].iloc[-1] 流动资产 = 资产负债表[&#x27;流动资产&#x27;].iloc[-1] 流动负债 = 资产负债表[&#x27;流动负债&#x27;].iloc[-1] 存货 = 资产负债表[&#x27;存货&#x27;].iloc[-1] 应收账款 = 资产负债表[&#x27;应收账款&#x27;].iloc[-1] 营业收入 = 利润表[&#x27;营业收入&#x27;].iloc[-1] 营业成本 = 利润表[&#x27;营业成本&#x27;].iloc[-1] 净利润 = 利润表[&#x27;净利润&#x27;].iloc[-1] 利息费用 = 利润表.get(&#x27;利息费用&#x27;, pd.Series([0])).iloc[-1] # 计算财务比率 财务比率 = &#123; # 偿债能力比率 &quot;流动比率&quot;: 流动资产 / 流动负债 if 流动负债 &gt; 0 else None, &quot;速动比率&quot;: (流动资产 - 存货) / 流动负债 if 流动负债 &gt; 0 else None, &quot;资产负债率&quot;: 总负债 / 总资产 if 总资产 &gt; 0 else None, &quot;权益乘数&quot;: 总资产 / 所有者权益 if 所有者权益 &gt; 0 else None, # 营运能力比率 &quot;应收账款周转率&quot;: 营业收入 / 应收账款 if 应收账款 &gt; 0 else None, &quot;存货周转率&quot;: 营业成本 / 存货 if 存货 &gt; 0 else None, &quot;总资产周转率&quot;: 营业收入 / 总资产 if 总资产 &gt; 0 else None, # 盈利能力比率 &quot;销售净利率&quot;: 净利润 / 营业收入 if 营业收入 &gt; 0 else None, &quot;资产净利率&quot;: 净利润 / 总资产 if 总资产 &gt; 0 else None, &quot;净资产收益率&quot;: 净利润 / 所有者权益 if 所有者权益 &gt; 0 else None, # 杠杆比率 &quot;利息保障倍数&quot;: (净利润 + 利息费用) / 利息费用 if 利息费用 &gt; 0 else None, &quot;负债权益比&quot;: 总负债 / 所有者权益 if 所有者权益 &gt; 0 else None &#125; return 财务比率# 创建示例财务数据资产负债表 = pd.DataFrame(&#123; &#x27;项目&#x27;: [&#x27;流动资产&#x27;, &#x27;非流动资产&#x27;, &#x27;总资产&#x27;, &#x27;流动负债&#x27;, &#x27;非流动负债&#x27;, &#x27;总负债&#x27;, &#x27;所有者权益&#x27;], &#x27;2023年末&#x27;: [500000, 800000, 1300000, 300000, 200000, 500000, 800000], &#x27;2024年末&#x27;: [600000, 900000, 1500000, 350000, 250000, 600000, 900000]&#125;)利润表 = pd.DataFrame(&#123; &#x27;项目&#x27;: [&#x27;营业收入&#x27;, &#x27;营业成本&#x27;, &#x27;营业利润&#x27;, &#x27;净利润&#x27;, &#x27;利息费用&#x27;], &#x27;2024年度&#x27;: [2000000, 1500000, 400000, 300000, 50000]&#125;)# 计算财务比率比率结果 = 计算财务比率(资产负债表, 利润表)print(&quot;📊 财务比率分析结果：&quot;)print(&quot;
偿债能力比率：&quot;)for 比率, 数值 in 比率结果.items(): if 比率 in [&quot;流动比率&quot;, &quot;速动比率&quot;, &quot;资产负债率&quot;, &quot;权益乘数&quot;] and 数值 is not None: print(f&quot; &#123;比率&#125;：&#123;数值:.2f&#125;&quot;)print(&quot;
营运能力比率：&quot;)for 比率, 数值 in 比率结果.items(): if 比率 in [&quot;应收账款周转率&quot;, &quot;存货周转率&quot;, &quot;总资产周转率&quot;] and 数值 is not None: print(f&quot; &#123;比率&#125;：&#123;数值:.2f&#125;&quot;)print(&quot;
盈利能力比率：&quot;)for 比率, 数值 in 比率结果.items(): if 比率 in [&quot;销售净利率&quot;, &quot;资产净利率&quot;, &quot;净资产收益率&quot;] and 数值 is not None: print(f&quot; &#123;比率&#125;：&#123;数值:.2%&#125;&quot;)# 比率分析和建议print(f&quot;
💡 财务分析建议：&quot;)if 比率结果[&#x27;流动比率&#x27;] and 比率结果[&#x27;流动比率&#x27;] &lt; 1.5: print(&quot;⚠️ 流动比率偏低，短期偿债能力需要关注&quot;)elif 比率结果[&#x27;流动比率&#x27;] and 比率结果[&#x27;流动比率&#x27;] &gt; 3: print(&quot;💡 流动比率偏高，可能存在资金闲置&quot;)if 比率结果[&#x27;资产负债率&#x27;] and 比率结果[&#x27;资产负债率&#x27;] &gt; 0.7: print(&quot;⚠️ 资产负债率偏高，财务风险较大&quot;)elif 比率结果[&#x27;资产负债率&#x27;] and 比率结果[&#x27;资产负债率&#x27;] &lt; 0.3: print(&quot;💡 资产负债率偏低，可以考虑适当增加杠杆&quot;)if 比率结果[&#x27;净资产收益率&#x27;] and 比率结果[&#x27;净资产收益率&#x27;] &gt; 0.15: print(&quot;✅ 净资产收益率良好，股东回报较高&quot;)elif 比率结果[&#x27;净资产收益率&#x27;] and 比率结果[&#x27;净资产收益率&#x27;] &lt; 0.1: print(&quot;⚠️ 净资产收益率偏低，盈利能力需要提升&quot;)
挑战2：预算差异分析
# 预算差异分析系统print(&quot;=== 预算差异分析系统 ===&quot;)def 预算差异分析(实际数据, 预算数据, 分析维度=[&#x27;部门&#x27;, &#x27;项目&#x27;]): &quot;&quot;&quot; 分析实际数据与预算数据的差异 参数： 实际数据：实际发生的数据DataFrame 预算数据：预算数据DataFrame 分析维度：按哪些维度进行分析 返回： 差异分析结果 &quot;&quot;&quot; # 确保数据格式一致 实际数据 = 实际数据.copy() 预算数据 = 预算数据.copy() # 按分析维度汇总 实际汇总 = 实际数据.groupby(分析维度)[&#x27;金额&#x27;].sum().reset_index() 实际汇总.columns = 分析维度 + [&#x27;实际金额&#x27;] 预算汇总 = 预算数据.groupby(分析维度)[&#x27;金额&#x27;].sum().reset_index() 预算汇总.columns = 分析维度 + [&#x27;预算金额&#x27;] # 合并数据 差异分析 = pd.merge(实际汇总, 预算汇总, on=分析维度, how=&#x27;outer&#x27;).fillna(0) # 计算差异 差异分析[&#x27;差异金额&#x27;] = 差异分析[&#x27;实际金额&#x27;] - 差异分析[&#x27;预算金额&#x27;] 差异分析[&#x27;差异率&#x27;] = 差异分析[&#x27;差异金额&#x27;] / (差异分析[&#x27;预算金额&#x27;] + 1e-10) * 100 # 加小值避免除零 差异分析[&#x27;完成率&#x27;] = 差异分析[&#x27;实际金额&#x27;] / (差异分析[&#x27;预算金额&#x27;] + 1e-10) * 100 # 差异分级 def 差异分级(差异率): if abs(差异率) &lt;= 5: return &quot;正常&quot; elif abs(差异率) &lt;= 10: return &quot;轻微差异&quot; elif abs(差异率) &lt;= 20: return &quot;显著差异&quot; else: return &quot;重大差异&quot; 差异分析[&#x27;差异级别&#x27;] = 差异分析[&#x27;差异率&#x27;].apply(差异分级) return 差异分析def 生成预算分析报告(差异分析结果, 文件名=&quot;预算差异分析报告.xlsx&quot;): &quot;&quot;&quot;生成预算差异分析报告&quot;&quot;&quot; # 创建Excel工作簿 wb = Workbook() # 1. 差异汇总表 汇总表 = wb.active 汇总表.title = &quot;预算差异汇总&quot; # 标题 汇总表[&quot;A1&quot;] = &quot;预算差异分析报告&quot; 汇总表[&quot;A1&quot;].font = Font(size=16, bold=True) 汇总表.merge_cells(&quot;A1:F1&quot;) # 写入差异数据 表头 = [&#x27;部门&#x27;, &#x27;项目&#x27;, &#x27;实际金额&#x27;, &#x27;预算金额&#x27;, &#x27;差异金额&#x27;, &#x27;差异率&#x27;, &#x27;完成率&#x27;, &#x27;差异级别&#x27;] for 列号, 标题 in enumerate(表头, 1): 单元格 = 汇总表.cell(row=3, column=列号, value=标题) 单元格.font = Font(bold=True) 单元格.fill = PatternFill(start_color=&quot;E8F4FD&quot;, end_color=&quot;E8F4FD&quot;, fill_type=&quot;solid&quot;) for 行号, (_, 数据) in enumerate(差异分析结果.iterrows(), 4): for 列号, 列名 in enumerate(表头, 1): if 列名 == &#x27;差异率&#x27; or 列名 == &#x27;完成率&#x27;: 值 = f&quot;&#123;数据[列名]:.1f&#125;%&quot; elif &#x27;金额&#x27; in 列名: 值 = f&quot;&#123;数据[列名]:,.2f&#125;&quot; else: 值 = 数据[列名] 汇总表.cell(row=行号, column=列号, value=值) # 2. 差异分级统计 分级统计 = 差异分析结果.groupby(&#x27;差异级别&#x27;).agg(&#123; &#x27;差异金额&#x27;: [&#x27;count&#x27;, &#x27;sum&#x27;], &#x27;差异率&#x27;: &#x27;mean&#x27; &#125;).round(2) 统计表 = wb.create_sheet(&quot;差异分级统计&quot;) 统计表[&quot;A1&quot;] = &quot;差异分级统计&quot; 统计表[&quot;A1&quot;].font = Font(size=14, bold=True) # 写入统计结果 表头 = [&#x27;差异级别&#x27;, &#x27;数量&#x27;, &#x27;涉及金额&#x27;, &#x27;平均差异率&#x27;] for 列号, 标题 in enumerate(表头, 1): 单元格 = 统计表.cell(row=3, column=列号, value=标题) 单元格.font = Font(bold=True) for 行号, (级别, 数据) in enumerate(分级统计.iterrows(), 4): 统计表.cell(row=行号, column=1, value=级别) 统计表.cell(row=行号, column=2, value=数据[(&#x27;差异金额&#x27;, &#x27;count&#x27;)]) 统计表.cell(row=行号, column=3, value=f&quot;&#123;数据[(&#x27;差异金额&#x27;, &#x27;sum&#x27;)]:,.2f&#125;&quot;) 统计表.cell(row=行号, column=4, value=f&quot;&#123;数据[(&#x27;差异率&#x27;, &#x27;mean&#x27;)]:.1f&#125;%&quot;) # 3. 主要差异项目 重大差异 = 差异分析结果[差异分析结果[&#x27;差异级别&#x27;].isin([&#x27;显著差异&#x27;, &#x27;重大差异&#x27;])] if len(重大差异) &gt; 0: 重大差异 = 重大差异.sort_values(&#x27;差异金额&#x27;, key=abs, ascending=False) 差异表 = wb.create_sheet(&quot;主要差异项目&quot;) 差异表[&quot;A1&quot;] = &quot;主要差异项目（差异金额前10）&quot; 差异表[&quot;A1&quot;].font = Font(size=14, bold=True) # 写入重大差异项目 表头 = [&#x27;部门&#x27;, &#x27;项目&#x27;, &#x27;差异金额&#x27;, &#x27;差异率&#x27;, &#x27;可能原因&#x27;] for 列号, 标题 in enumerate(表头, 1): 单元格 = 差异表.cell(row=3, column=列号, value=标题) 单元格.font = Font(bold=True) for 行号, (_, 数据) in enumerate(重大差异.head(10).iterrows(), 4): 差异表.cell(row=行号, column=1, value=数据[&#x27;部门&#x27;]) 差异表.cell(row=行号, column=2, value=数据[&#x27;项目&#x27;]) 差异表.cell(row=行号, column=3, value=f&quot;&#123;数据[&#x27;差异金额&#x27;]:,.2f&#125;&quot;) 差异表.cell(row=行号, column=4, value=f&quot;&#123;数据[&#x27;差异率&#x27;]:.1f&#125;%&quot;) # 根据差异率判断可能原因 if 数据[&#x27;差异率&#x27;] &gt; 50: 原因 = &quot;远超预算，可能预算偏低或实际情况变化&quot; elif 数据[&#x27;差异率&#x27;] &gt; 20: 原因 = &quot;显著超出预算，需要详细分析原因&quot; elif 数据[&#x27;差异率&#x27;] &lt; -50: 原因 = &quot;远未达预算，可能预算过高或执行不力&quot; elif 数据[&#x27;差异率&#x27;] &lt; -20: 原因 = &quot;显著低于预算，需要关注执行情况&quot; else: 原因 = &quot;差异在正常范围内&quot; 差异表.cell(row=行号, column=5, value=原因) # 保存文件 wb.save(文件名) print(f&quot;✅ 预算差异分析报告已生成：&#123;文件名&#125;&quot;) return 文件名# 创建示例预算数据实际数据 = pd.DataFrame(&#123; &#x27;部门&#x27;: [&#x27;销售部&#x27;, &#x27;销售部&#x27;, &#x27;市场部&#x27;, &#x27;市场部&#x27;, &#x27;技术部&#x27;, &#x27;技术部&#x27;], &#x27;项目&#x27;: [&#x27;差旅费&#x27;, &#x27;招待费&#x27;, &#x27;广告费&#x27;, &#x27;推广费&#x27;, &#x27;设备费&#x27;, &#x27;培训费&#x27;], &#x27;金额&#x27;: [25000, 15000, 80000, 60000, 120000, 25000]&#125;)预算数据 = pd.DataFrame(&#123; &#x27;部门&#x27;: [&#x27;销售部&#x27;, &#x27;销售部&#x27;, &#x27;市场部&#x27;, &#x27;市场部&#x27;, &#x27;技术部&#x27;, &#x27;技术部&#x27;], &#x27;项目&#x27;: [&#x27;差旅费&#x27;, &#x27;招待费&#x27;, &#x27;广告费&#x27;, &#x27;推广费&#x27;, &#x27;设备费&#x27;, &#x27;培训费&#x27;], &#x27;金额&#x27;: [20000, 18000, 60000, 50000, 100000, 30000]&#125;)# 执行预算差异分析差异结果 = 预算差异分析(实际数据, 预算_data)print(&quot;📊 预算差异分析结果：&quot;)print(差异结果)# 生成分析报告预算报告 = 生成预算分析报告(差异结果, &quot;预算差异分析报告.xlsx&quot;)# 分析建议print(f&quot;
💡 预算管理建议：&quot;)重大差异数量 = len(差异结果[差异结果[&#x27;差异级别&#x27;].isin([&#x27;显著差异&#x27;, &#x27;重大差异&#x27;])])if 重大差异数量 &gt; 0: print(f&quot;⚠️ 发现&#123;重大差异数量&#125;个重大差异项目，需要重点关注&quot;) print(&quot;建议：&quot;) print(&quot;1. 对重大差异项目进行详细调查&quot;) print(&quot;2. 分析差异产生的原因&quot;) print(&quot;3. 根据分析结果调整下期预算&quot;) print(&quot;4. 加强预算执行监控&quot;)else: print(&quot;✅ 预算执行情况良好，差异都在正常范围内&quot;)超预算项目 = 差异结果[差异结果[&#x27;差异金额&#x27;] &gt; 0]if len(超预算项目) &gt; 0: print(f&quot;
📈 超预算项目：&#123;len(超预算项目)&#125;个&quot;) print(&quot;建议加强成本控制和预算管理&quot;)低预算项目 = 差异结果[差异结果[&#x27;差异金额&#x27;] &lt; 0]if len(低预算项目) &gt; 0: print(f&quot;
📉 低预算项目：&#123;len(低预算项目)&#125;个&quot;) print(&quot;建议分析是否预算制定过高或执行不力&quot;)
💭 今日思考通过今天的学习，我们发现：
pandas的DataFrame就是Excel表格的”超级升级版” 数据筛选比Excel的自动筛选更灵活、更强大 分组统计比数据透视表更快、更直观 用pandas做财务分析，效率提升是数量级的
📝 课后小结 ✅ 理解了DataFrame的概念和用途 ✅ 掌握了数据筛选的各种方法 ✅ 学会了分组统计和交叉分析 ✅ 完成了专业级的销售数据分析
