📖 开篇语还记得你第一次用Excel打开CSV文件的情景吗？
“哇，原来Python生成的数据可以直接在Excel里打开！”
今天我们要反过来——让Python直接读写Excel文件。从此告别“复制粘贴”的机械劳动，实现真正的自动化办公！ 想象一下这个场景：每天早上9点，Python自动下载银行对账单 → 读取公司账目 → 自动对账 → 生成差异报告 → 发送到你的邮箱而你只需要喝杯咖啡，看看报告就行！
🎯 今日学习目标 学会读取CSV文件（Python的“数据入口”） 掌握写入Excel文件（Python的“数据出口”） 实现自动化银行对账（告别手工对账）
📖 读取CSV文件：Python的数据入口什么是CSV文件？ CSV = Comma Separated Values（逗号分隔值）就是纯文本的表格，用逗号分隔列，用换行分隔行 举个栗子🌰： 日期,摘要,收入,支出,余额2024-01-01,工资收入,8000.00,,8000.002024-01-02,超市购物,,150.50,7849.502024-01-03,交通费,,25.00,7824.50 用Python读取CSV文件 方法1：普通读取（适合简单场景）# 读取银行流水CSV文件print(&quot;=== 读取银行流水 ===&quot;)# 打开文件with open(&quot;银行流水.csv&quot;, &quot;r&quot;, encoding=&quot;utf-8&quot;) as 文件: # 读取所有行 所有行 = 文件.readlines() # 第一行是表头 表头 = 所有行[0].strip().split(&quot;,&quot;) print(f&quot;表头：&#123;表头&#125;&quot;) # 其余行是数据 银行流水 = [] for 行 in 所有行[1:]: # 跳过表头 数据 = 行.strip().split(&quot;,&quot;) 银行流水.append(数据) # 显示前几行 print(&quot;
银行流水数据：&quot;) for i, 记录 in enumerate(银行流水[:5], 1): print(f&quot;&#123;i&#125;. 日期：&#123;记录[0]&#125;，摘要：&#123;记录[1]&#125;，收入：&#123;记录[2]&#125;，支出：&#123;记录[3]&#125;，余额：&#123;记录[4]&#125;&quot;)# 计算总收入和总支出总收入 = sum(float(记录[2]) if 记录[2] else 0 for 记录 in 银行流水)总支出 = sum(float(记录[3]) if 记录[3] else 0 for 记录 in 银行流水)print(f&quot;
💰 汇总统计：&quot;)print(f&quot;总收入：&#123;总收入:,.2f&#125;元&quot;)print(f&quot;总支出：&#123;总支出:,.2f&#125;元&quot;)print(f&quot;净收支：&#123;总收入 - 总支出:,.2f&#125;元&quot;) 方法2：使用csv模块（推荐方法）import csv# 更专业的CSV读取print(&quot;=== 专业CSV读取 ===&quot;)def 读取银行流水(文件名): &quot;&quot;&quot;读取银行流水CSV文件&quot;&quot;&quot; 流水列表 = [] with open(文件名, &quot;r&quot;, encoding=&quot;utf-8&quot;) as 文件: csv读取器 = csv.reader(文件) # 读取表头 表头 = next(csv读取器) print(f&quot;表头：&#123;表头&#125;&quot;) # 读取数据 for 行号, 记录 in enumerate(csv读取器, 1): 流水字典 = &#123; &quot;行号&quot;: 行号, &quot;日期&quot;: 记录[0], &quot;摘要&quot;: 记录[1], &quot;收入&quot;: float(记录[2]) if 记录[2] else 0, &quot;支出&quot;: float(记录[3]) if 记录[3] else 0, &quot;余额&quot;: float(记录[4]) &#125; 流水列表.append(流水字典) return 流水列表, 表头# 使用函数读取银行流水数据, 原始表头 = 读取银行流水(&quot;银行流水.csv&quot;)# 数据分析print(f&quot;
📊 数据分析：&quot;)print(f&quot;共读取到 &#123;len(银行流水数据)&#125; 条记录&quot;)# 按条件筛选大额收入 = [记录 for 记录 in 银行流水数据 if 记录[&quot;收入&quot;] &gt; 1000]购物支出 = [记录 for 记录 in 银行流水数据 if &quot;购物&quot; in 记录[&quot;摘要&quot;]]print(f&quot;
大额收入（&gt;1000元）：&#123;len(大额收入)&#125;笔&quot;)for 记录 in 大额收入: print(f&quot; &#123;记录[&#x27;日期&#x27;]&#125;：&#123;记录[&#x27;收入&#x27;]:,.2f&#125;元&quot;)print(f&quot;
购物支出：&#123;len(购物支出)&#125;笔&quot;)购物总金额 = sum(记录[&quot;支出&quot;] for 记录 in 购物支出)print(f&quot;购物总支出：&#123;购物总金额:,.2f&#125;元&quot;) 方法3：读取并转换为DataFrame（为pandas做准备）import csvimport pandas as pddef csv转dataframe(csv文件): &quot;&quot;&quot;将CSV文件转换为DataFrame格式&quot;&quot;&quot; 数据列表 = [] with open(csv文件, &quot;r&quot;, encoding=&quot;utf-8&quot;) as 文件: csv读取器 = csv.DictReader(文件) for 行 in csv读取器: # 转换数值类型 行[&quot;收入&quot;] = float(行[&quot;收入&quot;]) if 行[&quot;收入&quot;] else 0 行[&quot;支出&quot;] = float(行[&quot;支出&quot;]) if 行[&quot;支出&quot;] else 0 行[&quot;余额&quot;] = float(行[&quot;余额&quot;]) 数据列表.append(行) return 数据列表# 读取数据流水数据 = csv转dataframe(&quot;银行流水.csv&quot;)# 转换为pandas DataFrame（为后续做准备）df = pd.DataFrame(流水数据)print(f&quot;DataFrame形状：&#123;df.shape&#125;&quot;)print(df.head()) # 显示前5行
实战：读取发票清单CSV
# 读取发票清单并自动分类print(&quot;=== 发票清单处理 ===&quot;)def 处理发票清单(发票文件): &quot;&quot;&quot;读取并处理发票清单&quot;&quot;&quot; 发票列表 = [] with open(发票文件, &quot;r&quot;, encoding=&quot;utf-8&quot;) as 文件: csv读取器 = csv.DictReader(文件) for 发票 in csv读取器: # 数据清洗和转换 发票信息 = &#123; &quot;发票代码&quot;: 发票[&quot;发票代码&quot;], &quot;发票号码&quot;: 发票[&quot;发票号码&quot;], &quot;开票日期&quot;: 发票[&quot;开票日期&quot;], &quot;金额&quot;: float(发票[&quot;金额&quot;]), &quot;税额&quot;: float(发票[&quot;税额&quot;]), &quot;价税合计&quot;: float(发票[&quot;价税合计&quot;]), &quot;发票类型&quot;: 发票[&quot;发票类型&quot;], &quot;发票状态&quot;: 发票[&quot;发票状态&quot;], &quot;销方名称&quot;: 发票[&quot;销方名称&quot;], &quot;发票内容&quot;: 发票[&quot;发票内容&quot;] &#125; 发票列表.append(发票信息) return 发票列表# 读取发票数据发票数据 = 处理发票清单(&quot;发票清单.csv&quot;)# 发票分类统计有效发票 = [发票 for 发票 in 发票数据 if 发票[&quot;发票状态&quot;] == &quot;正常&quot;]作废发票 = [发票 for 发票 in 发票数据 if 发票[&quot;发票状态&quot;] == &quot;作废&quot;]专用发票 = [发票 for 发票 in 发票数据 if 发票[&quot;发票类型&quot;] == &quot;专用发票&quot;]普通发票 = [发票 for 发票 in 发票数据 if 发票[&quot;发票类型&quot;] == &quot;普通发票&quot;]print(f&quot;📊 发票统计：&quot;)print(f&quot;总发票数：&#123;len(发票数据)&#125;张&quot;)print(f&quot;有效发票：&#123;len(有效发票)&#125;张&quot;)print(f&quot;作废发票：&#123;len(作废发票)&#125;张&quot;)print(f&quot;专用发票：&#123;len(专用发票)&#125;张&quot;)print(f&quot;普通发票：&#123;len(普通发票)&#125;张&quot;)# 金额统计有效发票总金额 = sum(发票[&quot;价税合计&quot;] for 发票 in 有效发票)专用发票总金额 = sum(发票[&quot;价税合计&quot;] for 发票 in 专用发票)print(f&quot;
💰 金额统计：&quot;)print(f&quot;有效发票总金额：&#123;有效发票总金额:,.2f&#125;元&quot;)print(f&quot;专用发票总金额：&#123;专用发票总金额:,.2f&#125;元&quot;)# 按月份统计月份统计 = &#123;&#125;for 发票 in 有效发票: 月份 = 发票[&quot;开票日期&quot;][:7] # 取年月部分 if 月份 not in 月份统计: 月份统计[月份] = &#123;&quot;数量&quot;: 0, &quot;金额&quot;: 0&#125; 月份统计[月份][&quot;数量&quot;] += 1 月份统计[月份][&quot;金额&quot;] += 发票[&quot;价税合计&quot;]print(f&quot;
📅 月度开票情况：&quot;)for 月份 in sorted(月份统计.keys()): 数量 = 月份统计[月份][&quot;数量&quot;] 金额 = 月份统计[月份][&quot;金额&quot;] print(f&quot;&#123;月份&#125;：&#123;数量&#125;张，&#123;金额:,.2f&#125;元&quot;)
📊 写入Excel文件：Python的数据出口安装必备库# 需要安装openpyxl库pip install openpyxl 基础Excel写入from openpyxl import Workbookfrom openpyxl.styles import Font, Alignment, PatternFillimport csv# 创建Excel工作簿def 创建财务报告(): &quot;&quot;&quot;创建专业的财务报告Excel文件&quot;&quot;&quot; # 创建工作簿 wb = Workbook() # 删除默认工作表 wb.remove(wb.active) # 创建多个工作表 汇总表 = wb.create_sheet(&quot;财务汇总&quot;, 0) 明细表 = wb.create_sheet(&quot;收支明细&quot;, 1) 分析表 = wb.create_sheet(&quot;分析报告&quot;, 2) # ===== 1. 财务汇总表 ===== 汇总表[&quot;A1&quot;] = &quot;财务汇总报告&quot; 汇总表[&quot;A1&quot;].font = Font(size=16, bold=True) 汇总表.merge_cells(&quot;A1:E1&quot;) # 添加汇总数据 汇总数据 = [ [&quot;项目&quot;, &quot;本月&quot;, &quot;上月&quot;, &quot;环比变化&quot;, &quot;备注&quot;], [&quot;总收入&quot;, &quot;50,000&quot;, &quot;45,000&quot;, &quot;+11.1%&quot;, &quot;工资收入&quot;], [&quot;总支出&quot;, &quot;35,000&quot;, &quot;32,000&quot;, &quot;+9.4%&quot;, &quot;日常开支&quot;], [&quot;净结余&quot;, &quot;15,000&quot;, &quot;13,000&quot;, &quot;+15.4%&quot;, &quot;储蓄增加&quot;], [&quot;投资收入&quot;, &quot;2,500&quot;, &quot;2,000&quot;, &quot;+25.0%&quot;, &quot;理财收益&quot;], [&quot;应收账款&quot;, &quot;8,500&quot;, &quot;7,200&quot;, &quot;+18.1%&quot;, &quot;待收款&quot;] ] for 行号, 数据行 in enumerate(汇总数据, 2): for 列号, 值 in enumerate(数据行, 1): 单元格 = 汇总表.cell(row=行号, column=列号, value=值) if 行号 == 2: # 表头 单元格.font = Font(bold=True) 单元格.fill = PatternFill(start_color=&quot;CCCCCC&quot;, end_color=&quot;CCCCCC&quot;, fill_type=&quot;solid&quot;) # 调整列宽 for 列 in [&quot;A&quot;, &quot;B&quot;, &quot;C&quot;, &quot;D&quot;, &quot;E&quot;]: 汇总表.column_dimensions[列].width = 15 # ===== 2. 收支明细表 ===== 明细表[&quot;A1&quot;] = &quot;收支明细表&quot; 明细表[&quot;A1&quot;].font = Font(size=14, bold=True) # 读取CSV数据并写入Excel try: with open(&quot;银行流水.csv&quot;, &quot;r&quot;, encoding=&quot;utf-8&quot;) as 文件: csv读取器 = csv.reader(文件) # 写入表头 表头 = next(csv读取器) for 列号, 标题 in enumerate(表头, 1): 明细表.cell(row=2, column=列号, value=标题) 明细表.cell(row=2, column=列号).font = Font(bold=True) # 写入数据 for 行号, 数据行 in enumerate(csv读取器, 3): for 列号, 值 in enumerate(数据行, 1): 明细表.cell(row=行号, column=列号, value=值) print(&quot;✅ CSV数据已成功导入Excel！&quot;) except FileNotFoundError: # 如果没有CSV文件，生成示例数据 示例数据 = [ [&quot;2024-01-01&quot;, &quot;工资收入&quot;, &quot;8000&quot;, &quot;&quot;, &quot;8000&quot;], [&quot;2024-01-02&quot;, &quot;超市购物&quot;, &quot;&quot;, &quot;150.50&quot;, &quot;7849.50&quot;], [&quot;2024-01-03&quot;, &quot;交通费&quot;, &quot;&quot;, &quot;25.00&quot;, &quot;7824.50&quot;], [&quot;2024-01-05&quot;, &quot;餐饮消费&quot;, &quot;&quot;, &quot;180.00&quot;, &quot;7644.50&quot;], [&quot;2024-01-10&quot;, &quot;兼职收入&quot;, &quot;1200&quot;, &quot;&quot;, &quot;8844.50&quot;] ] for 行号, 数据行 in enumerate(示例数据, 3): for 列号, 值 in enumerate(数据行, 1): 明细表.cell(row=行号, column=列号, value=值) print(&quot;✅ 示例数据已写入Excel！&quot;) # ===== 3. 分析报告表 ===== 分析表[&quot;A1&quot;] = &quot;财务分析报告&quot; 分析表[&quot;A1&quot;].font = Font(size=14, bold=True) # 添加分析内容 分析内容 = [ [&quot;分析项目&quot;, &quot;结果&quot;, &quot;建议&quot;], [&quot;收支比率&quot;, &quot;1.43&quot;, &quot;收入大于支出，财务状况良好&quot;], [&quot;储蓄率&quot;, &quot;30%&quot;, &quot;储蓄率较高，可适当增加投资&quot;], [&quot;最大支出&quot;, &quot;餐饮消费&quot;, &quot;建议控制餐饮支出，自己做饭&quot;], [&quot;收入稳定性&quot;, &quot;高&quot;, &quot;主要收入为工资，建议开拓副业&quot;], [&quot;投资建议&quot;, &quot;稳健型&quot;, &quot;可考虑定投指数基金&quot;] ] for 行号, 数据行 in enumerate(分析内容, 2): for 列号, 值 in enumerate(数据行, 1): 单元格 = 分析表.cell(row=行号, column=列号, value=值) if 行号 == 2: 单元格.font = Font(bold=True) 单元格.fill = PatternFill(start_color=&quot;E8F4FD&quot;, end_color=&quot;E8F4FD&quot;, fill_type=&quot;solid&quot;) # 调整格式 for 列 in [&quot;A&quot;, &quot;B&quot;, &quot;C&quot;]: 分析表.column_dimensions[列].width = 20 # ===== 保存文件 ===== 文件名 = &quot;财务报告_2024.xlsx&quot; wb.save(文件名) print(f&quot;✅ Excel文件已保存：&#123;文件名&#125;&quot;) return 文件名# 创建报告报告文件 = 创建财务报告()
进阶：自动生成图表
from openpyxl.chart import LineChart, Reference, BarChartfrom openpyxl.utils.dataframe import dataframe_to_rowsimport pandas as pddef 生成带图表的财务报告(): &quot;&quot;&quot;生成包含图表的财务报告&quot;&quot;&quot; # 创建工作簿 wb = Workbook() 数据表 = wb.active 数据表.title = &quot;月度数据&quot; # 创建示例数据 月份数据 = &#123; &quot;月份&quot;: [&quot;1月&quot;, &quot;2月&quot;, &quot;3月&quot;, &quot;4月&quot;, &quot;5月&quot;, &quot;6月&quot;], &quot;收入&quot;: [25000, 28000, 26000, 30000, 32000, 35000], &quot;支出&quot;: [18000, 19500, 18500, 21000, 22000, 23000], &quot;结余&quot;: [7000, 8500, 7500, 9000, 10000, 12000] &#125; df = pd.DataFrame(月份数据) # 写入数据到Excel for 行 in dataframe_to_rows(df, index=False, header=True): 数据表.append(行) # 创建折线图 折线图 = LineChart() 折线图.title = &quot;月度收支趋势图&quot; 折线图.style = 2 折线图.y_axis.title = &quot;金额（元）&quot; 折线图.x_axis.title = &quot;月份&quot; # 添加数据 数据范围 = Reference(数据表, min_col=2, min_row=1, max_col=4, max_row=7) 折线图.add_data(数据范围, titles_from_data=True) # 添加图表到工作表 数据表.add_chart(折线图, &quot;F2&quot;) # 创建柱状图 柱状图 = BarChart() 柱状图.title = &quot;月度结余对比&quot; 柱状图.style = 10 柱状图.y_axis.title = &quot;金额（元）&quot; 柱状图.x_axis.title = &quot;月份&quot; # 只显示结余数据 结余数据 = Reference(数据表, min_col=4, min_row=1, max_col=4, max_row=7) 月份标签 = Reference(数据表, min_col=1, min_row=2, max_row=7) 柱状图.add_data(结余数据, titles_from_data=True) 柱状图.set_categories(月份标签) # 添加图表 数据表.add_chart(柱状图, &quot;F18&quot;) # 保存文件 文件名 = &quot;财务报告_带图表.xlsx&quot; wb.save(文件名) print(f&quot;✅ 带图表的Excel报告已生成：&#123;文件名&#125;&quot;) return 文件名# 生成带图表的报告图表报告 = 生成带图表的财务报告()
🏦 实战项目：自动化银行对账 版本1.0：基础对账功能
# 自动化银行对账系统 - 基础版print(&quot;=== 自动化银行对账系统 ===&quot;)import csvfrom datetime import datetimeimport osdef 读取银行对账单(文件名): &quot;&quot;&quot;读取银行对账单&quot;&quot;&quot; 对账单 = [] try: with open(文件名, &quot;r&quot;, encoding=&quot;utf-8&quot;) as 文件: csv读取器 = csv.DictReader(文件) for 记录 in csv读取器: 对账单.append(&#123; &quot;日期&quot;: 记录[&quot;交易日期&quot;], &quot;摘要&quot;: 记录[&quot;摘要&quot;], &quot;借方&quot;: float(记录[&quot;借方金额&quot;]) if 记录[&quot;借方金额&quot;] else 0, &quot;贷方&quot;: float(记录[&quot;贷方金额&quot;]) if 记录[&quot;贷方金额&quot;] else 0, &quot;余额&quot;: float(记录[&quot;余额&quot;]), &quot;对账单索引&quot;: len(对账单) + 1 &#125;) except FileNotFoundError: print(f&quot;❌ 文件 &#123;文件名&#125; 不存在！&quot;) return [] return 对账单def 读取企业账目(文件名): &quot;&quot;&quot;读取企业账目&quot;&quot;&quot; 企业账 = [] try: with open(文件名, &quot;r&quot;, encoding=&quot;utf-8&quot;) as 文件: csv读取器 = csv.DictReader(文件) for 记录 in csv读取器: 企业账.append(&#123; &quot;日期&quot;: 记录[&quot;日期&quot;], &quot;摘要&quot;: 记录[&quot;摘要&quot;], &quot;借方&quot;: float(记录[&quot;借方&quot;]) if 记录[&quot;借方&quot;] else 0, &quot;贷方&quot;: float(记录[&quot;贷方&quot;]) if 记录[&quot;贷方&quot;] else 0, &quot;余额&quot;: float(记录[&quot;余额&quot;]), &quot;账目索引&quot;: len(企业账) + 1 &#125;) except FileNotFoundError: print(f&quot;❌ 文件 &#123;文件名&#125; 不存在！&quot;) return [] return 企业账def 基础对账(银行对账单, 企业账目): &quot;&quot;&quot;执行基础对账功能&quot;&quot;&quot; 对账结果 = &#123; &quot;匹配记录&quot;: [], &quot;银行未达&quot;: [], &quot;企业未达&quot;: [], &quot;差异记录&quot;: [] &#125; # 创建索引以提高查找效率 银行交易索引 = &#123;&#125; for 交易 in 银行对账单: 关键信息 = f&quot;&#123;交易[&#x27;日期&#x27;]&#125;_&#123;交易[&#x27;借方&#x27;]&#125;_&#123;交易[&#x27;贷方&#x27;]&#125;_&#123;交易[&#x27;摘要&#x27;][:10]&#125;&quot; if 关键信息 not in 银行交易索引: 银行交易索引[关键信息] = [] 银行交易索引[关键信息].append(交易) # 对账：以企业账目为准 for 企业交易 in 企业账目: 关键信息 = f&quot;&#123;企业交易[&#x27;日期&#x27;]&#125;_&#123;企业交易[&#x27;借方&#x27;]&#125;_&#123;企业交易[&#x27;贷方&#x27;]&#125;_&#123;企业交易[&#x27;摘要&#x27;][:10]&#125;&quot; if 关键信息 in 银行交易索引: # 找到匹配记录 匹配记录 = 银行交易索引[关键信息].pop(0) # 取出一个匹配 if not 银行交易索引[关键信息]: # 如果列表空了，删除键 del 银行交易索引[关键信息] 对账结果[&quot;匹配记录&quot;].append(&#123; &quot;企业记录&quot;: 企业交易, &quot;银行记录&quot;: 匹配记录, &quot;状态&quot;: &quot;完全匹配&quot; &#125;) else: # 企业有，银行没有 - 企业未达 对账结果[&quot;企业未达&quot;].append(企业交易) # 银行未达：银行有，企业没有 for 关键信息, 交易列表 in 银行交易索引.items(): 对账结果[&quot;银行未达&quot;].extend(交易列表) # 检查余额差异 if 银行对账单 and 企业账目: 银行最终余额 = 银行对账单[-1][&quot;余额&quot;] 企业最终余额 = 企业账目[-1][&quot;余额&quot;] 余额差异 = 银行最终余额 - 企业最终余额 if abs(余额差异) &gt; 0.01: # 差异大于1分钱 对账结果[&quot;差异记录&quot;].append(&#123; &quot;类型&quot;: &quot;余额差异&quot;, &quot;银行余额&quot;: 银行最终余额, &quot;企业余额&quot;: 企业最终余额, &quot;差异金额&quot;: 余额差异 &#125;) return 对账结果# 生成对账报告def 生成对账报告(对账结果, 输出文件名=&quot;对账报告.txt&quot;): &quot;&quot;&quot;生成对账报告&quot;&quot;&quot; with open(输出文件名, &quot;w&quot;, encoding=&quot;utf-8&quot;) as 报告文件: 报告文件.write(&quot;银行对账报告
&quot;) 报告文件.write(&quot;=&quot; * 50 + &quot;
