版本2.0：增强对账功能
# 自动化银行对账系统 - 增强版print(&quot;=== 增强版银行对账系统 ===&quot;)import csvimport pandas as pdfrom datetime import datetime, timedeltafrom openpyxl import Workbookfrom openpyxl.styles import Font, PatternFill, Alignmentclass 银行对账系统: def __init__(self): self.银行数据 = [] self.企业数据 = [] self.对账结果 = &#123;&#125; def 加载银行数据(self, 文件名, 日期列=&quot;日期&quot;, 金额列=&quot;金额&quot;, 摘要列=&quot;摘要&quot;, 余额列=&quot;余额&quot;): &quot;&quot;&quot;智能加载银行数据&quot;&quot;&quot; try: df = pd.read_csv(文件名) for _, 行 in df.iterrows(): self.银行数据.append(&#123; &quot;日期&quot;: pd.to_datetime(行[日期列]), &quot;金额&quot;: float(行[金额列]), &quot;摘要&quot;: str(行[摘要列]), &quot;余额&quot;: float(行[余额列]) if 余额列 in 行 else 0, &quot;原始行&quot;: 行.to_dict() &#125;) print(f&quot;✅ 银行数据加载成功：&#123;len(self.银行数据)&#125;笔&quot;) return True except Exception as e: print(f&quot;❌ 银行数据加载失败：&#123;e&#125;&quot;) return False def 加载企业数据(self, 文件名, 日期列=&quot;日期&quot;, 借方列=&quot;借方&quot;, 贷方列=&quot;贷方&quot;, 摘要列=&quot;摘要&quot;, 余额列=&quot;余额&quot;): &quot;&quot;&quot;智能加载企业数据&quot;&quot;&quot; try: df = pd.read_csv(文件名) for _, 行 in df.iterrows(): 借方 = float(行[借方列]) if 借方列 in 行 and pd.notna(行[借方列]) else 0 贷方 = float(行[贷方列]) if 贷方列 in 行 and pd.notna(行[贷方列]) else 0 金额 = 贷方 - 借方 self.企业数据.append(&#123; &quot;日期&quot;: pd.to_datetime(行[日期列]), &quot;金额&quot;: 金额, &quot;摘要&quot;: str(行[摘要列]) if 摘要列 in 行 else &quot;&quot;, &quot;余额&quot;: float(行[余额列]) if 余额列 in 行 and pd.notna(行[余额列]) else 0, &quot;原始行&quot;: 行.to_dict() &#125;) print(f&quot;✅ 企业数据加载成功：&#123;len(self.企业数据)&#125;笔&quot;) return True except Exception as e: print(f&quot;❌ 企业数据加载失败：&#123;e&#125;&quot;) return False def 智能对账(self, 容差天数=3, 容差金额=0.01): &quot;&quot;&quot;执行智能对账&quot;&quot;&quot; print(&quot;🔍 执行智能对账...&quot;) 对账结果 = &#123; &quot;完全匹配&quot;: [], &quot;金额匹配日期不同&quot;: [], &quot;日期匹配金额不同&quot;: [], &quot;银行独有&quot;: [], &quot;企业独有&quot;: [], &quot;余额差异&quot;: [] &#125; # 创建索引提高查找效率 银行已匹配 = set() 企业已匹配 = set() # 第一轮：精确匹配 print(&quot; 第一轮：精确匹配...&quot;) for i, 银行交易 in enumerate(self.银行数据): for j, 企业交易 in enumerate(self.企业数据): if j in 企业已匹配: continue # 检查是否完全匹配 if (abs((银行交易[&quot;日期&quot;] - 企业交易[&quot;日期&quot;]).days) &lt;= 容差天数 and abs(银行交易[&quot;金额&quot;] - 企业交易[&quot;金额&quot;]) &lt;= 容差金额): 对账结果[&quot;完全匹配&quot;].append(&#123; &quot;银行记录&quot;: 银行交易, &quot;企业记录&quot;: 企业交易, &quot;差异天数&quot;: abs((银行交易[&quot;日期&quot;] - 企业交易[&quot;日期&quot;]).days) &#125;) 银行已匹配.add(i) 企业已匹配.add(j) break # 第二轮：模糊匹配（仅金额匹配） print(&quot; 第二轮：金额模糊匹配...&quot;) 未匹配银行 = [i for i in range(len(self.银行数据)) if i not in 银行已匹配] 未匹配企业 = [j for j in range(len(self.企业数据)) if j not in 企业已匹配] for i in 未匹配银行[:]: # 使用副本，避免修改列表 if i in 银行已匹配: continue 银行交易 = self.银行数据[i] for j in 未匹配企业[:]: if j in 企业已匹配: continue 企业交易 = self.企业数据[j] # 仅金额匹配，日期差异较大 if (abs(银行交易[&quot;金额&quot;] - 企业交易[&quot;金额&quot;]) &lt;= 容差金额 and abs((银行交易[&quot;日期&quot;] - 企业交易[&quot;日期&quot;]).days) &lt;= 容差天数 * 2): 对账结果[&quot;金额匹配日期不同&quot;].append(&#123; &quot;银行记录&quot;: 银行交易, &quot;企业记录&quot;: 企业交易, &quot;差异天数&quot;: abs((银行交易[&quot;日期&quot;] - 企业交易[&quot;日期&quot;]).days) &#125;) 银行已匹配.add(i) 企业已匹配.add(j) 未匹配银行.remove(i) 未匹配企业.remove(j) break # 剩余记录 for i in 未匹配银行: 对账结果[&quot;银行独有&quot;].append(self.银行数据[i]) for j in 未匹配企业: 对账结果[&quot;企业独有&quot;].append(self.企业数据[j]) # 检查余额差异 if self.银行数据 and self.企业数据: 银行最终余额 = self.银行数据[-1][&quot;余额&quot;] 企业最终余额 = self.企业数据[-1][&quot;余额&quot;] 余额差异 = 银行最终余额 - 企业最终余额 if abs(余额差异) &gt; 容差金额: 对账结果[&quot;余额差异&quot;].append(&#123; &quot;银行余额&quot;: 银行最终余额, &quot;企业余额&quot;: 企业最终余额, &quot;差异金额&quot;: 余额差异 &#125;) self.对账结果 = 对账结果 return 对账结果 def 生成Excel报告(self, 文件名=&quot;银行对账报告.xlsx&quot;): &quot;&quot;&quot;生成专业的Excel对账报告&quot;&quot;&quot; wb = Workbook() # 1. 汇总报告 汇总表 = wb.active 汇总表.title = &quot;对账汇总&quot; # 标题 汇总表[&quot;A1&quot;] = &quot;银行对账汇总报告&quot; 汇总表[&quot;A1&quot;].font = Font(size=16, bold=True, color=&quot;FFFFFF&quot;) 汇总表[&quot;A1&quot;].fill = PatternFill(start_color=&quot;366092&quot;, end_color=&quot;366092&quot;, fill_type=&quot;solid&quot;) 汇总表.merge_cells(&quot;A1:F1&quot;) # 对账结果汇总 汇总数据 = [ [&quot;对账项目&quot;, &quot;笔数&quot;, &quot;金额范围&quot;, &quot;状态&quot;], [&quot;完全匹配&quot;, len(self.对账结果[&quot;完全匹配&quot;]), &quot;完全一致&quot;, &quot;✅ 正常&quot;], [&quot;金额匹配日期不同&quot;, len(self.对账结果[&quot;金额匹配日期不同&quot;]), &quot;时间差异&quot;, &quot;⚠️ 关注&quot;], [&quot;银行独有&quot;, len(self.对账结果[&quot;银行独有&quot;]), &quot;银行有企业无&quot;, &quot;❌ 未达&quot;], [&quot;企业独有&quot;, len(self.对账结果[&quot;企业独有&quot;]), &quot;企业有银行无&quot;, &quot;❌ 未达&quot;], [&quot;余额差异&quot;, len(self.对账结果[&quot;余额差异&quot;]), &quot;余额不符&quot;, &quot;❌ 异常&quot;] ] for 行号, 数据行 in enumerate(汇总数据, 3): for 列号, 值 in enumerate(数据行, 1): 单元格 = 汇总表.cell(row=行号, column=列号, value=值) if 行号 == 3: # 表头 单元格.font = Font(bold=True) 单元格.fill = PatternFill(start_color=&quot;D9E2F3&quot;, end_color=&quot;D9E2F3&quot;, fill_type=&quot;solid&quot;) # 2. 明细表 明细表 = wb.create_sheet(&quot;对账明细&quot;) 明细表[&quot;A1&quot;] = &quot;对账明细记录&quot; 明细表[&quot;A1&quot;].font = Font(size=14, bold=True) # 完全匹配明细 行号 = 3 明细表.cell(row=行号, column=1, value=&quot;完全匹配记录&quot;) 明细表.cell(row=行号, column=1).font = Font(bold=True, color=&quot;008000&quot;) 行号 += 1 # 表头 表头 = [&quot;类型&quot;, &quot;日期&quot;, &quot;摘要&quot;, &quot;金额&quot;, &quot;余额&quot;, &quot;状态&quot;] for 列号, 标题 in enumerate(表头, 1): 明细表.cell(row=行号, column=列号, value=标题) 明细表.cell(row=行号, column=列号).font = Font(bold=True) 行号 += 1 # 写入完全匹配记录 for 匹配 in self.对账结果[&quot;完全匹配&quot;][:10]: # 只显示前10条 银行 = 匹配[&quot;银行记录&quot;] 企业 = 匹配[&quot;企业记录&quot;] 明细表.cell(row=行号, column=1, value=&quot;银行&quot;) 明细表.cell(row=行号, column=2, value=银行[&quot;日期&quot;].strftime(&quot;%Y-%m-%d&quot;)) 明细表.cell(row=行号, column=3, value=银行[&quot;摘要&quot;][:20]) 明细表.cell(row=行号, column=4, value=银行[&quot;金额&quot;]) 明细表.cell(row=行号, column=5, value=银行.get(&quot;余额&quot;, &quot;&quot;)) 明细表.cell(row=行号, column=6, value=&quot;✅ 匹配&quot;) 行号 += 1 明细表.cell(row=行号, column=1, value=&quot;企业&quot;) 明细表.cell(row=行号, column=2, value=企业[&quot;日期&quot;].strftime(&quot;%Y-%m-%d&quot;)) 明细表.cell(row=行号, column=3, value=企业[&quot;摘要&quot;][:20]) 明细表.cell(row=行号, column=4, value=企业[&quot;金额&quot;]) 明细表.cell(row=行号, column=5, value=企业.get(&quot;余额&quot;, &quot;&quot;)) 明细表.cell(row=行号, column=6, value=&quot;✅ 匹配&quot;) 行号 += 2 # 空一行 # 未达账项 明细表.cell(row=行号, column=1, value=&quot;未达账项&quot;) 明细表.cell(row=行号, column=1).font = Font(bold=True, color=&quot;FF0000&quot;) 行号 += 1 # 银行未达 for 交易 in self.对账结果[&quot;银行未达&quot;]: 明细表.cell(row=行号, column=1, value=&quot;银行未达&quot;) 明细表.cell(row=行号, column=2, value=交易[&quot;日期&quot;].strftime(&quot;%Y-%m-%d&quot;)) 明细表.cell(row=行号, column=3, value=交易[&quot;摘要&quot;][:20]) 明细表.cell(row=行号, column=4, value=交易[&quot;金额&quot;]) 明细表.cell(row=行号, column=6, value=&quot;❌ 银行独有&quot;) 行号 += 1 # 企业未达 for 交易 in self.对账结果[&quot;企业未达&quot;]: 明细表.cell(row=行号, column=1, value=&quot;企业未达&quot;) 明细表.cell(row=行号, column=2, value=交易[&quot;日期&quot;].strftime(&quot;%Y-%m-%d&quot;)) 明细表.cell(row=行号, column=3, value=交易[&quot;摘要&quot;][:20]) 明细表.cell(row=行号, column=4, value=交易[&quot;金额&quot;]) 明细表.cell(row=行号, column=6, value=&quot;❌ 企业独有&quot;) 行号 += 1 # 调整列宽 for 列 in [&quot;A&quot;, &quot;B&quot;, &quot;C&quot;, &quot;D&quot;, &quot;E&quot;, &quot;F&quot;]: 明细表.column_dimensions[列].width = 15 # 3. 差异分析表 if self.对账结果[&quot;余额差异&quot;]: 差异表 = wb.create_sheet(&quot;余额差异分析&quot;) 差异表[&quot;A1&quot;] = &quot;余额差异分析&quot; 差异表[&quot;A1&quot;].font = Font(size=14, bold=True, color=&quot;FF0000&quot;) 差异 = self.对账结果[&quot;余额差异&quot;][0] 差异表[&quot;A3&quot;] = f&quot;银行最终余额：&#123;差异[&#x27;银行余额&#x27;]:,.2f&#125;元&quot; 差异表[&quot;A4&quot;] = f&quot;企业最终余额：&#123;差异[&#x27;企业余额&#x27;]:,.2f&#125;元&quot; 差异表[&quot;A5&quot;] = f&quot;差异金额：&#123;差异[&#x27;差异金额&#x27;]:,.2f&#125;元&quot; # 差异原因分析 差异表[&quot;A7&quot;] = &quot;可能原因分析：&quot; 差异表[&quot;A7&quot;].font = Font(bold=True) 原因列表 = [ &quot;1. 银行已入账，企业未获取回单&quot;, &quot;2. 企业已记账，银行尚未处理&quot;, &quot;3. 存在在途资金&quot;, &quot;4. 记账时间差异&quot;, &quot;5. 可能存在记账错误&quot; ] for i, 原因 in enumerate(原因列表, 8): 差异表.cell(row=i, column=1, value=原因) # 保存文件 wb.save(文件名) print(f&quot;✅ Excel对账报告已生成：&#123;文件名&#125;&quot;) return 文件名# 使用增强版对账系统对账系统 = 银行对账系统()# 加载数据（如果没有文件，创建示例数据）if not os.path.exists(&quot;银行对账单.csv&quot;): # 创建示例银行对账单 with open(&quot;银行对账单.csv&quot;, &quot;w&quot;, encoding=&quot;utf-8&quot;, newline=&#x27;&#x27;) as f: writer = csv.writer(f) writer.writerow([&quot;交易日期&quot;, &quot;摘要&quot;, &quot;借方金额&quot;, &quot;贷方金额&quot;, &quot;余额&quot;]) 数据 = [ [&quot;2024-01-01&quot;, &quot;上月结转&quot;, &quot;&quot;, &quot;&quot;, &quot;50000.00&quot;], [&quot;2024-01-05&quot;, &quot;客户A货款&quot;, &quot;&quot;, &quot;25000.00&quot;, &quot;75000.00&quot;], [&quot;2024-01-10&quot;, &quot;供应商B付款&quot;, &quot;15000.00&quot;, &quot;&quot;, &quot;60000.00&quot;], [&quot;2024-01-15&quot;, &quot;工资发放&quot;, &quot;35000.00&quot;, &quot;&quot;, &quot;25000.00&quot;], [&quot;2024-01-20&quot;, &quot;客户C货款&quot;, &quot;&quot;, &quot;30000.00&quot;, &quot;55000.00&quot;], [&quot;2024-01-25&quot;, &quot;水电费&quot;, &quot;1200.00&quot;, &quot;&quot;, &quot;53800.00&quot;], [&quot;2024-01-28&quot;, &quot;客户D货款&quot;, &quot;&quot;, &quot;20000.00&quot;, &quot;73800.00&quot;], [&quot;2024-01-30&quot;, &quot;银行手续费&quot;, &quot;50.00&quot;, &quot;&quot;, &quot;73750.00&quot;] ] writer.writerows(数据)if not os.path.exists(&quot;企业账目.csv&quot;): # 创建示例企业账目（故意制造一些差异） with open(&quot;企业账目.csv&quot;, &quot;w&quot;, encoding=&quot;utf-8&quot;, newline=&#x27;&#x27;) as f: writer = csv.writer(f) writer.writerow([&quot;日期&quot;, &quot;摘要&quot;, &quot;借方&quot;, &quot;贷方&quot;, &quot;余额&quot;]) 数据 = [ [&quot;2024-01-01&quot;, &quot;上月结转&quot;, &quot;&quot;, &quot;&quot;, &quot;50000.00&quot;], [&quot;2024-01-05&quot;, &quot;客户A货款&quot;, &quot;&quot;, &quot;25000.00&quot;, &quot;75000.00&quot;], [&quot;2024-01-10&quot;, &quot;供应商B付款&quot;, &quot;15000.00&quot;, &quot;&quot;, &quot;60000.00&quot;], [&quot;2024-01-15&quot;, &quot;工资发放&quot;, &quot;35000.00&quot;, &quot;&quot;, &quot;25000.00&quot;], # 企业未记录客户C的货款 [&quot;2024-01-22&quot;, &quot;客户E货款（未达）&quot;, &quot;&quot;, &quot;15000.00&quot;, &quot;40000.00&quot;], # 银行未记录 [&quot;2024-01-25&quot;, &quot;水电费&quot;, &quot;1200.00&quot;, &quot;&quot;, &quot;38800.00&quot;], [&quot;2024-01-28&quot;, &quot;客户D货款&quot;, &quot;&quot;, &quot;20000.00&quot;, &quot;58800.00&quot;], [&quot;2024-01-30&quot;, &quot;银行手续费&quot;, &quot;50.00&quot;, &quot;&quot;, &quot;58750.00&quot;] ] writer.writerows(数据)# 执行对账对账系统.加载银行数据(&quot;银行对账单.csv&quot;, 日期列=&quot;交易日期&quot;, 金额列=&quot;贷方金额&quot;, 摘要列=&quot;摘要&quot;, 余额列=&quot;余额&quot;)对账系统.加载企业数据(&quot;企业账目.csv&quot;, 日期列=&quot;日期&quot;, 贷方列=&quot;贷方&quot;, 借方列=&quot;借方&quot;, 摘要列=&quot;摘要&quot;, 余额列=&quot;余额&quot;)对账结果 = 对账系统.智能对账(容差天数=3, 容差金额=0.01)excel报告 = 对账系统.生成Excel报告(&quot;银行对账报告_2024.xlsx&quot;)print(f&quot;
📊 对账完成！&quot;)print(f&quot;Excel报告：&#123;excel报告&#125;&quot;)
