# 专业版银行对账系统print(&quot;=== 专业银行对账系统 ===&quot;)import sqlite3import hashlibfrom datetime import datetime, timedeltaimport pandas as pdfrom openpyxl import Workbookfrom openpyxl.styles import Font, PatternFill, Alignment, Border, Sidefrom openpyxl.chart import LineChart, Referenceclass 专业对账系统: def __init__(self): self.conn = sqlite3.connect(&#x27;:memory:&#x27;) # 使用内存数据库 self.创建数据库表() def 创建数据库表(self): &quot;&quot;&quot;创建数据库表结构&quot;&quot;&quot; cursor = self.conn.cursor() # 银行交易表 cursor.execute(&#x27;&#x27;&#x27; CREATE TABLE 银行交易 ( id INTEGER PRIMARY KEY AUTOINCREMENT, 交易日期 DATE, 摘要 TEXT, 借方金额 REAL, 贷方金额 REAL, 余额 REAL, 交易哈希 TEXT UNIQUE, 对账状态 TEXT DEFAULT &#x27;未对账&#x27;, 对账时间 TIMESTAMP, 差异说明 TEXT ) &#x27;&#x27;&#x27;) # 企业账目表 cursor.execute(&#x27;&#x27;&#x27; CREATE TABLE 企业账目 ( id INTEGER PRIMARY KEY AUTOINCREMENT, 日期 DATE, 摘要 TEXT, 借方 REAL, 贷方 REAL, 金额 REAL, 余额 REAL, 交易哈希 TEXT UNIQUE, 对账状态 TEXT DEFAULT &#x27;未对账&#x27;, 对账时间 TIMESTAMP, 差异说明 TEXT ) &#x27;&#x27;&#x27;) # 对账结果表 cursor.execute(&#x27;&#x27;&#x27; CREATE TABLE 对账结果 ( id INTEGER PRIMARY KEY AUTOINCREMENT, 银行交易ID INTEGER, 企业账目ID INTEGER, 对账类型 TEXT, 匹配度 REAL, 差异说明 TEXT, 对账时间 TIMESTAMP, 操作员 TEXT, FOREIGN KEY (银行交易ID) REFERENCES 银行交易(id), FOREIGN KEY (企业账目ID) REFERENCES 企业账目(id) ) &#x27;&#x27;&#x27;) self.conn.commit() def 计算交易哈希(self, 日期, 金额, 摘要): &quot;&quot;&quot;计算交易唯一哈希值&quot;&quot;&quot; 哈希字符串 = f&quot;&#123;日期&#125;_&#123;金额&#125;_&#123;摘要[:10]&#125;&quot; return hashlib.md5(哈希字符串.encode()).hexdigest() def 导入银行数据(self, 数据框): &quot;&quot;&quot;导入银行数据&quot;&quot;&quot; cursor = self.conn.cursor() 导入数量 = 0 for _, 行 in 数据框.iterrows(): 交易哈希 = self.计算交易哈希(行[&#x27;交易日期&#x27;], 行[&#x27;贷方金额&#x27;] - 行[&#x27;借方金额&#x27;], 行[&#x27;摘要&#x27;]) try: cursor.execute(&#x27;&#x27;&#x27; INSERT INTO 银行交易 (交易日期, 摘要, 借方金额, 贷方金额, 余额, 交易哈希) VALUES (?, ?, ?, ?, ?, ?) &#x27;&#x27;&#x27;, (行[&#x27;交易日期&#x27;], 行[&#x27;摘要&#x27;], 行[&#x27;借方金额&#x27;], 行[&#x27;贷方金额&#x27;], 行[&#x27;余额&#x27;], 交易哈希)) 导入数量 += 1 except sqlite3.IntegrityError: # 重复交易，跳过 continue self.conn.commit() print(f&quot;✅ 银行数据导入完成：&#123;导入数量&#125;笔&quot;) return 导入数量 def 导入企业数据(self, 数据框): &quot;&quot;&quot;导入企业数据&quot;&quot;&quot; cursor = self.conn.cursor() 导入数量 = 0 for _, 行 in 数据框.iterrows(): 金额 = 行[&#x27;贷方&#x27;] - 行[&#x27;借方&#x27;] 交易哈希 = self.计算交易哈希(行[&#x27;日期&#x27;], 金额, 行[&#x27;摘要&#x27;]) try: cursor.execute(&#x27;&#x27;&#x27; INSERT INTO 企业账目 (日期, 摘要, 借方, 贷方, 金额, 余额, 交易哈希) VALUES (?, ?, ?, ?, ?, ?, ?) &#x27;&#x27;&#x27;, (行[&#x27;日期&#x27;], 行[&#x27;摘要&#x27;], 行[&#x27;借方&#x27;], 行[&#x27;贷方&#x27;], 金额, 行[&#x27;余额&#x27;], 交易哈希)) 导入数量 += 1 except sqlite3.IntegrityError: # 重复交易，跳过 continue self.conn.commit() print(f&quot;✅ 企业数据导入完成：&#123;导入数量&#125;笔&quot;) return 导入数量 def 执行智能对账(self, 容差天数=2, 容差金额=0.01): &quot;&quot;&quot;执行智能对账&quot;&quot;&quot; cursor = self.conn.cursor() print(&quot;🔍 执行智能对账...&quot;) # 1. 精确匹配（哈希值相同） cursor.execute(&#x27;&#x27;&#x27; SELECT b.id, c.id, b.交易日期, c.日期, b.金额, c.金额, b.摘要, c.摘要 FROM 银行交易 b JOIN 企业账目 c ON b.交易哈希 = c.交易哈希 WHERE b.对账状态 = &#x27;未对账&#x27; AND c.对账状态 = &#x27;未对账&#x27; &#x27;&#x27;&#x27;) 精确匹配 = cursor.fetchall() print(f&quot; 精确匹配：&#123;len(精确匹配)&#125;笔&quot;) for 匹配 in 精确匹配: 银行ID, 企业ID = 匹配[0], 匹配[1] # 更新对账状态 cursor.execute(&#x27;UPDATE 银行交易 SET 对账状态=?, 对账时间=? WHERE id=?&#x27;, (&#x27;已匹配&#x27;, datetime.now(), 银行ID)) cursor.execute(&#x27;UPDATE 企业账目 SET 对账状态=?, 对账时间=? WHERE id=?&#x27;, (&#x27;已匹配&#x27;, datetime.now(), 企业ID)) # 记录对账结果 cursor.execute(&#x27;&#x27;&#x27; INSERT INTO 对账结果 (银行交易ID, 企业账目ID, 对账类型, 匹配度, 对账时间) VALUES (?, ?, ?, ?, ?) &#x27;&#x27;&#x27;, (银行ID, 企业ID, &#x27;精确匹配&#x27;, 1.0, datetime.now())) # 2. 模糊匹配（日期和金额相近） cursor.execute(&#x27;&#x27;&#x27; SELECT b.id, c.id, b.交易日期, c.日期, b.金额, c.金额, b.摘要, c.摘要 FROM 银行交易 b, 企业账目 c WHERE b.对账状态 = &#x27;未对账&#x27; AND c.对账状态 = &#x27;未对账&#x27; AND ABS(b.金额 - c.金额) &lt;= ? AND ABS(JULIANDAY(b.交易日期) - JULIANDAY(c.日期)) &lt;= ? &#x27;&#x27;&#x27;, (容差金额, 容差天数)) 模糊匹配 = cursor.fetchall() print(f&quot; 模糊匹配：&#123;len(模糊匹配)&#125;笔&quot;) for 匹配 in 模糊匹配: 银行ID, 企业ID, 银行日期, 企业日期, 银行金额, 企业金额, 银行摘要, 企业摘要 = 匹配 # 计算匹配度 日期差异 = abs((pd.to_datetime(银行日期) - pd.to_datetime(企业日期)).days) 金额差异 = abs(银行金额 - 企业金额) 匹配度 = max(0, 1 - 日期差异/容差天数 * 0.5 - 金额差异/max(abs(银行金额), abs(企业金额)) * 0.5) # 更新对账状态 cursor.execute(&#x27;UPDATE 银行交易 SET 对账状态=?, 对账时间=?, 差异说明=? WHERE id=?&#x27;, (&#x27;模糊匹配&#x27;, datetime.now(), f&#x27;日期差异&#123;日期差异&#125;天&#x27;, 银行ID)) cursor.execute(&#x27;UPDATE 企业账目 SET 对账状态=?, 对账时间=?, 差异说明=? WHERE id=?&#x27;, (&#x27;模糊匹配&#x27;, datetime.now(), f&#x27;金额差异&#123;金额差异:.2f&#125;元&#x27;, 企业ID)) # 记录对账结果 cursor.execute(&#x27;&#x27;&#x27; INSERT INTO 对账结果 (银行交易ID, 企业账目ID, 对账类型, 匹配度, 差异说明, 对账时间) VALUES (?, ?, ?, ?, ?, ?) &#x27;&#x27;&#x27;, (银行ID, 企业ID, &#x27;模糊匹配&#x27;, 匹配度, f&#x27;日期差异&#123;日期差异&#125;天,金额差异&#123;金额差异:.2f&#125;元&#x27;, datetime.now())) self.conn.commit() # 统计结果 cursor.execute(&#x27;SELECT COUNT(*) FROM 银行交易 WHERE 对账状态=&quot;已匹配&quot;&#x27;) 银行已匹配 = cursor.fetchone()[0] cursor.execute(&#x27;SELECT COUNT(*) FROM 企业账目 WHERE 对账状态=&quot;已匹配&quot;&#x27;) 企业已匹配 = cursor.fetchone()[0] cursor.execute(&#x27;SELECT COUNT(*) FROM 银行交易 WHERE 对账状态=&quot;未对账&quot;&#x27;) 银行未匹配 = cursor.fetchone()[0] cursor.execute(&#x27;SELECT COUNT(*) FROM 企业账目 WHERE 对账状态=&quot;未对账&quot;&#x27;) 企业未匹配 = cursor.fetchone()[0] return &#123; &quot;银行已匹配&quot;: 银行已匹配, &quot;企业已匹配&quot;: 企业已匹配, &quot;银行未匹配&quot;: 银行未匹配, &quot;企业未匹配&quot;: 企业未匹配, &quot;精确匹配&quot;: len(精确匹配), &quot;模糊匹配&quot;: len(模糊匹配) &#125; def 生成专业报告(self, 文件名=&quot;专业对账报告.xlsx&quot;): &quot;&quot;&quot;生成专业的Excel对账报告&quot;&quot;&quot; wb = Workbook() # 获取对账数据 cursor = self.conn.cursor() # 1. 执行汇总 汇总结果 = self.执行智能对账() # 2. 汇总报告表 汇总表 = wb.active 汇总表.title = &quot;对账汇总&quot; # 标题 汇总表[&quot;A1&quot;] = &quot;银行对账汇总报告&quot; 汇总表[&quot;A1&quot;].font = Font(size=18, bold=True, color=&quot;FFFFFF&quot;) 汇总表[&quot;A1&quot;].fill = PatternFill(start_color=&quot;366092&quot;, end_color=&quot;366092&quot;, fill_type=&quot;solid&quot;) 汇总表.merge_cells(&quot;A1:F1&quot;) 汇总表[&quot;A1&quot;].alignment = Alignment(horizontal=&quot;center&quot;) # 基本信息 汇总表[&quot;A3&quot;] = f&quot;报告生成时间：&#123;datetime.now().strftime(&#x27;%Y-%m-%d %H:%M:%S&#x27;)&#125;&quot; 汇总表[&quot;A3&quot;].font = Font(size=10, italic=True) # 对账结果汇总 汇总数据 = [ [&quot;对账结果&quot;, &quot;笔数&quot;, &quot;占比&quot;, &quot;状态说明&quot;], [&quot;精确匹配&quot;, 汇总结果[&quot;精确匹配&quot;], f&quot;&#123;汇总结果[&#x27;精确匹配&#x27;]/max(汇总结果[&#x27;银行已匹配&#x27;], 1)*100:.1f&#125;%&quot;, &quot;完全一致&quot;], [&quot;模糊匹配&quot;, 汇总结果[&quot;模糊匹配&quot;], f&quot;&#123;汇总结果[&#x27;模糊匹配&#x27;]/max(汇总结果[&#x27;银行已匹配&#x27;], 1)*100:.1f&#125;%&quot;, &quot;金额相近，日期差异&quot;], [&quot;银行未匹配&quot;, 汇总结果[&quot;银行未匹配&quot;], f&quot;&#123;汇总结果[&#x27;银行未匹配&#x27;]/max(len(self.银行数据), 1)*100:.1f&#125;%&quot;, &quot;银行有，企业无&quot;], [&quot;企业未匹配&quot;, 汇总结果[&quot;企业未匹配&quot;], f&quot;&#123;汇总结果[&#x27;企业未匹配&#x27;]/max(len(self.企业数据), 1)*100:.1f&#125;%&quot;, &quot;企业有，银行无&quot;] ] 起始行 = 5 for 行号, 数据行 in enumerate(汇总数据, 起始行): for 列号, 值 in enumerate(数据行, 1): 单元格 = 汇总表.cell(row=行号, column=列号, value=值) if 行号 == 起始行: 单元格.font = Font(bold=True) 单元格.fill = PatternFill(start_color=&quot;D9E2F3&quot;, end_color=&quot;D9E2F3&quot;, fill_type=&quot;solid&quot;) # 3. 未匹配明细表 明细表 = wb.create_sheet(&quot;未匹配明细&quot;) # 银行未匹配 cursor.execute(&#x27;&#x27;&#x27; SELECT 交易日期, 摘要, 借方金额, 贷方金额, 余额, 差异说明 FROM 银行交易 WHERE 对账状态 = &#x27;未对账&#x27; ORDER BY 交易日期 &#x27;&#x27;&#x27;) 银行未匹配 = cursor.fetchall() 明细表[&quot;A1&quot;] = &quot;银行未达账项&quot; 明细表[&quot;A1&quot;].font = Font(size=14, bold=True, color=&quot;FF0000&quot;) if 银行未匹配: # 表头 表头 = [&quot;日期&quot;, &quot;摘要&quot;, &quot;借方&quot;, &quot;贷方&quot;, &quot;余额&quot;, &quot;备注&quot;] for 列号, 标题 in enumerate(表头, 1): 明细表.cell(row=3, column=列号, value=标题) 明细表.cell(row=3, column=列号).font = Font(bold=True) # 数据 for 行号, 记录 in enumerate(银行未匹配, 4): for 列号, 值 in enumerate(记录, 1): 明细表.cell(row=行号, column=列号, value=值) # 小计 小计行 = len(银行未匹配) + 5 明细表.cell(row=小计行, column=1, value=&quot;小计&quot;) 明细表.cell(row=小计行, column=3, value=f&quot;=SUM(C4:C&#123;小计行-1&#125;)&quot;) # 借方合计 明细表.cell(row=小计行, column=4, value=f&quot;=SUM(D4:D&#123;小计行-1&#125;)&quot;) # 贷方合计 明细表.cell(row=小计行, column=1).font = Font(bold=True) # 企业未匹配 起始行 = len(银行未匹配) + 8 if 银行未匹配 else 5 明细表.cell(row=起始行, column=1, value=&quot;企业未达账项&quot;) 明细表.cell(row=起始行, column=1).font = Font(size=14, bold=True, color=&quot;FF0000&quot;) cursor.execute(&#x27;&#x27;&#x27; SELECT 日期, 摘要, 借方, 贷方, 余额, 差异说明 FROM 企业账目 WHERE 对账状态 = &#x27;未对账&#x27; ORDER BY 日期 &#x27;&#x27;&#x27;) 企业未匹配 = cursor.fetchall() if 企业未匹配: 数据起始行 = 起始行 + 2 # 表头 for 列号, 标题 in enumerate([&quot;日期&quot;, &quot;摘要&quot;, &quot;借方&quot;, &quot;贷方&quot;, &quot;余额&quot;, &quot;备注&quot;], 1): 明细表.cell(row=数据起始行, column=列号, value=标题) 明细表.cell(row=数据起始行, column=列号).font = Font(bold=True) # 数据 for 行号, 记录 in enumerate(企业未匹配, 数据起始行 + 1): for 列号, 值 in enumerate(记录, 1): 明细表.cell(row=行号, column=列号, value=值) # 调整列宽 for 列 in [&quot;A&quot;, &quot;B&quot;, &quot;C&quot;, &quot;D&quot;, &quot;E&quot;, &quot;F&quot;]: 明细表.column_dimensions[列].width = 15 # 4. 调整分录建议表 建议表 = wb.create_sheet(&quot;调整分录建议&quot;) 建议表[&quot;A1&quot;] = &quot;调整分录建议&quot; 建议表[&quot;A1&quot;].font = Font(size=14, bold=True) 调整建议 = [ [&quot;序号&quot;, &quot;调整事项&quot;, &quot;会计分录&quot;, &quot;金额&quot;, &quot;说明&quot;], [&quot;1&quot;, &quot;银行已收企业未收&quot;, &quot;借：银行存款
贷：应收账款&quot;, &quot;按未达金额&quot;, &quot;银行已入账，企业未获取回单&quot;], [&quot;2&quot;, &quot;银行已付企业未付&quot;, &quot;借：应付账款
贷：银行存款&quot;, &quot;按未达金额&quot;, &quot;银行已扣款，企业未获取回单&quot;], [&quot;3&quot;, &quot;企业已收银行未收&quot;, &quot;借：其他应收款
贷：应收账款&quot;, &quot;按未达金额&quot;, &quot;企业已记账，银行尚未到账&quot;], [&quot;4&quot;, &quot;企业已付银行未付&quot;, &quot;借：应付账款
贷：其他应付款&quot;, &quot;按未达金额&quot;, &quot;企业已付款，银行尚未扣款&quot;] ] for 行号, 数据行 in enumerate(调整建议, 3): for 列号, 值 in enumerate(数据行, 1): 单元格 = 建议表.cell(row=行号, column=列号, value=值) if 行号 == 3: 单元格.font = Font(bold=True) 单元格.fill = PatternFill(start_color=&quot;E8F4FD&quot;, end_color=&quot;E8F4FD&quot;, fill_type=&quot;solid&quot;) if 列号 == 3: # 会计分录列 单元格.alignment = Alignment(wrap_text=True) # 调整列宽 for 列号, 宽度 in enumerate([5, 15, 20, 12, 30], 1): 列字母 = chr(64 + 列号) 建议表.column_dimensions[列字母].width = 宽度 # 保存文件 wb.save(文件名) print(f&quot;✅ 专业对账报告已生成：&#123;文件名&#125;&quot;) return 文件名# 使用专业对账系统专业系统 = 专业对账系统()# 创建示例数据（如果没有真实数据）import randomfrom datetime import datetime, timedeltadef 生成示例银行数据(文件名=&quot;示例银行数据.csv&quot;, 记录数=20): &quot;&quot;&quot;生成示例银行数据&quot;&quot;&quot; 起始日期 = datetime(2024, 1, 1) 当前余额 = 50000 数据 = [] 数据.append([&quot;交易日期&quot;, &quot;摘要&quot;, &quot;借方金额&quot;, &quot;贷方金额&quot;, &quot;余额&quot;]) for i in range(记录数): 日期 = 起始日期 + timedelta(days=random.randint(1, 30)) # 随机生成交易 交易类型 = random.choice([&quot;收入&quot;, &quot;支出&quot;]) if 交易类型 == &quot;收入&quot;: 金额 = random.randint(1000, 10000) 摘要 = random.choice([&quot;客户货款&quot;, &quot;利息收入&quot;, &quot;退款&quot;]) 借方, 贷方 = 0, 金额 当前余额 += 金额 else: 金额 = random.randint(500, 5000) 摘要 = random.choice([&quot;供应商付款&quot;, &quot;工资&quot;, &quot;水电费&quot;, &quot;办公费&quot;]) 借方, 贷方 = 金额, 0 当前余额 -= 金额 数据.append([ 日期.strftime(&quot;%Y-%m-%d&quot;), 摘要, f&quot;&#123;借方:.2f&#125;&quot;, f&quot;&#123;贷方:.2f&#125;&quot;, f&quot;&#123;当前余额:.2f&#125;&quot; ]) with open(文件名, &quot;w&quot;, encoding=&quot;utf-8&quot;, newline=&#x27;&#x27;) as f: writer = csv.writer(f) writer.writerows(数据) return 文件名def 生成示例企业数据(文件名=&quot;示例企业数据.csv&quot;, 记录数=18): &quot;&quot;&quot;生成示例企业数据（故意制造一些差异）&quot;&quot;&quot; 起始日期 = datetime(2024, 1, 1) 当前余额 = 50000 数据 = [] 数据.append([&quot;日期&quot;, &quot;摘要&quot;, &quot;借方&quot;, &quot;贷方&quot;, &quot;余额&quot;]) 交易列表 = [ (&quot;2024-01-01&quot;, &quot;上月结转&quot;, 0, 0, 50000), (&quot;2024-01-05&quot;, &quot;客户A货款&quot;, 0, 25000, 75000), (&quot;2024-01-10&quot;, &quot;供应商B付款&quot;, 15000, 0, 60000), (&quot;2024-01-15&quot;, &quot;工资发放&quot;, 35000, 0, 25000), # 缺少客户C的记录（银行未达） (&quot;2024-01-22&quot;, &quot;客户E货款（未达）&quot;, 0, 15000, 40000), # 银行没有这笔 (&quot;2024-01-25&quot;, &quot;水电费&quot;, 1200, 0, 38800), (&quot;2024-01-28&quot;, &quot;客户D货款&quot;, 0, 20000, 58800), (&quot;2024-01-30&quot;, &quot;银行手续费&quot;, 50, 0, 58750), # 添加一些银行没有的交易 (&quot;2024-02-05&quot;, &quot;预收客户款&quot;, 0, 8000, 66750), (&quot;2024-02-10&quot;, &quot;预付供应商款&quot;, 5000, 0, 61750), ] for 日期, 摘要, 借方, 贷方, 余额 in 交易列表: 数据.append([日期, 摘要, f&quot;&#123;借方:.2f&#125;&quot;, f&quot;&#123;贷方:.2f&#125;&quot;, f&quot;&#123;余额:.2f&#125;&quot;]) # 添加一些随机交易 起始日期 = datetime(2024, 2, 15) for i in range(记录数 - len(交易列表)): 日期 = 起始日期 + timedelta(days=random.randint(1, 30)) 交易类型 = random.choice([&quot;收入&quot;, &quot;支出&quot;]) if 交易类型 == &quot;收入&quot;: 金额 = random.randint(2000, 8000) 摘要 = random.choice([&quot;服务费收入&quot;, &quot;其他收入&quot;]) 借方, 贷方 = 0, 金额 else: 金额 = random.randint(1000, 3000) 摘要 = random.choice([&quot;办公费&quot;, &quot;差旅费&quot;, &quot;通讯费&quot;]) 借方, 贷方 = 金额, 0 当前余额 = 当前余额 - 借方 + 贷方 数据.append([ 日期.strftime(&quot;%Y-%m-%d&quot;), 摘要, f&quot;&#123;借方:.2f&#125;&quot;, f&quot;&#123;贷方:.2f&#125;&quot;, f&quot;&#123;当前余额:.2f&#125;&quot; ]) with open(文件名, &quot;w&quot;, encoding=&quot;utf-8&quot;, newline=&#x27;&#x27;) as f: writer = csv.writer(f) writer.writerows(数据) return 文件名# 生成示例数据银行文件 = 生成示例银行数据(&quot;专业银行数据.csv&quot;, 25)企业文件 = 生成示例企业数据(&quot;专业企业数据.csv&quot;, 22)# 加载数据银行df = pd.read_csv(银行文件)企业df = pd.read_csv(企业文件)# 数据预处理银行df[&#x27;交易日期&#x27;] = pd.to_datetime(银行df[&#x27;交易日期&#x27;])银行df[&#x27;借方金额&#x27;] = pd.to_numeric(银行df[&#x27;借方金额&#x27;], errors=&#x27;coerce&#x27;).fillna(0)银行df[&#x27;贷方金额&#x27;] = pd.to_numeric(银行df[&#x27;贷方金额&#x27;], errors=&#x27;coerce&#x27;).fillna(0)银行df[&#x27;余额&#x27;] = pd.to_numeric(银行df[&#x27;余额&#x27;], errors=&#x27;coerce&#x27;).fillna(0)企业df[&#x27;日期&#x27;] = pd.to_datetime(企业df[&#x27;日期&#x27;])企业df[&#x27;借方&#x27;] = pd.to_numeric(企业df[&#x27;借方&#x27;], errors=&#x27;coerce&#x27;).fillna(0)企业df[&#x27;贷方&#x27;] = pd.to_numeric(企业df[&#x27;贷方&#x27;], errors=&#x27;coerce&#x27;).fillna(0)企业df[&#x27;余额&#x27;] = pd.to_numeric(企业df[&#x27;余额&#x27;], errors=&#x27;coerce&#x27;).fillna(0)# 导入数据专业系统.导入银行数据(银行df)专业系统.导入企业数据(企业df)# 执行对账对账统计 = 专业系统.执行智能对账(容差天数=3, 容差金额=0.01)# 生成专业报告专业报告 = 专业系统.生成专业报告(&quot;专业银行对账报告.xlsx&quot;)print(f&quot;
📊 专业对账完成！&quot;)print(f&quot;报告文件：&#123;专业报告&#125;&quot;)print(f&quot;
