📖 开篇语还记得你第一次收到客户信息表的情景吗？
手机号有的是13800138000，有的是138-0013-8000，还有的是空着的日期格式五花八门：2024/1/1、2024-01-01、1-Jan-2024客户名称前后有空格，有的还多了个“有限公司”邮箱地址明显写错了：zhangsan@email、lisi123@com这就是“脏数据”——现实世界中的数据从来都不是完美的！
今天我们要学的，就是让Python帮你把这些“脏数据”变成“干净数据”。就像财务做账前的整理工作一样，数据清洗是数据分析的第一步，也是最重要的一步！
🎯 今日学习目标 识别和处理缺失值（空值、NaN） 统一数据格式（日期、数字、文本） 实战清理客户信息表（比手工清洗快100倍）
🧹 什么是数据清洗？脏数据的常见类型
脏数据类型 示例 清洗方法
缺失值 手机号：空值 填充或删除
格式不统一 日期：2024/1/1 vs 2024-01-01 标准化格式
数据错误 邮箱：zhangsan\@email 校验和修正
重复数据 同一个客户录入两次 去重
多余空格 “ 张三 ” 去除空格
数据类型错误 “123.45元”（文本） 转换为数字
为什么数据清洗很重要？ 举个财务的例子🌰：原始数据：应收账款- 客户A：15,000元 ✅- 客户B：空值 ❌（是0元还是未统计？）- 客户C：&quot;12,500元&quot;（文本）❌（无法计算）- 客户D：12,500.00 ✅清洗后：- 客户A：15000.00 ✅- 客户B：0.00 ✅（明确为0）- 客户C：12500.00 ✅（转换为数字）- 客户D：12500.00 ✅总计：15000 + 0 + 12500 + 12500 = 50000元（清洗前无法准确计算总计！）
🔍 识别脏数据：先发现问题创建示例客户信息表import pandas as pdimport numpy as np# 创建一个&quot;脏兮兮&quot;的客户信息表客户信息 = pd.DataFrame(&#123; &#x27;客户ID&#x27;: [&#x27;C001&#x27;, &#x27;C002&#x27;, &#x27;C003&#x27;, &#x27;C004&#x27;, &#x27;C005&#x27;, &#x27;C006&#x27;, &#x27;C007&#x27;, &#x27;C008&#x27;, &#x27;C009&#x27;, &#x27;C010&#x27;], &#x27;客户名称&#x27;: [&#x27; 张三 &#x27;, &#x27;李四&#x27;, &#x27;王五&#x27;, None, &#x27;赵六&#x27;, &#x27;钱七&#x27;, &#x27;孙八&#x27;, &#x27;周九&#x27;, &#x27;吴十&#x27;, &#x27;郑十一&#x27;], &#x27;联系电话&#x27;: [&#x27;13800138000&#x27;, &#x27;138-0013-8001&#x27;, None, &#x27;1381234567&#x27;, &#x27;13800138004&#x27;, &#x27;not-a-phone&#x27;, &#x27;13800138005&#x27;, &#x27;&#x27;, &#x27;138-0013-8006&#x27;, &#x27;13800138007&#x27;], &#x27;邮箱&#x27;: [&#x27;zhangsan@email.com&#x27;, &#x27;lisi@company&#x27;, None, &#x27;wangwu123@&#x27;, &#x27;zhaoliu@email.com&#x27;, &#x27;qianqi@email.com&#x27;, &#x27;sunba@email.com&#x27;, &#x27;zhoujiu@&#x27;, &#x27;wushi@email.com&#x27;, &#x27;zhengshiyi@email.com&#x27;], &#x27;注册日期&#x27;: [&#x27;2024-01-01&#x27;, &#x27;2024/01/02&#x27;, &#x27;2024.01.03&#x27;, None, &#x27;2024-01-05&#x27;, &#x27;2024-01-06&#x27;, &#x27;2024-01-07&#x27;, &#x27;2024-01-08&#x27;, &#x27;2024-01-09&#x27;, &#x27;2024-01-10&#x27;], &#x27;信用等级&#x27;: [&#x27;A&#x27;, &#x27;B&#x27;, &#x27;A&#x27;, &#x27;C&#x27;, None, &#x27;B&#x27;, &#x27;A&#x27;, &#x27;C&#x27;, &#x27;B&#x27;, &#x27;A&#x27;], &#x27;应收账款&#x27;: [&#x27;15000.50&#x27;, &#x27;25000&#x27;, None, &#x27;18000.75&#x27;, &#x27;not-a-number&#x27;, &#x27;22000&#x27;, &#x27;19500.25&#x27;, &#x27;&#x27;, &#x27;16500&#x27;, &#x27;21000.80&#x27;], &#x27;状态&#x27;: [&#x27;活跃&#x27;, &#x27;活跃&#x27;, &#x27; 不活跃 &#x27;, &#x27;活跃&#x27;, &#x27;活跃&#x27;, &#x27;不活跃&#x27;, &#x27;活跃&#x27;, &#x27;活跃&#x27;, &#x27;不活跃&#x27;, &#x27;活跃&#x27;]&#125;)print(&quot;原始客户信息表：&quot;)print(客户信息)print(f&quot;
数据形状：&#123;客户信息.shape&#125;&quot;)print(f&quot;数据类型：
&#123;客户信息.dtypes&#125;&quot;) 数据质量检查def 数据质量报告(df, 表名=&quot;数据表&quot;): &quot;&quot;&quot;生成数据质量检查报告&quot;&quot;&quot; print(f&quot;
&#123;&#x27;=&#x27;*50&#125;&quot;) print(f&quot;&#123;表名&#125; - 数据质量检查报告&quot;) print(f&quot;&#123;&#x27;=&#x27;*50&#125;&quot;) print(f&quot;数据形状：&#123;df.shape&#125;&quot;) print(f&quot;列名：&#123;df.columns.tolist()&#125;&quot;) print(f&quot;
缺失值统计：&quot;) 缺失统计 = df.isnull().sum() for 列名, 缺失数 in 缺失统计.items(): 缺失率 = 缺失数 / len(df) * 100 print(f&quot; &#123;列名&#125;：&#123;缺失数&#125;个 (&#123;缺失率:.1f&#125;%)&quot;) print(f&quot;
重复数据：&#123;df.duplicated().sum()&#125;行&quot;) print(f&quot;
数据类型检查：&quot;) for 列名 in df.columns: 数据类型 = df[列名].dtype 唯一值数量 = df[列名].nunique() print(f&quot; &#123;列名&#125;：&#123;数据类型&#125;，唯一值：&#123;唯一值数量&#125;个&quot;) # 显示前5个唯一值 唯一值 = df[列名].dropna().unique()[:5] print(f&quot; 示例值：&#123;唯一值.tolist()&#125;&quot;)# 生成数据质量报告数据质量报告(客户信息, &quot;客户信息表&quot;)
🧽 处理缺失值：把“空”变成“满”识别缺失值# 查看缺失值分布print(&quot;缺失值分布：&quot;)print(客户信息.isnull().sum())# 查看包含缺失值的行print(&quot;
包含缺失值的行：&quot;)缺失行 = 客户信息[客户信息.isnull().any(axis=1)]print(缺失行)# 查看特定列的缺失值print(&quot;
邮箱地址缺失的行：&quot;)邮箱缺失 = 客户信息[客户信息[&#x27;邮箱&#x27;].isnull()]print(邮箱缺失[[&#x27;客户ID&#x27;, &#x27;客户名称&#x27;, &#x27;邮箱&#x27;]]) 方法1：删除缺失值（适合缺失比例小的数据）# 方法1.1：删除包含缺失值的行客户信息_删除缺失 = 客户信息.dropna()print(f&quot;删除缺失值后：&#123;客户信息_删除缺失.shape&#125;&quot;)# 方法1.2：删除特定列缺失的行客户信息_删除邮箱缺失 = 客户信息.dropna(subset=[&#x27;邮箱&#x27;])print(f&quot;删除邮箱缺失后：&#123;客户信息_删除邮箱缺失.shape&#125;&quot;)# 方法1.3：删除缺失比例高的列缺失比例 = 客户信息.isnull().sum() / len(客户信息)高缺失列 = 缺失比例[缺失比例 &gt; 0.3].index # 缺失超过30%的列客户信息_删除高缺失列 = 客户信息.drop(columns=高缺失列)print(f&quot;删除高缺失列后：&#123;客户信息_删除高缺失列.shape&#125;&quot;) 方法2：填充缺失值（更常用的方法）# 方法2.1：用固定值填充客户信息_填充1 = 客户信息.copy()客户信息_填充1[&#x27;信用等级&#x27;] = 客户信息_填充1[&#x27;信用等级&#x27;].fillna(&#x27;C&#x27;) # 默认C级# 方法2.2：用前一个值或后一个值填充客户信息_填充2 = 客户信息.copy()客户信息_填充2[&#x27;信用等级&#x27;] = 客户信息_填充2[&#x27;信用等级&#x27;].fillna(method=&#x27;ffill&#x27;) # 前向填充# 方法2.3：用平均值填充（适合数值型）客户信息_填充3 = 客户信息.copy()# 先转换应收账款为数值类型客户信息_填充3[&#x27;应收账款&#x27;] = pd.to_numeric(客户信息_填充3[&#x27;应收账款&#x27;], errors=&#x27;coerce&#x27;)客户信息_填充3[&#x27;应收账款&#x27;] = 客户信息_填充3[&#x27;应收账款&#x27;].fillna(客户信息_填充3[&#x27;应收账款&#x27;].mean())# 方法2.4：智能填充（根据其他列推断）客户信息_智能填充 = 客户信息.copy()# 根据销售员推断信用等级（同级别的销售员信用等级相同）信用等级映射 = 客户信息_智能填充.groupby(&#x27;销售员&#x27;)[&#x27;信用等级&#x27;].first().to_dict()客户信息_智能填充[&#x27;信用等级&#x27;] = 客户信息_智能填充.apply( lambda row: row[&#x27;信用等级&#x27;] if pd.notna(row[&#x27;信用等级&#x27;]) else 信用等级映射.get(row[&#x27;销售员&#x27;], &#x27;C&#x27;), axis=1)print(&quot;智能填充后的信用等级：&quot;)print(客户信息_智能填充[[&#x27;销售员&#x27;, &#x27;信用等级&#x27;]]) 方法3：插值填充（适合时间序列）# 创建时间序列数据时间序列数据 = pd.DataFrame(&#123; &#x27;日期&#x27;: pd.date_range(&#x27;2024-01-01&#x27;, periods=10), &#x27;销售额&#x27;: [10000, 12000, np.nan, 15000, 18000, np.nan, 22000, 25000, 28000, 30000]&#125;)print(&quot;原始时间序列：&quot;)print(时间序列数据)# 线性插值填充时间序列_插值 = 时间序列数据.copy()时间序列_插值[&#x27;销售额&#x27;] = 时间序列_插值[&#x27;销售额&#x27;].interpolate(method=&#x27;linear&#x27;)print(&quot;
插值填充后：&quot;)print(时间序列_插值)# 可视化插值效果import matplotlib.pyplot as pltplt.figure(figsize=(10, 6))plt.plot(时间序列数据[&#x27;日期&#x27;], 时间序列数据[&#x27;销售额&#x27;], &#x27;ro-&#x27;, label=&#x27;原始数据（含缺失）&#x27;)plt.plot(时间序列_插值[&#x27;日期&#x27;], 时间序列_插值[&#x27;销售额&#x27;], &#x27;bo-&#x27;, label=&#x27;插值填充后&#x27;)plt.title(&#x27;时间序列数据插值填充&#x27;)plt.xlabel(&#x27;日期&#x27;)plt.ylabel(&#x27;销售额&#x27;)plt.legend()plt.grid(True)plt.xticks(rotation=45)plt.tight_layout()plt.savefig(&#x27;时间序列插值.png&#x27;, dpi=300, bbox_inches=&#x27;tight&#x27;)plt.close()
