文本替换后：&quot;)print(文本数据_替换) 数字数据清洗# 创建混合格式的数字数据数字数据 = pd.DataFrame(&#123; &#x27;金额&#x27;: [&#x27;15000.50&#x27;, &#x27;25000&#x27;, None, &#x27;18,000.75&#x27;, &#x27;not-a-number&#x27;, &#x27;22000&#x27;, &#x27;19500.25&#x27;, &#x27;&#x27;, &#x27;16500&#x27;, &#x27;21000.80元&#x27;], &#x27;数量&#x27;: [&#x27;100&#x27;, &#x27;150件&#x27;, &#x27;200个&#x27;, &#x27;180&#x27;, &#x27;not-a-number&#x27;, &#x27;220&#x27;, &#x27;195&#x27;, &#x27;&#x27;, &#x27;165&#x27;, &#x27;210台&#x27;], &#x27;单价&#x27;: [&#x27;150.50元&#x27;, &#x27;166.67&#x27;, &#x27;152.50&#x27;, &#x27;158.33&#x27;, &#x27;not-a-number&#x27;, &#x27;157.50&#x27;, &#x27;156.25&#x27;, &#x27;&#x27;, &#x27;160.00&#x27;, &#x27;157.50元/件&#x27;]&#125;)print(&quot;原始数字数据：&quot;)print(数字数据)print(f&quot;
