&#123;数字数据.dtypes&#125;&quot;)# 清洗数字数据函数def 清洗数字列(系列, 列名=&quot;数字列&quot;): &quot;&quot;&quot;清洗包含非数字字符的数字列&quot;&quot;&quot; 清洗后的系列 = 系列.astype(str) # 先转换为字符串 # 移除常见的非数字字符 清洗后的系列 = 清洗后的系列.str.replace(&#x27;,&#x27;, &#x27;&#x27;) # 移除千分位逗号 清洗后的系列 = 清洗后的系列.str.replace(&#x27;元&#x27;, &#x27;&#x27;) # 移除货币符号 清洗后的系列 = 清洗后的系列.str.replace(&#x27;件&#x27;, &#x27;&#x27;) # 移除单位 清洗后的系列 = 清洗后的系列.str.replace(&#x27;个&#x27;, &#x27;&#x27;) 清洗后的系列 = 清洗后的系列.str.replace(&#x27;台&#x27;, &#x27;&#x27;) 清洗后的系列 = 清洗后的系列.str.replace(&#x27;/件&#x27;, &#x27;&#x27;) 清洗后的系列 = 清洗后的系列.str.strip() # 去除空格 # 将无法转换的值设为NaN 清洗后的系列 = pd.to_numeric(清洗后的系列, errors=&#x27;coerce&#x27;) return 清洗后的系列# 应用数字清洗数字数据_清洗 = 数字数据.copy()for 列名 in 数字数据.columns: 数字数据_清洗[列名] = 清洗数字列(数字数据[列名], 列名)print(&quot;
