最终清洗结果：&quot;)print(数字数据_最终) 日期数据清洗# 创建混乱的日期数据日期数据 = pd.DataFrame(&#123; &#x27;原始日期&#x27;: [&#x27;2024-01-01&#x27;, &#x27;2024/01/02&#x27;, &#x27;2024.01.03&#x27;, &#x27;01-Jan-2024&#x27;, &#x27;20240104&#x27;, &#x27;2024年1月5日&#x27;, &#x27;1/6/2024&#x27;, &#x27;Jan 7, 2024&#x27;, None, &#x27;not-a-date&#x27;], &#x27;事件&#x27;: [&#x27;订单1&#x27;, &#x27;订单2&#x27;, &#x27;订单3&#x27;, &#x27;订单4&#x27;, &#x27;订单5&#x27;, &#x27;订单6&#x27;, &#x27;订单7&#x27;, &#x27;订单8&#x27;, &#x27;订单9&#x27;, &#x27;订单10&#x27;]&#125;)print(&quot;原始日期数据：&quot;)print(日期数据)# 智能日期清洗函数def 智能日期清洗(日期系列): &quot;&quot;&quot;智能识别和清洗各种格式的日期&quot;&quot;&quot; 清洗后的日期 = pd.to_datetime(日期系列, errors=&#x27;coerce&#x27;, infer_datetime_format=True) # 如果还有无法识别的，尝试手动处理 无法识别 = 清洗后的日期.isnull() &amp; 日期系列.notnull() if 无法识别.sum() &gt; 0: print(f&quot;发现&#123;无法识别.sum()&#125;个无法识别的日期格式&quot;) # 尝试其他格式 for i, 原始值 in enumerate(日期系列[无法识别]): try: # 移除中文和特殊字符 清理值 = str(原始值).replace(&#x27;年&#x27;, &#x27;-&#x27;).replace(&#x27;月&#x27;, &#x27;-&#x27;).replace(&#x27;日&#x27;, &#x27;&#x27;) 清理值 = 清理值.replace(&#x27;Jan&#x27;, &#x27;01&#x27;).replace(&#x27;Feb&#x27;, &#x27;02&#x27;).replace(&#x27;Mar&#x27;, &#x27;03&#x27;) 清理值 = 清理值.replace(&#x27; &#x27;, &#x27;-&#x27;) # 尝试解析 解析日期 = pd.to_datetime(清理值, errors=&#x27;coerce&#x27;) if pd.notna(解析日期): 清洗后的日期.loc[清洗后的日期.index[无法识别][i]] = 解析日期 except: continue return 清洗后的日期# 应用日期清洗日期数据_清洗 = 日期数据.copy()日期数据_清洗[&#x27;标准日期&#x27;] = 智能日期清洗(日期数据[&#x27;原始日期&#x27;])print(&quot;
日期清洗结果：&quot;)print(日期数据_清洗)# 提取日期组件日期数据_增强 = 日期数据_清洗.copy()日期数据_增强[&#x27;年&#x27;] = 日期数据_增强[&#x27;标准日期&#x27;].dt.year日期数据_增强[&#x27;月&#x27;] = 日期_data_增强[&#x27;标准日期&#x27;].dt.month日期数据_增强[&#x27;日&#x27;] = 日期_data_增强[&#x27;标准日期&#x27;].dt.day日期数据_增强[&#x27;星期&#x27;] = 日期_data_增强[&#x27;标准日期&#x27;].dt.day_name()print(&quot;
增强后的日期数据：&quot;)print(日期数据_增强)
🧪 数据验证：确保清洗质量创建数据验证函数def 数据清洗质量检查(原始数据, 清洗后数据): &quot;&quot;&quot;检查数据清洗的质量&quot;&quot;&quot; print(&quot;=&quot;*60) print(&quot;数据清洗质量检查报告&quot;) print(&quot;=&quot;*60) print(f&quot;原始数据形状：&#123;原始数据.shape&#125;&quot;) print(f&quot;清洗后数据形状：&#123;清洗后_data.shape&#125;&quot;) # 缺失值检查 print(f&quot;
缺失值对比：&quot;) 原始缺失 = 原始数据.isnull().sum() 清洗缺失 = 清洗后数据.isnull().sum() for 列名 in 原始数据.columns: 原始缺失数 = 原始缺失[列名] 清洗缺失数 = 清洗缺失[列名] 改善 = 原始缺失数 - 清洗缺失数 if 改善 &gt; 0: print(f&quot; &#123;列名&#125;：&#123;原始缺失数&#125; → &#123;清洗缺失数&#125;（改善&#123;改善&#125;个）&quot;) elif 改善 &lt; 0: print(f&quot; &#123;列名&#125;：&#123;原始缺失数&#125; → &#123;清洗缺失数&#125;（新增&#123;abs(改善)&#125;个）⚠️&quot;) else: print(f&quot; &#123;列名&#125;：&#123;原始缺失数&#125; → &#123;清洗缺失数&#125;（无变化）&quot;) # 数据类型检查 print(f&quot;
数据类型变化：&quot;) for 列名 in 原始数据.columns: if 列名 in 清洗后_data.columns: 原始类型 = 原始数据[列名].dtype 清洗类型 = 清洗后_data[列名].dtype if 原始类型 != 清洗类型: print(f&quot; &#123;列名&#125;：&#123;原始类型&#125; → &#123;清洗_type&#125; ✅&quot;) # 数据范围检查 print(f&quot;
数据范围检查：&quot;) for 列名 in 清洗后_data.select_dtypes(include=[np.number]).columns: 最小值 = 清洗后_data[列名].min() 最大值 = 清洗后_data[列名].max() 平均值 = 清洗后_data[列名].mean() print(f&quot; &#123;列名&#125;：范围[&#123;最小值:.2f&#125;, &#123;最大值:.2f&#125;]，平均值&#123;平均值:.2f&#125;&quot;)# 使用质量检查函数数据清洗质量检查(客户信息, 客户信息_智能填充)
