# 客户信息清洗 - 基础版print(&quot;=== 客户信息清洗系统 ===&quot;)def 基础客户信息清洗(df): &quot;&quot;&quot;基础版客户信息清洗&quot;&quot;&quot; print(&quot;🔍 开始基础数据清洗...&quot;) # 1. 去除文本前后空格 print(&quot;1. 去除文本空格...&quot;) 文本列 = [&#x27;客户名称&#x27;, &#x27;状态&#x27;] for 列名 in 文本列: if 列名 in df.columns: df[列名] = df[列名].str.strip() # 2. 统一大小写 print(&quot;2. 统一状态大小写...&quot;) if &#x27;状态&#x27; in df.columns: df[&#x27;状态&#x27;] = df[&#x27;状态&#x27;].str.title() # 3. 处理缺失值 print(&quot;3. 处理缺失值...&quot;) # 客户名称缺失：标记为&quot;待补充&quot; if &#x27;客户名称&#x27; in df.columns: df[&#x27;客户名称&#x27;] = df[&#x27;客户名称&#x27;].fillna(&#x27;待补充&#x27;) # 信用等级缺失：默认为C级 if &#x27;信用等级&#x27; in df.columns: df[&#x27;信用等级&#x27;] = df[&#x27;信用等级&#x27;].fillna(&#x27;C&#x27;) # 4. 清洗数字数据 print(&quot;4. 清洗应收账款数据...&quot;) if &#x27;应收账款&#x27; in df.columns: df[&#x27;应收账款&#x27;] = pd.to_numeric(df[&#x27;应收账款&#x27;], errors=&#x27;coerce&#x27;) df[&#x27;应收账款&#x27;] = df[&#x27;应收账款&#x27;].fillna(0) # 5. 清洗电话号码 print(&quot;5. 清洗电话号码...&quot;) if &#x27;联系电话&#x27; in df.columns: # 移除所有非数字字符 df[&#x27;联系电话_清洗&#x27;] = df[&#x27;联系电话&#x27;].astype(str).str.replace(r&#x27;[^0-9]&#x27;, &#x27;&#x27;, regex=True) # 验证手机号长度（11位） df[&#x27;电话有效性&#x27;] = df[&#x27;联系电话_清洗&#x27;].str.len() == 11 # 6. 清洗邮箱地址 print(&quot;6. 清洗邮箱地址...&quot;) if &#x27;邮箱&#x27; in df.columns: # 基本邮箱格式验证 df[&#x27;邮箱有效性&#x27;] = df[&#x27;邮箱&#x27;].str.contains(&#x27;@&#x27;, na=False) # 填充无效邮箱 df.loc[~df[&#x27;邮箱有效性&#x27;], &#x27;邮箱&#x27;] = &#x27;待补充@company.com&#x27; print(&quot;✅ 基础清洗完成！&quot;) return df# 使用基础清洗客户信息_基础清洗 = 基础客户信息清洗(客户信息.copy())print(&quot;
基础清洗结果：&quot;)print(客户信息_基础清洗.head())
