# 专业数据清洗系统print(&quot;
=== 专业数据清洗系统 ===&quot;)from sklearn.impute import SimpleImputerfrom sklearn.preprocessing import StandardScaler, LabelEncoderimport joblibclass 专业数据清洗系统: def __init__(self): self.清洗规则 = &#123;&#125; self.清洗模型 = &#123;&#125; self.清洗历史 = [] def 分析数据质量(self, df): &quot;&quot;&quot;全面分析数据质量&quot;&quot;&quot; print(&quot;🔍 分析数据质量...&quot;) 质量报告 = &#123; &#x27;总体情况&#x27;: &#123;&#125;, &#x27;缺失值分析&#x27;: &#123;&#125;, &#x27;异常值分析&#x27;: &#123;&#125;, &#x27;格式一致性&#x27;: &#123;&#125;, &#x27;重复数据&#x27;: &#123;&#125; &#125; # 总体情况 质量报告[&#x27;总体情况&#x27;] = &#123; &#x27;数据形状&#x27;: df.shape, &#x27;列数&#x27;: len(df.columns), &#x27;行数&#x27;: len(df), &#x27;内存使用&#x27;: df.memory_usage(deep=True).sum() &#125; # 缺失值分析 缺失统计 = df.isnull().sum() 缺失比例 = (缺失统计 / len(df) * 100).round(2) 质量报告[&#x27;缺失值分析&#x27;] = &#123; &#x27;总缺失值&#x27;: 缺失统计.sum(), &#x27;缺失值比例&#x27;: 缺失比例.to_dict(), &#x27;完全缺失的行&#x27;: df.isnull().all(axis=1).sum(), &#x27;任何缺失的行&#x27;: df.isnull().any(axis=1).sum() &#125; # 异常值分析（使用IQR方法） 数值列 = df.select_dtypes(include=[np.number]).columns 异常值统计 = &#123;&#125; for 列名 in 数值列: Q1 = df[列名].quantile(0.25) Q3 = df[列名].quantile(0.75) IQR = Q3 - Q1 下限 = Q1 - 1.5 * IQR 上限 = Q3 + 1.5 * IQR 异常值 = df[(df[列名] &lt; 下限) | (df[列名] &gt; 上限)][列名] 异常值统计[列名] = &#123; &#x27;异常值数量&#x27;: len(异常值), &#x27;异常值比例&#x27;: len(异常值) / len(df) * 100, &#x27;下限&#x27;: 下限, &#x27;上限&#x27;: 上限 &#125; 质量报告[&#x27;异常值分析&#x27;] = 异常值统计 # 重复数据 完全重复 = df.duplicated().sum() 部分重复 = df.duplicated(subset=df.columns[:3]).sum() # 检查前3列 质量报告[&#x27;重复数据&#x27;] = &#123; &#x27;完全重复行&#x27;: 完全重复, &#x27;部分重复行&#x27;: 部分重复 - 完全重复, &#x27;重复率&#x27;: (完全重复 + max(0, 部分重复 - 完全重复)) / len(df) * 100 &#125; return 质量报告 def 智能清洗(self, df, 清洗配置=None): &quot;&quot;&quot;智能数据清洗&quot;&quot;&quot; print(&quot;🤖 开始智能数据清洗...&quot;) if 清洗配置 is None: 清洗配置 = self._生成默认清洗配置(df) df_清洗 = df.copy() # 1. 根据数据类型自动选择清洗策略 for 列名 in df.columns: 数据类型 = df[列名].dtype 唯一值数量 = df[列名].nunique() 缺失比例 = df[列名].isnull().sum() / len(df) print(f&quot; 处理列：&#123;列名&#125;（类型：&#123;数据类型&#125;，缺失率：&#123;缺失比例:.1%&#125;）&quot;) if pd.api.types.is_numeric_dtype(df[列名]): df_清洗 = self._清洗数值列(df_清洗, 列名, 缺失比例) elif pd.api.types.is_datetime64_dtype(df[列名]): df_清洗 = self._清洗日期列(df_清洗, 列名, 缺失比例) else: df_清洗 = self._清洗文本列(df_清洗, 列名, 唯一值数量, 缺失比例) # 2. 高级清洗技术 print(&quot; 应用高级清洗技术...&quot;) df_清洗 = self._高级清洗技术(df_清洗) # 3. 数据验证 print(&quot; 验证清洗结果...&quot;) 验证结果 = self._验证清洗结果(df, df_清洗) print(&quot;✅ 智能清洗完成！&quot;) return df_清洗, 验证结果 def _生成默认清洗配置(self, df): &quot;&quot;&quot;根据数据特征生成默认清洗配置&quot;&quot;&quot; 配置 = &#123;&#125; for 列名 in df.columns: 缺失比例 = df[列名].isnull().sum() / len(df) 数据类型 = df[列名].dtype 配置[列名] = &#123; &#x27;缺失值处理&#x27;: &#x27;智能填充&#x27; if 缺失比例 &lt; 0.3 else &#x27;删除行&#x27;, &#x27;异常值处理&#x27;: &#x27;标记&#x27;, &#x27;格式标准化&#x27;: True, &#x27;数据验证&#x27;: True &#125; return 配置 def _清洗数值列(self, df, 列名, 缺失比例): &quot;&quot;&quot;清洗数值列&quot;&quot;&quot; # 转换为数值类型 df[列名] = pd.to_numeric(df[列名], errors=&#x27;coerce&#x27;) # 处理缺失值 if 缺失比例 &lt; 0.1: # 缺失率小于10%，用中位数填充 中位数 = df[列名].median() df[列名] = df[列名].fillna(中位数) elif 缺失比例 &lt; 0.3: # 缺失率10-30%，用均值填充 均值 = df[列名].mean() df[列名] = df[列名].fillna(均值) else: # 缺失率大于30%，创建指示变量 df[f&#x27;&#123;列名&#125;_是否缺失&#x27;] = df[列名].isnull() df[列名] = df[列名].fillna(0) # 处理异常值 Q1 = df[列名].quantile(0.25) Q3 = df[列名].quantile(0.75) IQR = Q3 - Q1 下限 = Q1 - 1.5 * IQR 上限 = Q3 + 1.5 * IQR 异常值 = (df[列名] &lt; 下限) | (df[列名] &gt; 上限) if 异常值.sum() &gt; 0: df[f&#x27;&#123;列名&#125;_异常标记&#x27;] = 异常值 # 用边界值替换异常值 df.loc[df[列名] &lt; 下限, 列名] = 下限 df.loc[df[列名] &gt; 上限, 列名] = 上限 return df def _清洗日期列(self, df, 列名, 缺失比例): &quot;&quot;&quot;清洗日期列&quot;&quot;&quot; # 尝试多种日期格式 日期格式列表 = [ &#x27;%Y-%m-%d&#x27;, &#x27;%Y/%m/%d&#x27;, &#x27;%Y.%m.%d&#x27;, &#x27;%d-%b-%Y&#x27;, &#x27;%d %b %Y&#x27;, &#x27;%Y年%m月%d日&#x27;, &#x27;%m/%d/%Y&#x27;, &#x27;%Y%m%d&#x27; ] 成功解析 = pd.Series([False] * len(df)) for 日期格式 in 日期格式列表: 未解析 = ~成功解析 &amp; df[列名].notnull() if 未解析.sum() == 0: break try: 解析结果 = pd.to_datetime(df.loc[未解析, 列名], format=日期格式, errors=&#x27;coerce&#x27;) 有效解析 = 解析结果.notnull() df.loc[未解析 &amp; 有效解析, 列名] = 解析结果[有效解析] 成功解析 |= 有效解析 except: continue # 对无法解析的使用智能解析 仍然未解析 = ~成功解析 &amp; df[列名].notnull() if 仍然未解析.sum() &gt; 0: 智能结果 = pd.to_datetime(df.loc[仍然未解析, 列名], errors=&#x27;coerce&#x27;) df.loc[仍然未解析, 列名] = 智能结果 # 处理缺失值 if 缺失比例 &lt; 0.2: # 用中位数日期填充（对于时间序列） df[列名] = pd.to_datetime(df[列名]) 中位数日期 = df[列名].dropna().quantile(0.5) df[列名] = df[列名].fillna(中位数日期) else: # 用当前日期填充 df[列名] = pd.to_datetime(df[列名]) df[列名] = df[列名].fillna(datetime.now()) return df def _清洗文本列(self, df, 列名, 唯一值数量, 缺失比例): &quot;&quot;&quot;清洗文本列&quot;&quot;&quot; # 去除空白字符 df[列名] = df[列名].astype(str).str.strip() df[列名] = df[列名].str.replace(r&#x27;\s+&#x27;, &#x27; &#x27;, regex=True) # 处理缺失值 if 缺失比例 &gt; 0: if 唯一值数量 &lt; 20: # 分类变量 # 用众数填充 众数 = df[列名].mode()[0] if len(df[列名].mode()) &gt; 0 else &#x27;未知&#x27; df[列名] = df[列名].fillna(众数) else: # 文本变量 df[列名] = df[列名].fillna(&#x27;待补充&#x27;) # 标准化处理 if 列名 == &#x27;状态&#x27;: df[列名] = df[列名].str.title() elif 列名 == &#x27;信用等级&#x27;: # 标准化信用等级 有效等级 = [&#x27;A&#x27;, &#x27;B&#x27;, &#x27;C&#x27;, &#x27;D&#x27;] 无效等级 = ~df[列名].isin(有效等级) df.loc[无效等级, 列名] = &#x27;C&#x27; # 默认C级 return df def _高级清洗技术(self, df): &quot;&quot;&quot;高级清洗技术&quot;&quot;&quot; # 1. 重复数据处理 重复掩码 = df.duplicated() if 重复掩码.sum() &gt; 0: df[&#x27;是否重复&#x27;] = 重复掩码 df = df.drop_duplicates() # 2. 基于机器学习的缺失值填充（简化版） # 使用相关列预测缺失值 数值列 = df.select_dtypes(include=[np.number]).columns for 列名 in 数值列: if df[列名].isnull().sum() &gt; 0: # 使用其他数值列的均值进行预测 其他列 = [col for col in 数值列 if col != 列名] if len(其他列) &gt; 0: 缺失索引 = df[列名].isnull() 预测值 = df.loc[缺失索引, 其他列].mean(axis=1) df.loc[缺失索引, 列名] = 预测值 return df def _验证清洗结果(self, 原始数据, 清洗后数据): &quot;&quot;&quot;验证清洗结果&quot;&quot;&quot; 验证报告 = &#123; &#x27;清洗效果&#x27;: &#123;&#125;, &#x27;数据质量提升&#x27;: &#123;&#125;, &#x27;建议&#x27;: [] &#125; # 清洗效果评估 原始缺失率 = 原始数据.isnull().sum().sum() / (原始数据.shape[0] * 原始数据.shape[1]) 清洗缺失率 = 清洗后_data.isnull().sum().sum() / (清洗后_data.shape[0] * 清洗后_data.shape[1]) 验证报告[&#x27;清洗效果&#x27;] = &#123; &#x27;原始缺失率&#x27;: f&quot;&#123;原始缺失率:.2%&#125;&quot;, &#x27;清洗缺失率&#x27;: f&quot;&#123;清洗缺失率:.2%&#125;&quot;, &#x27;缺失率降低&#x27;: f&quot;&#123;(原始缺失率 - 清洗缺失率):.2%&#125;&quot; &#125; # 数据质量提升 原始重复率 = 原始数据.duplicated().sum() / len(原始数据) 清洗重复率 = 清洗后_data.duplicated().sum() / len(清洗后_data) 验证报告[&#x27;数据质量提升&#x27;] = &#123; &#x27;重复率降低&#x27;: f&quot;&#123;(原始重复率 - 清洗重复率):.2%&#125;&quot;, &#x27;数据完整性&#x27;: f&quot;&#123;(1 - 清洗缺失率):.2%&#125;&quot; &#125; # 建议 if 清洗缺失率 &gt; 0.1: 验证报告[&#x27;建议&#x27;].append(&quot;缺失率仍然较高，建议检查数据源质量&quot;) if 清洗后_data.select_dtypes(include=[np.number]).empty: 验证报告[&#x27;建议&#x27;].append(&quot;没有数值型数据，可能类型转换有问题&quot;) 验证报告[&#x27;建议&#x27;].append(&quot;建议定期执行数据清洗流程&quot;) return 验证报告# 使用专业清洗系统专业系统 = 专业数据清洗系统()# 分析原始数据质量质量报告 = 专业系统.分析数据质量(客户信息)print(&quot;📊 数据质量分析报告：&quot;)for 分类, 数据 in 质量报告.items(): print(f&quot;
&#123;分类&#125;：&quot;) for 项目, 值 in 数据.items(): print(f&quot; &#123;项目&#125;：&#123;值&#125;&quot;)# 执行智能清洗客户信息_专业清洗, 验证结果 = 专业系统.智能清洗(客户信息)print(f&quot;
✅ 专业清洗完成！&quot;)print(f&quot;清洗效果：缺失率从&#123;验证结果[&#x27;清洗效果&#x27;][&#x27;原始缺失率&#x27;]&#125;降低到&#123;验证结果[&#x27;清洗效果&#x27;][&#x27;清洗缺失率&#x27;]&#125;&quot;)# 保存清洗模型joblib.dump(专业系统, &#x27;客户信息清洗模型.pkl&#x27;)print(&quot;✅ 清洗模型已保存！&quot;)
