# 发票数据清洗挑战print(&quot;=== 发票数据清洗挑战 ===&quot;)# 创建复杂的发票数据发票数据 = pd.DataFrame(&#123; &#x27;发票号码&#x27;: [&#x27;12345678&#x27;, &#x27;87654321&#x27;, &#x27;ABCD1234&#x27;, &#x27;1234567&#x27;, &#x27;1234567890123&#x27;, None, &#x27;12345678&#x27;, &#x27;87654322&#x27;], &#x27;开票日期&#x27;: [&#x27;2024-01-01&#x27;, &#x27;2024/01/02&#x27;, &#x27;2024.01.03&#x27;, &#x27;01-Jan-2024&#x27;, &#x27;20240105&#x27;, &#x27;2024年1月6日&#x27;, None, &#x27;2024-01-08&#x27;], &#x27;购买方名称&#x27;: [&#x27; 张三公司 &#x27;, &#x27;李四企业&#x27;, &#x27;王五集团 &#x27;, &#x27; 赵六有限公司&#x27;, None, &#x27;钱七股份&#x27;, &#x27;孙八实业&#x27;, &#x27;周九集团&#x27;], &#x27;金额&#x27;: [&#x27;15000.50&#x27;, &#x27;25,000.00&#x27;, &#x27;18000.75元&#x27;, &#x27;not-a-number&#x27;, &#x27;22000&#x27;, None, &#x27;19500.25&#x27;, &#x27;21000.80&#x27;], &#x27;税额&#x27;: [&#x27;1950.07&#x27;, &#x27;3,250.00&#x27;, &#x27;2,340.10&#x27;, &#x27;invalid&#x27;, &#x27;2,860.00&#x27;, None, &#x27;2,535.03&#x27;, &#x27;2,730.10&#x27;], &#x27;税率&#x27;: [&#x27;13%&#x27;, &#x27;13%&#x27;, &#x27;13%&#x27;, &#x27;not-a-rate&#x27;, &#x27;13%&#x27;, None, &#x27;13%&#x27;, &#x27;13%&#x27;], &#x27;发票类型&#x27;: [&#x27;专用发票&#x27;, &#x27; 普通发票 &#x27;, &#x27;专用发票&#x27;, None, &#x27;电子发票&#x27;, &#x27;专用发票&#x27;, &#x27;普通发票&#x27;, &#x27;专用发票&#x27;], &#x27;发票状态&#x27;: [&#x27;正常&#x27;, &#x27;正常&#x27;, &#x27; 作废 &#x27;, &#x27;正常&#x27;, None, &#x27;正常&#x27;, &#x27;正常&#x27;, &#x27;正常&#x27;]&#125;)def 清洗发票数据(发票df): &quot;&quot;&quot;专业发票数据清洗&quot;&quot;&quot; print(&quot;🔍 开始清洗发票数据...&quot;) df = 发票df.copy() # 1. 发票号码标准化 print(&quot;1. 发票号码标准化...&quot;) # 移除所有非数字字符 df[&#x27;发票号码_清洗&#x27;] = df[&#x27;发票号码&#x27;].astype(str).str.replace(r&#x27;[^0-9]&#x27;, &#x27;&#x27;, regex=True) # 验证发票号码长度（8位） df[&#x27;发票号码有效性&#x27;] = (df[&#x27;发票号码_清洗&#x27;].str.len() == 8) &amp; (df[&#x27;发票号码_清洗&#x27;] != &#x27;nan&#x27;) # 处理无效发票号码 df.loc[~df[&#x27;发票号码有效性&#x27;], &#x27;发票号码_清洗&#x27;] = &#x27;INVALID&#x27; # 2. 开票日期标准化 print(&quot;2. 开票日期标准化...&quot;) df[&#x27;开票日期_标准&#x27;] = pd.to_datetime(df[&#x27;开票日期&#x27;], errors=&#x27;coerce&#x27;) # 处理超出合理范围的日期 当前日期 = pd.Timestamp.now() 未来日期 = df[&#x27;开票日期_标准&#x27;] &gt; 当前日期 过早日期 = df[&#x27;开票日期_标准&#x27;] &lt; pd.Timestamp(&#x27;2020-01-01&#x27;) df.loc[未来日期, &#x27;日期异常标记&#x27;] = &#x27;未来日期&#x27; df.loc[过早日期, &#x27;日期异常标记&#x27;] = &#x27;过早日期&#x27; df.loc[df[&#x27;开票日期_标准&#x27;].isnull(), &#x27;日期异常标记&#x27;] = &#x27;无效日期&#x27; # 3. 购买方名称清洗 print(&quot;3. 购买方名称清洗...&quot;) df[&#x27;购买方名称_清洗&#x27;] = df[&#x27;购买方名称&#x27;].astype(str).str.strip() # 统一有限公司格式 df[&#x27;购买方名称_清洗&#x27;] = df[&#x27;购买方名称_清洗&#x27;].str.replace(&#x27;有限公司&#x27;, &#x27;有限公司&#x27;, regex=False) df[&#x27;购买方名称_清洗&#x27;] = df[&#x27;购买方名称_清洗&#x27;].str.replace(&#x27;有限责任&#x27;, &#x27;有限公司&#x27;, regex=False) # 4. 金额和税额清洗 print(&quot;4. 金额和税额清洗...&quot;) for 列名 in [&#x27;金额&#x27;, &#x27;税额&#x27;]: # 移除货币符号和千分位 df[f&#x27;&#123;列名&#125;_数值&#x27;] = df[列名].astype(str).str.replace(r&#x27;[,\元]&#x27;, &#x27;&#x27;, regex=True) # 转换为数值 df[f&#x27;&#123;列名&#125;_数值&#x27;] = pd.to_numeric(df[f&#x27;&#123;列名&#125;_数值&#x27;], errors=&#x27;coerce&#x27;) # 处理异常值 df[f&#x27;&#123;列名&#125;_数值&#x27;] = df[f&#x27;&#123;列名&#125;_数值&#x27;].fillna(0) # 5. 税率标准化 print(&quot;5. 税率标准化...&quot;) df[&#x27;税率_数值&#x27;] = df[&#x27;税率&#x27;].astype(str).str.replace(&#x27;%&#x27;, &#x27;&#x27;).str.strip() df[&#x27;税率_数值&#x27;] = pd.to_numeric(df[&#x27;税率_数值&#x27;], errors=&#x27;coerce&#x27;) # 标准化为百分比形式 df[&#x27;税率_标准&#x27;] = df[&#x27;税率_数值&#x27;] / 100 # 处理异常税率 异常税率 = (df[&#x27;税率_标准&#x27;] &lt; 0) | (df[&#x27;税率_标准&#x27;] &gt; 0.2) # 假设税率不超过20% df.loc[异常税率, &#x27;税率异常标记&#x27;] = &#x27;税率超出正常范围&#x27; df.loc[异常税率, &#x27;税率_标准&#x27;] = 0.13 # 默认13% # 6. 发票类型标准化 print(&quot;6. 发票类型标准化...&quot;) df[&#x27;发票类型_标准&#x27;] = df[&#x27;发票类型&#x27;].astype(str).str.strip() # 统一命名 类型映射 = &#123; &#x27;专用发票&#x27;: &#x27;增值税专用发票&#x27;, &#x27;普通发票&#x27;: &#x27;增值税普通发票&#x27;, &#x27;电子发票&#x27;: &#x27;增值税电子普通发票&#x27; &#125; for 原始, 标准 in 类型映射.items(): df[&#x27;发票类型_标准&#x27;] = df[&#x27;发票类型_标准&#x27;].str.replace(原始, 标准, regex=False) # 7. 发票状态标准化 print(&quot;7. 发票状态标准化...&quot;) df[&#x27;发票状态_标准&#x27;] = df[&#x27;发票状态&#x27;].astype(str).str.strip().str.title() # 统一状态名称 状态映射 = &#123; &#x27;正常&#x27;: &#x27;有效&#x27;, &#x27;作废&#x27;: &#x27;无效&#x27;, &#x27;冲红&#x27;: &#x27;已冲红&#x27; &#125; for 原始, 标准 in 状态映射.items(): df[&#x27;发票状态_标准&#x27;] = df[&#x27;发票状态_标准&#x27;].str.replace(原始, 标准, regex=False) # 8. 数据验证 print(&quot;8. 数据验证...&quot;) # 验证税额计算 df[&#x27;计算税额&#x27;] = df[&#x27;金额_数值&#x27;] * df[&#x27;税率_标准&#x27;] df[&#x27;税额差异&#x27;] = abs(df[&#x27;税额_数值&#x27;] - df[&#x27;计算税额&#x27;]) 税额不匹配 = df[&#x27;税额差异&#x27;] &gt; 0.01 # 差异超过1分钱 df.loc[税额不匹配, &#x27;税额验证标记&#x27;] = &#x27;税额计算不匹配&#x27; # 验证发票状态一致性 作废发票有金额 = (df[&#x27;发票状态_标准&#x27;] == &#x27;无效&#x27;) &amp; (df[&#x27;金额_数值&#x27;] &gt; 0) df.loc[作废发票有金额, &#x27;状态一致性标记&#x27;] = &#x27;作废发票不应有金额&#x27; print(&quot;✅ 发票数据清洗完成！&quot;) return df# 清洗发票数据发票_清洗结果 = 清洗发票数据(发票数据)print(&quot;
清洗结果摘要：&quot;)print(f&quot;有效发票号码：&#123;发票_清洗结果[&#x27;发票号码有效性&#x27;].sum()&#125;个&quot;)print(f&quot;有效日期：&#123;发票_清洗结果[&#x27;开票日期_标准&#x27;].notnull().sum()&#125;个&quot;)print(f&quot;税额验证通过：&#123;(~发票_清洗结果[&#x27;税额验证标记&#x27;].notnull()).sum()&#125;个&quot;)print(f&quot;状态一致：&#123;(~发票_清洗结果[&#x27;状态一致性标记&#x27;].notnull()).sum()&#125;个&quot;)# 显示异常数据print(&quot;
⚠️ 发现的数据异常：&quot;)异常列 = [col for col in 发票_清洗结果.columns if &#x27;异常&#x27; in col or &#x27;错误&#x27; in col or &#x27;无效&#x27; in col]for 异常列名 in 异常列: 异常数量 = 发票_清洗结果[异常列名].notnull().sum() if 异常数量 &gt; 0: print(f&quot; &#123;异常列名&#125;：&#123;异常数量&#125;个&quot;)
挑战2：银行流水智能分类
# 银行流水智能分类系统print(&quot;=== 银行流水智能分类系统 ===&quot;)# 创建银行流水数据银行流水 = pd.DataFrame(&#123; &#x27;交易日期&#x27;: [&#x27;2024-01-01&#x27;, &#x27;2024-01-02&#x27;, &#x27;2024-01-03&#x27;, &#x27;2024-01-04&#x27;, &#x27;2024-01-05&#x27;, &#x27;2024-01-06&#x27;, &#x27;2024-01-07&#x27;, &#x27;2024-01-08&#x27;], &#x27;摘要&#x27;: [&#x27;工资收入-张三&#x27;, &#x27;支付宝转账-花呗还款&#x27;, &#x27;微信支付-超市购物&#x27;, &#x27;跨行转账-客户A货款&#x27;, &#x27;ATM取款&#x27;, &#x27;信用卡还款&#x27;, &#x27;微信红包-新年红包&#x27;, &#x27;对公转账-供应商B货款&#x27;], &#x27;金额&#x27;: [15000.00, -2500.00, -156.50, 35000.00, -3000.00, -5800.00, 88.88, -45000.00], &#x27;对方账户&#x27;: [&#x27;工资专户&#x27;, &#x27;支付宝(中国)网络技术有限公司&#x27;, &#x27;财付通支付科技有限公司&#x27;, &#x27;张三&#x27;, &#x27;ATM机&#x27;, &#x27;中国工商银行信用卡中心&#x27;, &#x27;微信红包&#x27;, &#x27;ABC有限公司&#x27;], &#x27;交易类型&#x27;: [&#x27;转入&#x27;, &#x27;转出&#x27;, &#x27;转出&#x27;, &#x27;转入&#x27;, &#x27;转出&#x27;, &#x27;转出&#x27;, &#x27;转入&#x27;, &#x27;转出&#x27;]&#125;)def 智能流水分类(流水df): &quot;&quot;&quot;智能银行流水分类&quot;&quot;&quot; print(&quot;🤖 开始智能流水分类...&quot;) df = 流水df.copy() # 定义分类关键词 分类规则 = &#123; &#x27;工资收入&#x27;: &#123; &#x27;关键词&#x27;: [&#x27;工资&#x27;, &#x27;薪资&#x27;, &#x27;奖金&#x27;, &#x27;津贴&#x27;], &#x27;金额特征&#x27;: &#x27;&gt;0&#x27;, &#x27;优先级&#x27;: 1 &#125;, &#x27;投资理财&#x27;: &#123; &#x27;关键词&#x27;: [&#x27;理财&#x27;, &#x27;基金&#x27;, &#x27;股票&#x27;, &#x27;证券&#x27;, &#x27;投资&#x27;], &#x27;金额特征&#x27;: &#x27;任意&#x27;, &#x27;优先级&#x27;: 2 &#125;, &#x27;生活消费&#x27;: &#123; &#x27;关键词&#x27;: [&#x27;支付宝&#x27;, &#x27;微信&#x27;, &#x27;购物&#x27;, &#x27;餐饮&#x27;, &#x27;超市&#x27;], &#x27;金额特征&#x27;: &#x27;&lt;0&#x27;, &#x27;优先级&#x27;: 3 &#125;, &#x27;信用卡还款&#x27;: &#123; &#x27;关键词&#x27;: [&#x27;信用卡&#x27;, &#x27;还款&#x27;, &#x27;creditcard&#x27;], &#x27;金额特征&#x27;: &#x27;&lt;0&#x27;, &#x27;优先级&#x27;: 1 &#125;, &#x27;转账汇款&#x27;: &#123; &#x27;关键词&#x27;: [&#x27;转账&#x27;, &#x27;汇款&#x27;, &#x27;跨行&#x27;], &#x27;金额特征&#x27;: &#x27;任意&#x27;, &#x27;优先级&#x27;: 4 &#125;, &#x27;现金业务&#x27;: &#123; &#x27;关键词&#x27;: [&#x27;ATM&#x27;, &#x27;取款&#x27;, &#x27;存款&#x27;, &#x27;现金&#x27;], &#x27;金额特征&#x27;: &#x27;任意&#x27;, &#x27;优先级&#x27;: 5 &#125;, &#x27;其他收入&#x27;: &#123; &#x27;关键词&#x27;: [&#x27;红包&#x27;, &#x27;退款&#x27;, &#x27;返利&#x27;], &#x27;金额特征&#x27;: &#x27;&gt;0&#x27;, &#x27;优先级&#x27;: 6 &#125;, &#x27;其他支出&#x27;: &#123; &#x27;关键词&#x27;: [], &#x27;金额特征&#x27;: &#x27;&lt;0&#x27;, &#x27;优先级&#x27;: 7 &#125; &#125; # 创建分类列 df[&#x27;分类结果&#x27;] = &#x27;未分类&#x27; df[&#x27;分类置信度&#x27;] = 0.0 df[&#x27;分类依据&#x27;] = &#x27;&#x27; def 计算置信度(关键词匹配数, 总关键词数, 金额匹配, 规则优先级): &quot;&quot;&quot;计算分类置信度&quot;&quot;&quot; 关键词置信度 = 关键词匹配数 / max(总关键词数, 1) 金额置信度 = 1.0 if 金额匹配 else 0.5 优先级权重 = 1.0 / 规则优先级 return (关键词置信度 * 0.6 + 金额置信度 * 0.3 + 优先级权重 * 0.1) # 逐行分析 for 索引, 行 in df.iterrows(): 摘要 = str(行[&#x27;摘要&#x27;]).lower() 对方账户 = str(行[&#x27;对方账户&#x27;]).lower() 金额 = 行[&#x27;金额&#x27;] 交易类型 = 行[&#x27;交易类型&#x27;] 最佳分类 = None 最高置信度 = 0 # 检查每个分类规则 for 分类名, 规则 in 分类规则.items(): 关键词 = 规则[&#x27;关键词&#x27;] 金额特征 = 规则[&#x27;金额特征&#x27;] 优先级 = 规则[&#x27;优先级&#x27;] # 关键词匹配 关键词匹配数 = 0 匹配关键词 = [] for 关键词项 in 关键词: if 关键词项 in 摘要 or 关键词项 in 对方账户: 关键词匹配数 += 1 匹配关键词.append(关键词项) # 金额特征匹配 金额匹配 = False if 金额特征 == &#x27;任意&#x27;: 金额匹配 = True elif 金额特征 == &#x27;&gt;0&#x27; and 金额 &gt; 0: 金额匹配 = True elif 金额特征 == &#x27;&lt;0&#x27; and 金额 &lt; 0: 金额匹配 = True # 计算置信度 置信度 = 计算置信度(关键词匹配数, len(关键词), 金额匹配, 优先级) if 置信度 &gt; 最高置信度: 最高置信度 = 置信度 最佳分类 = 分类名 分类依据 = f&quot;关键词：&#123;匹配关键词&#125;，金额：&#123;金额&#125;，优先级：&#123;优先级&#125;&quot; # 记录最佳分类结果 if 最佳分类 and 最高置信度 &gt; 0.3: # 置信度阈值 df.loc[索引, &#x27;分类结果&#x27;] = 最佳分类 df.loc[索引, &#x27;分类置信度&#x27;] = 最高置信度 df.loc[索引, &#x27;分类依据&#x27;] = 分类依据 else: # 使用默认分类 if 金额 &gt; 0: df.loc[索引, &#x27;分类结果&#x27;] = &#x27;其他收入&#x27; df.loc[索引, &#x27;分类置信度&#x27;] = 0.3 else: df.loc[索引, &#x27;分类结果&#x27;] = &#x27;其他支出&#x27; df.loc[索引, &#x27;分类置信度&#x27;] = 0.3 # 高级分析 print(&quot;📊 执行高级分析...&quot;) # 计算各类别的统计信息 分类统计 = df.groupby(&#x27;分类结果&#x27;).agg(&#123; &#x27;金额&#x27;: [&#x27;count&#x27;, &#x27;sum&#x27;, &#x27;mean&#x27;], &#x27;分类置信度&#x27;: &#x27;mean&#x27; &#125;).round(2) 分类统计.columns = [&#x27;笔数&#x27;, &#x27;总金额&#x27;, &#x27;平均金额&#x27;, &#x27;平均置信度&#x27;] 分类统计 = 分类统计.sort_values(&#x27;总金额&#x27;, ascending=False) print(&quot;
分类统计结果：&quot;) print(分类统计) # 异常检测 print(&quot;
🔍 异常检测：&quot;) # 大额异常检测 大额阈值 = df[&#x27;金额&#x27;].abs().quantile(0.95) 大额交易 = df[df[&#x27;金额&#x27;].abs() &gt; 大额阈值] if len(大额交易) &gt; 0: print(f&quot;发现&#123;len(大额交易)&#125;笔大额交易（&gt;&#123;大额阈值:.2f&#125;元）：&quot;) for _, 交易 in 大额交易.iterrows(): print(f&quot; &#123;交易[&#x27;交易日期&#x27;]&#125;：&#123;交易[&#x27;分类结果&#x27;]&#125; - &#123;交易[&#x27;金额&#x27;]:,.2f&#125;元&quot;) # 低置信度检测 低置信度阈值 = 0.5 低置信度交易 = df[df[&#x27;分类置信度&#x27;] &lt; 低置信度阈值] if len(低置信度交易) &gt; 0: print(f&quot;
发现&#123;len(低置信度交易)&#125;笔低置信度分类：&quot;) for _, 交易 in 低置信度交易.iterrows(): print(f&quot; &#123;交易[&#x27;交易日期&#x27;]&#125;：&#123;交易[&#x27;分类结果&#x27;]&#125;（置信度：&#123;交易[&#x27;分类置信度&#x27;]:.2f&#125;）&quot;) print(&quot;✅ 智能分类完成！&quot;) return df# 执行智能分类流水_分类结果 = 智能流水分类(银行流水)# 生成分类报告print(f&quot;
📈 分类结果摘要：&quot;)分类汇总 = 流水_分类结果[&#x27;分类结果&#x27;].value_counts()for 分类, 数量 in 分类汇总.items(): 平均置信度 = 流水_分类结果[流水_分类结果[&#x27;分类结果&#x27;] == 分类][&#x27;分类置信度&#x27;].mean() print(f&quot; &#123;分类&#125;：&#123;数量&#125;笔（平均置信度：&#123;平均置信度:.2f&#125;）&quot;)# 可视化分类结果import matplotlib.pyplot as pltplt.figure(figsize=(12, 8))# 子图1：分类饼图plt.subplot(2, 2, 1)分类统计 = 流水_分类结果[&#x27;分类结果&#x27;].value_counts()plt.pie(分类统计.values, labels=分类统计.index, autopct=&#x27;%1.1f%%&#x27;, startangle=90)plt.title(&#x27;交易分类分布&#x27;)# 子图2：收入vs支出plt.subplot(2, 2, 2)收支对比 = 流水_分类结果.groupby([&#x27;分类结果&#x27;, 流水_分类结果[&#x27;金额&#x27;] &gt; 0])[&#x27;金额&#x27;].sum().unstack(fill_value=0)收支对比.plot(kind=&#x27;bar&#x27;, stacked=True)plt.title(&#x27;各类别收入vs支出&#x27;)plt.xlabel(&#x27;分类&#x27;)plt.ylabel(&#x27;金额&#x27;)plt.xticks(rotation=45)# 子图3：时间序列plt.subplot(2, 2, 3)日分类金额 = 流水_分类结果.groupby([&#x27;交易日期&#x27;, &#x27;分类结果&#x27;])[&#x27;金额&#x27;].sum().unstack(fill_value=0)日分类金额.plot(kind=&#x27;line&#x27;, marker=&#x27;o&#x27;)plt.title(&#x27;各类别金额时间序列&#x27;)plt.xlabel(&#x27;日期&#x27;)plt.ylabel(&#x27;金额&#x27;)plt.xticks(rotation=45)# 子图4：置信度分布plt.subplot(2, 2, 4)plt.hist(流水_分类结果[&#x27;分类置信度&#x27;], bins=10, edgecolor=&#x27;black&#x27;)plt.title(&#x27;分类置信度分布&#x27;)plt.xlabel(&#x27;置信度&#x27;)plt.ylabel(&#x27;频数&#x27;)plt.tight_layout()plt.savefig(&#x27;银行流水智能分类分析.png&#x27;, dpi=300, bbox_inches=&#x27;tight&#x27;)plt.close()print(&quot;✅ 可视化分析图表已生成！&quot;)
