今天我们要学的，就是用Python做这些“简单”的数据分析。 你会发现：
一行代码就能完成复杂的分组统计 自动处理几万行数据，再也不用手动拖拽
🎯 今日学习目标 掌握基础统计运算（求和、平均、最大最小值） 学会分组统计（比数据透视表更快） 实战月度支出分析（自动生成分析报告）
🧮 基础统计运算：数据分析的基石创建示例数据：月度支出表import pandas as pdimport numpy as np# 创建真实的月度支出数据np.random.seed(42) # 保证结果可重复# 生成3个月的支出数据日期范围 = pd.date_range(&#x27;2024-01-01&#x27;, &#x27;2024-03-31&#x27;, freq=&#x27;D&#x27;)支出类别 = [&#x27;餐饮&#x27;, &#x27;交通&#x27;, &#x27;购物&#x27;, &#x27;娱乐&#x27;, &#x27;住房&#x27;, &#x27;医疗&#x27;, &#x27;教育&#x27;, &#x27;其他&#x27;]支出方式 = [&#x27;现金&#x27;, &#x27;支付宝&#x27;, &#x27;微信&#x27;, &#x27;银行卡&#x27;]月度支出 = []for 日期 in 日期范围: # 每天1-3笔支出 日支出笔数 = np.random.randint(1, 4) for _ in range(日支出笔数): 类别 = np.random.choice(支出类别) 方式 = np.random.choice(支出方式) 金额 = np.random.randint(10, 501) # 10-500元随机支出 月度支出.append(&#123; &#x27;日期&#x27;: 日期, &#x27;类别&#x27;: 类别, &#x27;方式&#x27;: 方式, &#x27;金额&#x27;: 金额, &#x27;备注&#x27;: f&#x27;&#123;类别&#125;消费&#x27; &#125;)# 创建DataFramedf = pd.DataFrame(月度支出)df[&#x27;月份&#x27;] = df[&#x27;日期&#x27;].dt.monthdf[&#x27;星期&#x27;] = df[&#x27;日期&#x27;].dt.day_name()df[&#x27;是否周末&#x27;] = df[&#x27;日期&#x27;].dt.dayofweek &gt;= 5print(&quot;📊 月度支出数据预览：&quot;)print(df.head(10))print(f&quot;
数据形状：&#123;df.shape&#125;&quot;) 基础统计运算（比Excel函数更强大）print(&quot;=== 基础统计运算 ===&quot;)# 总支出总支出 = df[&#x27;金额&#x27;].sum()print(f&quot;💰 总支出：&#123;总支出:,&#125;元&quot;)# 平均支出平均支出 = df[&#x27;金额&#x27;].mean()print(f&quot;📊 平均支出：&#123;平均支出:.2f&#125;元/笔&quot;)# 最大/最小支出最大支出 = df[&#x27;金额&#x27;].max()最小支出 = df[&#x27;金额&#x27;].min()print(f&quot;🔝 最大支出：&#123;最大支出&#125;元&quot;)print(f&quot;🔻 最小支出：&#123;最小支出&#125;元&quot;)# 支出笔数总笔数 = df[&#x27;金额&#x27;].count()print(f&quot;📝 总支出笔数：&#123;总笔数&#125;笔&quot;)# 标准差（支出波动）支出标准差 = df[&#x27;金额&#x27;].std()print(f&quot;📈 支出标准差：&#123;支出标准差:.2f&#125;元&quot;)# 中位数（比平均数更稳定）支出中位数 = df[&#x27;金额&#x27;].median()print(f&quot;⚖️ 支出中位数：&#123;支出中位数&#125;元&quot;)# 分位数分析q25 = df[&#x27;金额&#x27;].quantile(0.25) # 25%分位q75 = df[&#x27;金额&#x27;].quantile(0.75) # 75%分位print(f&quot;📊 支出分位数：25%=&#123;q25&#125;元，75%=&#123;q75&#125;元&quot;)# 描述性统计（一键生成所有统计指标）print(&quot;
📋 描述性统计汇总：&quot;)print(df[&#x27;金额&#x27;].describe()) 按条件统计（比Excel筛选更智能）print(&quot;
=== 条件统计分析 ===&quot;)# 周末vs工作日支出对比周末支出 = df[df[&#x27;是否周末&#x27;]][&#x27;金额&#x27;].sum()工作日支出 = df[~df[&#x27;是否周末&#x27;]][&#x27;金额&#x27;].sum()print(f&quot;周末支出：&#123;周末支出:,&#125;元&quot;)print(f&quot;工作日支出：&#123;工作日支出:,&#125;元&quot;)print(f&quot;周末日均：&#123;周末支出 / df[df[&#x27;是否周末&#x27;]][&#x27;金额&#x27;].count():.2f&#125;元/天&quot;)print(f&quot;工作日日均：&#123;工作日支出 / df[~df[&#x27;是否周末&#x27;]][&#x27;金额&#x27;].count():.2f&#125;元/天&quot;)# 大额支出分析（&gt;200元）大额支出 = df[df[&#x27;金额&#x27;] &gt; 200]大额支出统计 = &#123; &#x27;总笔数&#x27;: len(大额支出), &#x27;总金额&#x27;: 大额支出[&#x27;金额&#x27;].sum(), &#x27;平均金额&#x27;: 大额支出[&#x27;金额&#x27;].mean(), &#x27;最大金额&#x27;: 大额支出[&#x27;金额&#x27;].max()&#125;print(f&quot;
💰 大额支出（&gt;200元）统计：&quot;)for 指标, 数值 in 大额支出统计.items(): print(f&quot; &#123;指标&#125;：&#123;数值&#125;&quot;)# 小额支出分析（&lt;50元）小额支出 = df[df[&#x27;金额&#x27;] &lt; 50]小额支出统计 = &#123; &#x27;总笔数&#x27;: len(小额支出), &#x27;总金额&#x27;: 小额支出[&#x27;金额&#x27;].sum(), &#x27;平均金额&#x27;: 小额支出[&#x27;金额&#x27;].mean(), &#x27;占比&#x27;: 小额支出[&#x27;金额&#x27;].sum() / df[&#x27;金额&#x27;].sum() * 100&#125;print(f&quot;
🪙 小额支出（&lt;50元）统计：&quot;)for 指标, 数值 in 小额支出统计.items(): if 指标 == &#x27;占比&#x27;: print(f&quot; &#123;指标&#125;：&#123;数值:.1f&#125;%&quot;) else: print(f&quot; &#123;指标&#125;：&#123;数值&#125;&quot;)# 特定日期范围分析（春节期间）春节开始 = pd.Timestamp(&#x27;2024-02-08&#x27;)春节结束 = pd.Timestamp(&#x27;2024-02-18&#x27;)春节支出 = df[(df[&#x27;日期&#x27;] &gt;= 春节开始) &amp; (df[&#x27;日期&#x27;] &lt;= 春节结束)]print(f&quot;
🧧 春节期间支出：&#123;春节支出[&#x27;金额&#x27;].sum():,&#125;元（&#123;len(春节支出)&#125;笔）&quot;)
📊 分组统计：超级数据透视表基础分组统计（一行代码搞定）print(&quot;
=== 分组统计分析 ===&quot;)# 按类别统计支出类别统计 = df.groupby(&#x27;类别&#x27;)[&#x27;金额&#x27;].agg([&#x27;count&#x27;, &#x27;sum&#x27;, &#x27;mean&#x27;, &#x27;max&#x27;]).round(2)类别统计.columns = [&#x27;支出笔数&#x27;, &#x27;总支出&#x27;, &#x27;平均支出&#x27;, &#x27;最大支出&#x27;]类别统计 = 类别统计.sort_values(&#x27;总支出&#x27;, ascending=False)print(&quot;📊 按支出类别统计：&quot;)print(类别统计)# 按支付方式统计方式统计 = df.groupby(&#x27;方式&#x27;)[&#x27;金额&#x27;].agg([&#x27;count&#x27;, &#x27;sum&#x27;, &#x27;mean&#x27;]).round(2)方式统计.columns = [&#x27;使用次数&#x27;, &#x27;总支出&#x27;, &#x27;平均支出&#x27;]方式统计 = 方式统计.sort_values(&#x27;总支出&#x27;, ascending=False)print(&quot;
💳 按支付方式统计：&quot;)print(方式统计)# 按月份统计月度统计 = df.groupby(&#x27;月份&#x27;)[&#x27;金额&#x27;].agg([&#x27;count&#x27;, &#x27;sum&#x27;, &#x27;mean&#x27;]).round(2)月度统计.columns = [&#x27;支出笔数&#x27;, &#x27;月度总支出&#x27;, &#x27;平均单笔支出&#x27;]月度统计.index = [f&quot;&#123;月&#125;月&quot; for 月 in 月度统计.index]print(&quot;
📅 按月份统计：&quot;)print(月度统计) 多维度分组（Excel需要多次操作）# 多维度分组统计print(&quot;
=== 多维度分组分析 ===&quot;)# 类别+支付方式交叉统计交叉统计 = df.groupby([&#x27;类别&#x27;, &#x27;方式&#x27;])[&#x27;金额&#x27;].agg([&#x27;count&#x27;, &#x27;sum&#x27;]).round(2)交叉统计.columns = [&#x27;笔数&#x27;, &#x27;金额&#x27;]print(&quot;📊 类别×支付方式交叉统计：&quot;)print(交叉统计)# 重置索引让结果更美观交叉统计_重置 = df.groupby([&#x27;类别&#x27;, &#x27;方式&#x27;]).agg(&#123; &#x27;金额&#x27;: [&#x27;count&#x27;, &#x27;sum&#x27;, &#x27;mean&#x27;], &#x27;日期&#x27;: &#x27;count&#x27;&#125;).round(2)交叉统计_重置.columns = [&#x27;支出笔数&#x27;, &#x27;总支出&#x27;, &#x27;平均支出&#x27;, &#x27;天数&#x27;]print(&quot;
📋 类别×支付方式详细统计：&quot;)print(交叉统计_重置)# 按星期和类别统计星期类别 = df.groupby([&#x27;星期&#x27;, &#x27;类别&#x27;])[&#x27;金额&#x27;].sum().unstack(fill_value=0)print(&quot;
📅 星期×类别支出矩阵：&quot;)print(星期类别)# 计算每个类别的支出占比类别占比 = df.groupby(&#x27;类别&#x27;)[&#x27;金额&#x27;].sum() / df[&#x27;金额&#x27;].sum() * 100类别占比 = 类别占比.round(1)print(&quot;
📈 各类别支出占比：&quot;)for 类别, 占比 in 类别占比.items(): print(f&quot; &#123;类别&#125;：&#123;占比&#125;%&quot;) 高级分组函数（财务专用）# 财务专用分组统计print(&quot;
=== 财务专用分析 ===&quot;)# 累计支出（类似Excel的累计求和）日累计支出 = df.groupby(&#x27;日期&#x27;)[&#x27;金额&#x27;].sum().cumsum()print(f&quot;
📈 累计支出（月末）：&#123;日累计支出.iloc[-1]:,&#125;元&quot;)# 滚动平均（7天移动平均）df_sorted = df.sort_values(&#x27;日期&#x27;)日支出 = df_sorted.groupby(&#x27;日期&#x27;)[&#x27;金额&#x27;].sum()滚动平均 = 日支出.rolling(window=7, min_periods=1).mean()print(f&quot;
📊 7天移动平均支出（最新）：&#123;滚动平均.iloc[-1]:.2f&#125;元&quot;)# 同比环比分析（需要多月份数据）# 这里模拟计算日均支出的环比变化一月数据 = df[df[&#x27;月份&#x27;] == 1]二月数据 = df[df[&#x27;月份&#x27;] == 2]三月数据 = df[df[&#x27;月份&#x27;] == 3]一月日均 = 一月数据.groupby(&#x27;日期&#x27;)[&#x27;金额&#x27;].sum().mean()二月日均 = 二月数据.groupby(&#x27;日期&#x27;)[&#x27;金额&#x27;].sum().mean()三月日均 = 三月_data.groupby(&#x27;日期&#x27;)[&#x27;金额&#x27;].sum().mean()print(f&quot;
📊 各月日均支出：&quot;)print(f&quot; 1月：&#123;一月日均:.2f&#125;元/天&quot;)print(f&quot; 2月：&#123;二月日均:.2f&#125;元/天&quot;)print(f&quot; 3月：&#123;三月日均:.2f&#125;元/天&quot;)# 计算环比变化if 二月日均 &gt; 0: 二月环比 = (二月日均 - 一月日均) / 一月日均 * 100 print(f&quot; 2月环比：&#123;二月环比:+.1f&#125;%&quot;)if 三月日均 &gt; 0: 三月环比 = (三月日均 - 二月日均) / 二月日均 * 100 print(f&quot; 3月环比：&#123;三月环比:+.1f&#125;%&quot;)
🎯 实战项目：月度支出分析 版本1.0：基础支出分析
# 月度支出分析 - 基础版print(&quot;=== 月度支出分析报告 ===&quot;)def 基础支出分析(df): &quot;&quot;&quot;基础支出分析&quot;&quot;&quot; print(&quot;📊 生成基础支出分析...&quot;) # 1. 总体支出分析 总分析 = &#123; &#x27;总支出&#x27;: df[&#x27;金额&#x27;].sum(), &#x27;平均支出&#x27;: df[&#x27;金额&#x27;].mean(), &#x27;支出笔数&#x27;: len(df), &#x27;日均支出&#x27;: df.groupby(&#x27;日期&#x27;)[&#x27;金额&#x27;].sum().mean(), &#x27;最大单笔&#x27;: df[&#x27;金额&#x27;].max(), &#x27;最小单笔&#x27;: df[&#x27;金额&#x27;].min() &#125; print(&quot;
📈 总体支出情况：&quot;) for 指标, 数值 in 总分析.items(): if &#x27;金额&#x27; in 指标: print(f&quot; &#123;指标&#125;：&#123;数值:,.2f&#125;元&quot;) else: print(f&quot; &#123;指标&#125;：&#123;数值&#125;&quot;) # 2. 分类支出分析 分类分析 = df.groupby(&#x27;类别&#x27;).agg(&#123; &#x27;金额&#x27;: [&#x27;sum&#x27;, &#x27;mean&#x27;, &#x27;count&#x27;], &#x27;日期&#x27;: &#x27;nunique&#x27; &#125;).round(2) 分类分析.columns = [&#x27;总支出&#x27;, &#x27;平均支出&#x27;, &#x27;支出笔数&#x27;, &#x27;支出天数&#x27;] 分类分析 = 分类分析.sort_values(&#x27;总支出&#x27;, ascending=False) print(&quot;
📊 分类支出排名：&quot;) for 类别, 数据 in 分类分析.iterrows(): print(f&quot; &#123;类别&#125;：&#123;数据[&#x27;总支出&#x27;]:,.2f&#125;元（&#123;数据[&#x27;支出笔数&#x27;]&#125;笔）&quot;) # 3. 支付方式分析 方式分析 = df.groupby(&#x27;方式&#x27;).agg(&#123; &#x27;金额&#x27;: [&#x27;sum&#x27;, &#x27;count&#x27;], &#x27;日期&#x27;: &#x27;nunique&#x27; &#125;).round(2) 方式分析.columns = [&#x27;总支出&#x27;, &#x27;使用次数&#x27;, &#x27;使用天数&#x27;] print(&quot;
💳 支付方式分析：&quot;) for 方式, 数据 in 方式分析.iterrows(): print(f&quot; &#123;方式&#125;：&#123;数据[&#x27;总支出&#x27;]:,.2f&#125;元（&#123;数据[&#x27;使用次数&#x27;]&#125;次）&quot;) # 4. 时间趋势分析 日支出 = df.groupby(&#x27;日期&#x27;)[&#x27;金额&#x27;].sum() print(&quot;
