# 月度支出分析 - 高级版print(&quot;
=== 高级支出分析 ===&quot;)def 高级支出分析(df): &quot;&quot;&quot;高级支出分析&quot;&quot;&quot; print(&quot;🔍 执行高级分析...&quot;) # 1. 时间序列分析 print(&quot;
📈 时间序列分析：&quot;) # 日支出趋势 日支出 = df.groupby(&#x27;日期&#x27;)[&#x27;金额&#x27;].sum().sort_index() # 计算趋势指标 支出增长 = 日支出.pct_change().mean() * 100 支出波动 = 日支出.std() 支出趋势 = &quot;上升&quot; if 支出增长 &gt; 0 else &quot;下降&quot; print(f&quot; 支出趋势：&#123;支出趋势&#125;（日均增长率：&#123;支出增长:.2f&#125;%）&quot;) print(f&quot; 支出波动：&#123;支出波动:.2f&#125;元（标准差）&quot;) # 找支出高峰和低谷 高峰日期 = 日支出.idxmax() 低谷日期 = 日支出.idxmin() print(f&quot; 支出高峰：&#123;日支出.max():,.2f&#125;元（&#123;高峰日期.strftime(&#x27;%m月%d日&#x27;)&#125;）&quot;) print(f&quot; 支出低谷：&#123;日支出.min():,.2f&#125;元（&#123;低谷日期.strftime(&#x27;%m月%d日&#x27;)&#125;）&quot;) # 2. 异常检测 print(&quot;
⚠️ 异常支出检测：&quot;) # 使用IQR方法检测异常值 Q1 = df[&#x27;金额&#x27;].quantile(0.25) Q3 = df[&#x27;金额&#x27;].quantile(0.75) IQR = Q3 - Q1 下限 = Q1 - 1.5 * IQR 上限 = Q3 + 1.5 * IQR 异常支出 = df[(df[&#x27;金额&#x27;] &lt; 下限) | (df[&#x27;金额&#x27;] &gt; 上限)] print(f&quot; 发现异常支出：&#123;len(异常支出)&#125;笔&quot;) if len(异常支出) &gt; 0: print(f&quot; 异常支出金额范围：&#123;异常支出[&#x27;金额&#x27;].min():.2f&#125; - &#123;异常支出[&#x27;金额&#x27;].max():.2f&#125;元&quot;) print(f&quot; 异常支出占比：&#123;异常支出[&#x27;金额&#x27;].sum() / df[&#x27;金额&#x27;].sum() * 100:.1f&#125;%&quot;) # 分析异常支出的类别分布 异常类别分布 = 异常支出[&#x27;类别&#x27;].value_counts() print(f&quot; 异常支出主要类别：&#123;异常类别分布.index[0]&#125;（&#123;异常类别分布.iloc[0]&#125;笔）&quot;) # 3. 消费行为分析 print(&quot;
💡 消费行为分析：&quot;) # 消费频次分析 日消费频次 = df.groupby(&#x27;日期&#x27;).size() 平均日消费次数 = 日消费频次.mean() 最高日消费次数 = 日消费频次.max() print(f&quot; 平均日消费次数：&#123;平均日消费次数:.1f&#125;次&quot;) print(f&quot; 最高日消费次数：&#123;最高日消费次数&#125;次&quot;) # 消费集中度分析 前20%支出 = df.nlargest(int(len(df) * 0.2), &#x27;金额&#x27;)[&#x27;金额&#x27;].sum() 集中度 = 前20%支出 / df[&#x27;金额&#x27;].sum() * 100 print(f&quot; 前20%支出占总支出：&#123;集中度:.1f&#125;%（帕累托法则）&quot;) if 集中度 &gt; 80: print(&quot; 💡 消费高度集中，建议关注大额支出&quot;) elif 集中度 &lt; 60: print(&quot; 💡 消费较为分散，支出管理良好&quot;) # 4. 预测分析（简化版） print(&quot;
🔮 简单预测分析：&quot;) # 基于历史数据预测下月支出 月度平均 = df.groupby(&#x27;月份&#x27;)[&#x27;金额&#x27;].sum().mean() 最近一月 = df[df[&#x27;月份&#x27;] == df[&#x27;月份&#x27;].max()][&#x27;金额&#x27;].sum() 趋势因子 = 最近一月 / 月度平均 预测下月支出 = 月度平均 * 趋势因子 print(f&quot; 预测下月支出：&#123;预测下月支出:,.2f&#125;元&quot;) print(f&quot; （基于趋势因子：&#123;趋势因子:.2f&#125;）&quot;) # 5. 健康度评估 print(&quot;
💚 消费健康度评估：&quot;) # 计算各项健康指标 健康指标 = &#123; &#x27;支出稳定性&#x27;: (1 - 日支出.std() / 日支出.mean()) * 100, &#x27;预算遵守度&#x27;: min(100, 100 - abs(日支出.mean() - 200) / 200 * 100), # 假设预算200元/天 &#x27;消费多样性&#x27;: len(df[&#x27;类别&#x27;].unique()) / len(支出类别) * 100, &#x27;理性消费率&#x27;: (1 - len(df[df[&#x27;金额&#x27;] &gt; 300]) / len(df)) * 100 # 假设300元以上为大额 &#125; 总体健康度 = sum(健康指标.values()) / len(健康指标) print(f&quot; 总体健康度：&#123;总体健康度:.1f&#125;分&quot;) for 指标, 分值 in 健康指标.items(): print(f&quot; &#123;指标&#125;：&#123;分值:.1f&#125;分&quot;) if 总体健康度 &gt;= 80: print(&quot; 🎉 消费健康状况优秀！&quot;) elif 总体健康度 &gt;= 60: print(&quot; 👍 消费健康状况良好&quot;) else: print(&quot; ⚠️ 消费健康状况需要改善&quot;) return &#123; &#x27;日支出&#x27;: 日支出, &#x27;异常支出&#x27;: 异常支出, &#x27;健康指标&#x27;: 健康指标, &#x27;总体健康度&#x27;: 总体健康度 &#125;# 执行高级分析高级结果 = 高级支出分析(df)
版本3.0：专业分析报告
# 专业支出分析报告print(&quot;
=== 专业支出分析报告 ===&quot;)from openpyxl import Workbookfrom openpyxl.styles import Font, PatternFill, Alignmentfrom openpyxl.chart import LineChart, BarChart, PieChart, Referenceimport matplotlib.pyplot as pltdef 生成专业支出报告(df, 文件名=&quot;月度支出分析报告.xlsx&quot;): &quot;&quot;&quot;生成专业的支出分析报告&quot;&quot;&quot; print(&quot;📊 生成专业报告...&quot;) # 创建工作簿 wb = Workbook() # 1. 执行汇总表 汇总表 = wb.active 汇总表.title = &quot;执行汇总&quot; # 标题 汇总表[&quot;A1&quot;] = &quot;月度支出分析报告&quot; 汇总表[&quot;A1&quot;].font = Font(size=18, bold=True, color=&quot;FFFFFF&quot;) 汇总表[&quot;A1&quot;].fill = PatternFill(start_color=&quot;366092&quot;, end_color=&quot;366092&quot;, fill_type=&quot;solid&quot;) 汇总表.merge_cells(&quot;A1:H1&quot;) 汇总表[&quot;A1&quot;].alignment = Alignment(horizontal=&quot;center&quot;) # 基本信息 分析期间 = f&quot;&#123;df[&#x27;日期&#x27;].min().strftime(&#x27;%Y年%m月%d日&#x27;)&#125; - &#123;df[&#x27;日期&#x27;].max().strftime(&#x27;%Y年%m月%d日&#x27;)&#125;&quot; 汇总表[&quot;A3&quot;] = f&quot;分析期间：&#123;分析期间&#125;&quot; 汇总表[&quot;A4&quot;] = f&quot;数据记录数：&#123;len(df)&#125;笔&quot; 汇总表[&quot;A5&quot;] = f&quot;报告生成时间：&#123;pd.Timestamp.now().strftime(&#x27;%Y年%m月%d日 %H:%M&#x27;)&#125;&quot; # 关键指标 关键指标 = [ [&quot;关键指标&quot;, &quot;数值&quot;, &quot;单位&quot;, &quot;环比变化&quot;, &quot;健康状况&quot;], [&quot;总支出&quot;, f&quot;&#123;df[&#x27;金额&#x27;].sum():,.2f&#125;&quot;, &quot;元&quot;, &quot;-&quot;, &quot;待评估&quot;], [&quot;平均单笔支出&quot;, f&quot;&#123;df[&#x27;金额&#x27;].mean():.2f&#125;&quot;, &quot;元/笔&quot;, &quot;-&quot;, &quot;待评估&quot;], [&quot;日均支出&quot;, f&quot;&#123;df.groupby(&#x27;日期&#x27;)[&#x27;金额&#x27;].sum().mean():.2f&#125;&quot;, &quot;元/天&quot;, &quot;-&quot;, &quot;待评估&quot;], [&quot;支出笔数&quot;, f&quot;&#123;len(df):,&#125;&quot;, &quot;笔&quot;, &quot;-&quot;, &quot;待评估&quot;], [&quot;支出类别数&quot;, f&quot;&#123;df[&#x27;类别&#x27;].nunique()&#125;&quot;, &quot;类&quot;, &quot;-&quot;, &quot;待评估&quot;], [&quot;支出方式数&quot;, f&quot;&#123;df[&#x27;方式&#x27;].nunique()&#125;&quot;, &quot;种&quot;, &quot;-&quot;, &quot;待评估&quot;] ] 起始行 = 7 for 行号, 数据行 in enumerate(关键指标, 起始行): for 列号, 值 in enumerate(数据行, 1): 单元格 = 汇总表.cell(row=行号, column=列号, value=值) if 行号 == 起始行: 单元格.font = Font(bold=True) 单元格.fill = PatternFill(start_color=&quot;D9E2F3&quot;, end_color=&quot;D9E2F3&quot;, fill_type=&quot;solid&quot;) # 2. 分类支出表 分类表 = wb.create_sheet(&quot;分类支出分析&quot;) 分类表[&quot;A1&quot;] = &quot;分类支出分析&quot; 分类表[&quot;A1&quot;].font = Font(size=14, bold=True) # 分类统计数据 分类统计 = df.groupby(&#x27;类别&#x27;).agg(&#123; &#x27;金额&#x27;: [&#x27;count&#x27;, &#x27;sum&#x27;, &#x27;mean&#x27;, &#x27;max&#x27;], &#x27;日期&#x27;: &#x27;nunique&#x27; &#125;).round(2) 分类统计.columns = [&#x27;支出笔数&#x27;, &#x27;总支出&#x27;, &#x27;平均支出&#x27;, &#x27;最大支出&#x27;, &#x27;支出天数&#x27;] 分类统计 = 分类统计.sort_values(&#x27;总支出&#x27;, ascending=False) 分类统计[&#x27;占比&#x27;] = (分类统计[&#x27;总支出&#x27;] / 分类统计[&#x27;总支出&#x27;].sum() * 100).round(1) # 写入表头 表头 = [&#x27;类别&#x27;, &#x27;支出笔数&#x27;, &#x27;总支出&#x27;, &#x27;平均支出&#x27;, &#x27;最大支出&#x27;, &#x27;占比&#x27;, &#x27;支出天数&#x27;] for 列号, 标题 in enumerate(表头, 1): 单元格 = 分类表.cell(row=3, column=列号, value=标题) 单元格.font = Font(bold=True) 单元格.fill = PatternFill(start_color=&quot;E8F4FD&quot;, end_color=&quot;E8F4FD&quot;, fill_type=&quot;solid&quot;) # 写入数据 for 行号, (类别, 数据) in enumerate(分类统计.iterrows(), 4): 分类表.cell(row=行号, column=1, value=类别) 分类表.cell(row=行号, column=2, value=数据[&#x27;支出笔数&#x27;]) 分类表.cell(row=行号, column=3, value=数据[&#x27;总支出&#x27;]) 分类表.cell(row=行号, column=4, value=数据[&#x27;平均支出&#x27;]) 分类表.cell(row=行号, column=5, value=数据[&#x27;最大支出&#x27;]) 分类表.cell(row=行号, column=6, value=f&quot;&#123;数据[&#x27;占比&#x27;]&#125;%&quot;) 分类表.cell(row=行号, column=7, value=数据[&#x27;支出天数&#x27;]) # 添加图表数据 图表数据行 = len(分类统计) + 6 分类表.cell(row=图表数据行, column=1, value=&quot;图表数据&quot;) 分类表.cell(row=图表数据行, column=1).font = Font(bold=True) for i, (类别, 数据) in enumerate(分类统计.iterrows(), 图表数据行 + 1): 分类表.cell(row=i, column=1, value=类别) 分类表.cell(row=i, column=2, value=数据[&#x27;总支出&#x27;]) # 创建饼图 饼图 = PieChart() 饼图.title = &quot;支出分类占比&quot; 数据 = Reference(分类表, min_col=2, min_row=图表数据行 + 1, max_row=图表数据行 + len(分类统计)) 分类 = Reference(分类表, min_col=1, min_row=图表数据行 + 1, max_row=图表数据行 + len(分类统计)) 饼图.add_data(data) 饼图.set_categories(分类) 分类表.add_chart(饼图, &quot;I3&quot;) # 3. 时间趋势表 时间表 = wb.create_sheet(&quot;时间趋势分析&quot;) 时间表[&quot;A1&quot;] = &quot;支出时间趋势分析&quot; 时间表[&quot;A1&quot;].font = Font(size=14, bold=True) # 日支出数据 日支出 = df.groupby(&#x27;日期&#x27;)[&#x27;金额&#x27;].sum().sort_index() 时间表[&quot;A3&quot;] = &quot;日支出明细&quot; 时间表[&quot;A3&quot;].font = Font(bold=True) # 写入日支出数据 表头 = [&#x27;日期&#x27;, &#x27;支出金额&#x27;, &#x27;星期&#x27;, &#x27;是否周末&#x27;] for 列号, 标题 in enumerate(表头, 1): 单元格 = 时间表.cell(row=5, column=列号, value=标题) 单元格.font = Font(bold=True) for 行号, (日期, 金额) in enumerate(日支出.items(), 6): 该日数据 = df[df[&#x27;日期&#x27;] == 日期].iloc[0] 时间表.cell(row=行号, column=1, value=日期.strftime(&#x27;%m-%d&#x27;)) 时间表.cell(row=行号, column=2, value=金额) 时间表.cell(row=行号, column=3, value=该日数据[&#x27;星期&#x27;]) 时间表.cell(row=行号, column=4, value=&#x27;是&#x27; if 该日数据[&#x27;是否周末&#x27;] else &#x27;否&#x27;) # 创建折线图 折线图 = LineChart() 折线图.title = &quot;日支出趋势&quot; 折线图.style = 2 折线图.y_axis.title = &#x27;支出金额（元）&#x27; 折线图.x_axis.title = &#x27;日期&#x27; 数据 = Reference(时间表, min_col=2, min_row=6, max_row=6 + len(日支出)) 分类 = Reference(时间表, min_col=1, min_row=6, max_row=6 + len(日支出)) 折线图.add_data(data) 折线图.set_categories(分类) 时间表.add_chart(折线图, &quot;F5&quot;) # 4. 健康度评估表 健康表 = wb.create_sheet(&quot;消费健康度评估&quot;) 健康表[&quot;A1&quot;] = &quot;消费健康度评估&quot; 健康表[&quot;A1&quot;].font = Font(size=14, bold=True) # 计算健康指标 日消费频次 = df.groupby(&#x27;日期&#x27;).size() 支出集中度 = df.nlargest(int(len(df) * 0.2), &#x27;金额&#x27;)[&#x27;金额&#x27;].sum() / df[&#x27;金额&#x27;].sum() * 100 类别多样性 = len(df[&#x27;类别&#x27;].unique()) / 8 * 100 # 假设有8个标准类别 理性消费率 = (1 - len(df[df[&#x27;金额&#x27;] &gt; 300]) / len(df)) * 100 健康指标 = &#123; &#x27;支出稳定性&#x27;: max(0, 100 - (日消费频次.std() / 日消费频次.mean() * 100)), &#x27;消费多样性&#x27;: min(100, 类别多样性), &#x27;理性消费率&#x27;: 理性消费率, &#x27;支出分散度&#x27;: max(0, 100 - 支出集中度) &#125; 总体健康度 = sum(健康指标.values()) / len(健康指标) # 写入健康指标 健康表[&quot;A3&quot;] = &quot;健康指标&quot; 健康表[&quot;A3&quot;].font = Font(bold=True) 健康数据 = [ [&quot;健康指标&quot;, &quot;得分&quot;, &quot;等级&quot;, &quot;建议&quot;], [&quot;支出稳定性&quot;, f&quot;&#123;健康指标[&#x27;支出稳定性&#x27;]:.1f&#125;&quot;, &quot;良好&quot; if 健康指标[&#x27;支出稳定性&#x27;] &gt;= 80 else &quot;需改善&quot;, &quot;保持规律消费习惯&quot;], [&quot;消费多样性&quot;, f&quot;&#123;健康指标[&#x27;消费多样性&#x27;]:.1f&#125;&quot;, &quot;优秀&quot; if 健康指标[&#x27;消费多样性&#x27;] &gt;= 90 else &quot;良好&quot;, &quot;适当增加消费类别&quot;], [&quot;理性消费率&quot;, f&quot;&#123;健康指标[&#x27;理性消费率&#x27;]:.1f&#125;&quot;, &quot;优秀&quot; if 健康指标[&#x27;理性消费率&#x27;] &gt;= 90 else &quot;良好&quot;, &quot;控制大额支出&quot;], [&quot;支出分散度&quot;, f&quot;&#123;健康指标[&#x27;支出分散度&#x27;]:.1f&#125;&quot;, &quot;良好&quot; if 健康指标[&#x27;支出分散度&#x27;] &gt;= 70 else &quot;需改善&quot;, &quot;避免过度集中消费&quot;] ] for 行号, 数据行 in enumerate(健康数据, 5): for 列号, 值 in enumerate(数据行, 1): 单元格 = 健康表.cell(row=行号, column=列号, value=值) if 行号 == 5: 单元格.font = Font(bold=True) 单元格.fill = PatternFill(start_color=&quot;E8F4FD&quot;, end_color=&quot;E8F4FD&quot;, fill_type=&quot;solid&quot;) # 总体评分 健康表.cell(row=11, column=1, value=&quot;总体健康度&quot;) 健康表.cell(row=11, column=1).font = Font(bold=True) 健康表.cell(row=12, column=1, value=f&quot;&#123;总体健康度:.1f&#125;分&quot;) 健康表.cell(row=12, column=2, value=&quot;优秀&quot; if 总体健康度 &gt;= 85 else &quot;良好&quot; if 总体健康度 &gt;= 70 else &quot;需改善&quot;) # 调整列宽 for 列 in [&quot;A&quot;, &quot;B&quot;, &quot;C&quot;, &quot;D&quot;]: 健康表.column_dimensions[列].width = 20 # 保存文件 wb.save(文件名) print(f&quot;✅ 专业支出报告已生成：&#123;文件名&#125;&quot;) return 文件名# 生成专业报告专业报告文件 = 生成专业支出报告(df)# 额外：生成数据可视化print(&quot;
📊 生成数据可视化图表...&quot;)plt.rcParams[&#x27;font.sans-serif&#x27;] = [&#x27;SimHei&#x27;] # 设置中文字体plt.rcParams[&#x27;axes.unicode_minus&#x27;] = False # 正确显示负号# 1. 支出分类饼图plt.figure(figsize=(10, 8))分类统计 = df.groupby(&#x27;类别&#x27;)[&#x27;金额&#x27;].sum().sort_values(ascending=False)plt.pie(分类统计.values, labels=分类统计.index, autopct=&#x27;%1.1f%%&#x27;, startangle=90)plt.title(&#x27;月度支出分类分布&#x27;, fontsize=16)plt.axis(&#x27;equal&#x27;)plt.savefig(&#x27;支出分类分布.png&#x27;, dpi=300, bbox_inches=&#x27;tight&#x27;)plt.close()# 2. 日支出趋势图plt.figure(figsize=(14, 6))日支出 = df.groupby(&#x27;日期&#x27;)[&#x27;金额&#x27;].sum()plt.plot(日支出.index, 日支出.values, marker=&#x27;o&#x27;, linewidth=2, markersize=4)plt.title(&#x27;日支出趋势图&#x27;, fontsize=16)plt.xlabel(&#x27;日期&#x27;, fontsize=12)plt.ylabel(&#x27;支出金额（元）&#x27;, fontsize=12)plt.grid(True, alpha=0.3)plt.xticks(rotation=45)plt.tight_layout()plt.savefig(&#x27;日支出趋势.png&#x27;, dpi=300, bbox_inches=&#x27;tight&#x27;)plt.close()# 3. 类别对比柱状图plt.figure(figsize=(12, 6))分类数据 = df.groupby(&#x27;类别&#x27;).agg(&#123; &#x27;金额&#x27;: &#x27;sum&#x27;, &#x27;日期&#x27;: &#x27;count&#x27;&#125;)分类数据.columns = [&#x27;总支出&#x27;, &#x27;支出笔数&#x27;]# 创建双轴图fig, ax1 = plt.subplots(figsize=(12, 6))ax2 = ax1.twinx()# 绘制总支出bars = ax1.bar(分类数据.index, 分类数据[&#x27;总支出&#x27;], color=&#x27;skyblue&#x27;, alpha=0.7, label=&#x27;总支出&#x27;)ax1.set_xlabel(&#x27;支出类别&#x27;, fontsize=12)ax1.set_ylabel(&#x27;总支出（元）&#x27;, fontsize=12, color=&#x27;blue&#x27;)ax1.tick_params(axis=&#x27;y&#x27;, labelcolor=&#x27;blue&#x27;)# 绘制支出笔数line = ax2.plot(分类数据.index, 分类_data[&#x27;支出笔数&#x27;], color=&#x27;red&#x27;, marker=&#x27;o&#x27;, linewidth=2, label=&#x27;支出笔数&#x27;)ax2.set_ylabel(&#x27;支出笔数&#x27;, fontsize=12, color=&#x27;red&#x27;)ax2.tick_params(axis=&#x27;y&#x27;, labelcolor=&#x27;red&#x27;)plt.title(&#x27;各类别支出对比&#x27;, fontsize=16)plt.xticks(rotation=45)plt.tight_layout()plt.savefig(&#x27;类别支出对比.png&#x27;, dpi=300, bbox_inches=&#x27;tight&#x27;)plt.close()print(&quot;✅ 所有可视化图表已生成！&quot;)
🏃‍♀️ 进阶小挑战 挑战1：销售趋势分析
# 销售趋势分析挑战print(&quot;=== 销售趋势分析挑战 ===&quot;)# 创建销售数据销售数据 = pd.DataFrame(&#123; &#x27;日期&#x27;: pd.date_range(&#x27;2024-01-01&#x27;, periods=100, freq=&#x27;D&#x27;), &#x27;产品&#x27;: np.random.choice([&#x27;产品A&#x27;, &#x27;产品B&#x27;, &#x27;产品C&#x27;, &#x27;产品D&#x27;], 100), &#x27;销售员&#x27;: np.random.choice([&#x27;张三&#x27;, &#x27;李四&#x27;, &#x27;王五&#x27;, &#x27;赵六&#x27;], 100), &#x27;客户类型&#x27;: np.random.choice([&#x27;新客户&#x27;, &#x27;老客户&#x27;], 100), &#x27;销售额&#x27;: np.random.randint(1000, 10000, 100), &#x27;数量&#x27;: np.random.randint(10, 100, 100), &#x27;地区&#x27;: np.random.choice([&#x27;华北&#x27;, &#x27;华东&#x27;, &#x27;华南&#x27;, &#x27;西部&#x27;], 100)&#125;)# 添加月份和季度销售数据[&#x27;月份&#x27;] = 销售数据[&#x27;日期&#x27;].dt.month销售数据[&#x27;季度&#x27;] = 销售数据[&#x27;日期&#x27;].dt.quarterdef 销售趋势分析(df): &quot;&quot;&quot;销售趋势分析&quot;&quot;&quot; print(&quot;📈 开始销售趋势分析...&quot;) # 1. 时间趋势分析 print(&quot;
📊 时间趋势分析：&quot;) # 日销售额趋势 日销售 = df.groupby(&#x27;日期&#x27;)[&#x27;销售额&#x27;].sum() 销售增长 = 日销售.pct_change().mean() * 100 print(f&quot; 日均销售增长率：&#123;销售增长:.2f&#125;%&quot;) print(f&quot; 最高单日销售：&#123;日销售.max():,&#125;元（&#123;日销售.idxmax().strftime(&#x27;%Y-%m-%d&#x27;)&#125;）&quot;) print(f&quot; 最低单日销售：&#123;日销售.min():,&#125;元（&#123;日销售.idxmin().strftime(&#x27;%Y-%m-%d&#x27;)&#125;）&quot;) # 月度趋势 月度销售 = df.groupby(&#x27;月份&#x27;)[&#x27;销售额&#x27;].sum() print(f&quot;
 月度销售情况：&quot;) for 月份, 销售额 in 月度销售.items(): print(f&quot; &#123;月份&#125;月：&#123;销售额:,&#125;元&quot;) # 2. 产品表现分析 print(&quot;
📦 产品表现分析：&quot;) 产品分析 = df.groupby(&#x27;产品&#x27;).agg(&#123; &#x27;销售额&#x27;: [&#x27;sum&#x27;, &#x27;mean&#x27;, &#x27;count&#x27;], &#x27;数量&#x27;: &#x27;sum&#x27; &#125;).round(2) 产品分析.columns = [&#x27;总销售额&#x27;, &#x27;平均销售额&#x27;, &#x27;销售次数&#x27;, &#x27;总数量&#x27;] 产品分析 = 产品分析.sort_values(&#x27;总销售额&#x27;, ascending=False) print(&quot; 产品销售排名：&quot;) for 产品, 数据 in 产品分析.iterrows(): print(f&quot; &#123;产品&#125;：&#123;数据[&#x27;总销售额&#x27;]:,.2f&#125;元（&#123;数据[&#x27;销售次数&#x27;]&#125;次）&quot;) # 3. 销售员业绩分析 print(&quot;
🏆 销售员业绩分析：&quot;) 销售员分析 = df.groupby(&#x27;销售员&#x27;).agg(&#123; &#x27;销售额&#x27;: [&#x27;sum&#x27;, &#x27;mean&#x27;, &#x27;count&#x27;], &#x27;客户类型&#x27;: lambda x: (x == &#x27;新客户&#x27;).sum() &#125;).round(2) 销售员分析.columns = [&#x27;总销售额&#x27;, &#x27;平均销售额&#x27;, &#x27;销售次数&#x27;, &#x27;新客户数&#x27;] 销售员分析 = 销售员分析.sort_values(&#x27;总销售额&#x27;, ascending=False) print(&quot; 销售员业绩排名：&quot;) for 销售员, 数据 in 销售员分析.iterrows(): 新客户率 = 数据[&#x27;新客户数&#x27;] / 数据[&#x27;销售次数&#x27;] * 100 print(f&quot; &#123;销售员&#125;：&#123;数据[&#x27;总销售额&#x27;]:,.2f&#125;元（新客户率：&#123;新客户率:.1f&#125;%）&quot;) # 4. 地区分析 print(&quot;
🗺️ 地区销售分析：&quot;) 地区分析 = df.groupby(&#x27;地区&#x27;).agg(&#123; &#x27;销售额&#x27;: [&#x27;sum&#x27;, &#x27;mean&#x27;, &#x27;count&#x27;] &#125;).round(2) 地区分析.columns = [&#x27;总销售额&#x27;, &#x27;平均销售额&#x27;, &#x27;销售次数&#x27;] 地区分析[&#x27;市场占比&#x27;] = (地区分析[&#x27;总销售额&#x27;] / 地区分析[&#x27;总销售额&#x27;].sum() * 100).round(1) print(&quot; 地区市场表现：&quot;) for 地区, 数据 in 地区分析.iterrows(): print(f&quot; &#123;地区&#125;：&#123;数据[&#x27;总销售额&#x27;]:,.2f&#125;元（占比：&#123;数据[&#x27;市场占比&#x27;]&#125;%）&quot;) # 5. 客户类型分析 print(&quot;
👥 客户类型分析：&quot;) 客户分析 = df.groupby(&#x27;客户类型&#x27;).agg(&#123; &#x27;销售额&#x27;: [&#x27;sum&#x27;, &#x27;mean&#x27;, &#x27;count&#x27;] &#125;).round(2) 客户分析.columns = [&#x27;总销售额&#x27;, &#x27;平均销售额&#x27;, &#x27;客户数量&#x27;] for 客户类型, 数据 in 客户分析.iterrows(): print(f&quot; &#123;客户类型&#125;：&#123;数据[&#x27;总销售额&#x27;]:,.2f&#125;元（平均：&#123;数据[&#x27;平均销售额&#x27;]:.2f&#125;元/单）&quot;) # 6. 交叉分析 print(&quot;
🔗 交叉分析：&quot;) # 产品×地区 产品地区 = df.groupby([&#x27;产品&#x27;, &#x27;地区&#x27;])[&#x27;销售额&#x27;].sum().unstack(fill_value=0) print(&quot; 产品×地区销售矩阵：&quot;) print(产品地区) # 销售员×产品 销售产品 = df.groupby([&#x27;销售员&#x27;, &#x27;产品&#x27;])[&#x27;销售额&#x27;].sum().unstack(fill_value=0) print(&quot;
 销售员×产品销售矩阵：&quot;) print(销售产品) # 7. 异常检测 print(&quot;
⚠️ 异常销售检测：&quot;) # 使用IQR方法检测异常销售额 Q1 = df[&#x27;销售额&#x27;].quantile(0.25) Q3 = df[&#x27;销售额&#x27;].quantile(0.75) IQR = Q3 - Q1 下限 = Q1 - 1.5 * IQR 上限 = Q3 + 1.5 * IQR 异常销售 = df[(df[&#x27;销售额&#x27;] &lt; 下限) | (df[&#x27;销售额&#x27;] &gt; 上限)] print(f&quot; 发现异常销售：&#123;len(异常销售)&#125;笔&quot;) if len(异常销售) &gt; 0: print(f&quot; 异常销售额范围：&#123;异常销售[&#x27;销售额&#x27;].min():.2f&#125; - &#123;异常销售[&#x27;销售额&#x27;].max():.2f&#125;元&quot;) # 分析异常销售的特征 异常产品 = 异常销售[&#x27;产品&#x27;].value_counts().head(3) print(f&quot; 异常销售主要涉及产品：&#123;&#x27;, &#x27;.join(异常产品.index)&#125;&quot;) return &#123; &#x27;日销售&#x27;: 日销售, &#x27;月度销售&#x27;: 月度销售, &#x27;产品分析&#x27;: 产品分析, &#x27;销售员分析&#x27;: 销售员分析, &#x27;地区分析&#x27;: 地区分析, &#x27;异常销售&#x27;: 异常销售 &#125;# 执行销售趋势分析销售分析结果 = 销售趋势分析(销售数据)# 生成销售趋势图表plt.figure(figsize=(15, 10))# 子图1：日销售额趋势plt.subplot(2, 2, 1)日销售 = 销售分析结果[&#x27;日销售&#x27;]plt.plot(日销售.index, 日销售.values, marker=&#x27;o&#x27;, linewidth=2)plt.title(&#x27;日销售额趋势&#x27;, fontsize=14)plt.xlabel(&#x27;日期&#x27;)plt.ylabel(&#x27;销售额（元）&#x27;)plt.xticks(rotation=45)plt.grid(True, alpha=0.3)# 子图2：月度销售额柱状图plt.subplot(2, 2, 2)月度销售 = 销售分析结果[&#x27;月度销售&#x27;]plt.bar(月度销售.index, 月度销售.values, color=&#x27;skyblue&#x27;)plt.title(&#x27;月度销售额对比&#x27;, fontsize=14)plt.xlabel(&#x27;月份&#x27;)plt.ylabel(&#x27;销售额（元）&#x27;)# 子图3：产品销售额饼图plt.subplot(2, 2, 3)产品分析 = 销售分析结果[&#x27;产品分析&#x27;]plt.pie(产品分析[&#x27;总销售额&#x27;].values, labels=产品分析.index, autopct=&#x27;%1.1f%%&#x27;, startangle=90)plt.title(&#x27;产品销售占比&#x27;, fontsize=14)# 子图4：地区销售额柱状图plt.subplot(2, 2, 4)地区分析 = 销售分析结果[&#x27;地区分析&#x27;]plt.bar(地区分析.index, 地区分析[&#x27;总销售额&#x27;].values, color=&#x27;lightcoral&#x27;)plt.title(&#x27;地区销售对比&#x27;, fontsize=14)plt.xlabel(&#x27;地区&#x27;)plt.ylabel(&#x27;销售额（元）&#x27;)plt.xticks(rotation=45)plt.tight_layout()plt.savefig(&#x27;销售趋势分析图表.png&#x27;, dpi=300, bbox_inches=&#x27;tight&#x27;)plt.close()print(&quot;✅ 销售趋势分析图表已生成！&quot;)
挑战2：财务比率计算
# 财务比率计算挑战print(&quot;=== 财务比率计算挑战 ===&quot;)# 创建财务数据财务数据 = pd.DataFrame(&#123; &#x27;公司&#x27;: [&#x27;公司A&#x27;, &#x27;公司B&#x27;, &#x27;公司C&#x27;, &#x27;公司D&#x27;, &#x27;公司E&#x27;], &#x27;营业收入&#x27;: [1000000, 800000, 1200000, 600000, 1500000], &#x27;营业成本&#x27;: [600000, 480000, 720000, 420000, 900000], &#x27;营业利润&#x27;: [200000, 160000, 240000, 100000, 300000], &#x27;净利润&#x27;: [150000, 120000, 180000, 75000, 225000], &#x27;总资产&#x27;: [2000000, 1600000, 2400000, 1200000, 3000000], &#x27;总负债&#x27;: [800000, 640000, 960000, 480000, 1200000], &#x27;流动资产&#x27;: [1200000, 960000, 1440000, 720000, 1800000], &#x27;流动负债&#x27;: [600000, 480000, 720000, 360000, 900000], &#x27;应收账款&#x27;: [300000, 240000, 360000, 180000, 450000], &#x27;存货&#x27;: [400000, 320000, 480000, 240000, 600000]&#125;)def 计算综合财务比率(财务df): &quot;&quot;&quot;计算综合财务比率&quot;&quot;&quot; print(&quot;📊 计算综合财务比率...&quot;) # 创建结果DataFrame 比率结果 = 财务df.copy() # 1. 盈利能力比率 print(&quot;
💰 盈利能力比率：&quot;) 比率结果[&#x27;销售毛利率&#x27;] = (财务df[&#x27;营业收入&#x27;] - 财务df[&#x27;营业成本&#x27;]) / 财务df[&#x27;营业收入&#x27;] * 100 比率结果[&#x27;销售净利率&#x27;] = 财务df[&#x27;净利润&#x27;] / 财务df[&#x27;营业收入&#x27;] * 100 比率结果[&#x27;资产净利率&#x27;] = 财务df[&#x27;净利润&#x27;] / 财务df[&#x27;总资产&#x27;] * 100 比率结果[&#x27;净资产收益率&#x27;] = 财务df[&#x27;净利润&#x27;] / (财务df[&#x27;总资产&#x27;] - 财务df[&#x27;总负债&#x27;]) * 100 print(&quot; 已计算：销售毛利率、销售净利率、资产净利率、净资产收益率&quot;) # 2. 偿债能力比率 print(&quot;
🏦 偿债能力比率：&quot;) 比率结果[&#x27;流动比率&#x27;] = 财务df[&#x27;流动资产&#x27;] / 财务df[&#x27;流动负债&#x27;] 比率结果[&#x27;速动比率&#x27;] = (财务df[&#x27;流动资产&#x27;] - 财务df[&#x27;存货&#x27;]) / 财务df[&#x27;流动负债&#x27;] 比率结果[&#x27;资产负债率&#x27;] = 财务df[&#x27;总负债&#x27;] / 财务df[&#x27;总资产&#x27;] * 100 比率结果[&#x27;权益乘数&#x27;] = 财务df[&#x27;总资产&#x27;] / (财务df[&#x27;总资产&#x27;] - 财务df[&#x27;总负债&#x27;]) print(&quot; 已计算：流动比率、速动比率、资产负债率、权益乘数&quot;) # 3. 营运能力比率 print(&quot;
⚙️ 营运能力比率：&quot;) 比率结果[&#x27;应收账款周转率&#x27;] = 财务df[&#x27;营业收入&#x27;] / 财务df[&#x27;应收账款&#x27;] 比率结果[&#x27;存货周转率&#x27;] = 财务df[&#x27;营业成本&#x27;] / 财务df[&#x27;存货&#x27;] 比率结果[&#x27;总资产周转率&#x27;] = 财务df[&#x27;营业收入&#x27;] / 财务df[&#x27;总资产&#x27;] print(&quot; 已计算：应收账款周转率、存货周转率、总资产周转率&quot;) # 4. 综合评分 print(&quot;
📊 综合财务评分：&quot;) # 创建评分标准 评分标准 = &#123; &#x27;销售毛利率&#x27;: &#123;&#x27;优秀&#x27;: 30, &#x27;良好&#x27;: 20, &#x27;及格&#x27;: 10&#125;, &#x27;销售净利率&#x27;: &#123;&#x27;优秀&#x27;: 15, &#x27;良好&#x27;: 10, &#x27;及格&#x27;: 5&#125;, &#x27;净资产收益率&#x27;: &#123;&#x27;优秀&#x27;: 15, &#x27;良好&#x27;: 10, &#x27;及格&#x27;: 5&#125;, &#x27;流动比率&#x27;: &#123;&#x27;优秀&#x27;: 2.0, &#x27;良好&#x27;: 1.5, &#x27;及格&#x27;: 1.0&#125;, &#x27;速动比率&#x27;: &#123;&#x27;优秀&#x27;: 1.5, &#x27;良好&#x27;: 1.0, &#x27;及格&#x27;: 0.8&#125;, &#x27;资产负债率&#x27;: &#123;&#x27;优秀&#x27;: 40, &#x27;良好&#x27;: 50, &#x27;及格&#x27;: 60&#125; # 越低越好 &#125; def 计算单项评分(实际值, 标准, 指标名称): &quot;&quot;&quot;计算单项指标评分&quot;&quot;&quot; if &#x27;资产负债率&#x27; in 指标名称: # 负向指标，越低越好 if 实际值 &lt;= 标准[&#x27;优秀&#x27;]: return 100 elif 实际值 &lt;= 标准[&#x27;良好&#x27;]: return 80 elif 实际值 &lt;= 标准[&#x27;及格&#x27;]: return 60 else: return 40 else: # 正向指标，越高越好 if 实际值 &gt;= 标准[&#x27;优秀&#x27;]: return 100 elif 实际值 &gt;= 标准[&#x27;良好&#x27;]: return 80 elif 实际值 &gt;= 标准[&#x27;及格&#x27;]: return 60 else: return 40 # 计算各项评分 评分列 = [] for 指标, 标准 in 评分标准.items(): 评分列.append(f&quot;&#123;指标&#125;_评分&quot;) 比率结果[f&quot;&#123;指标&#125;_评分&quot;] = 比率结果[指标].apply( lambda x: 计算单项评分(x, 标准, 指标) ) # 计算综合评分 比率结果[&#x27;综合财务评分&#x27;] = 比率结果[评分列].mean(axis=1) # 财务等级评定 def 评定财务等级(综合评分): if 综合评分 &gt;= 90: return &quot;优秀&quot; elif 综合评分 &gt;= 80: return &quot;良好&quot; elif 综合评分 &gt;= 70: return &quot;一般&quot; elif 综合评分 &gt;= 60: return &quot;及格&quot; else: return &quot;较差&quot; 比率结果[&#x27;财务等级&#x27;] = 比率结果[&#x27;综合财务评分&#x27;].apply(评定财务等级) print(&quot; 已计算：综合财务评分、财务等级&quot;) return 比率结果# 执行财务比率计算财务比率结果 = 计算综合财务比率(财务数据)print(&quot;
📊 财务比率分析结果：&quot;)# 显示关键比率关键比率 = [&#x27;销售毛利率&#x27;, &#x27;销售净利率&#x27;, &#x27;净资产收益率&#x27;, &#x27;流动比率&#x27;, &#x27;资产负债率&#x27;, &#x27;综合财务评分&#x27;]print(&quot;
关键财务比率：&quot;)for 比率 in 关键比率: print(f&quot;
&#123;比率&#125;：&quot;) for 公司, 数值 in 财务比率结果[[&#x27;公司&#x27;, 比率]].values: if &#x27;%&#x27; in 比率 or &#x27;评分&#x27; in 比率: print(f&quot; &#123;公司&#125;：&#123;数值:.1f&#125;&#123;&#x27;%&#x27; if &#x27;%&#x27; in 比率 else &#x27;分&#x27;&#125;&quot;) else: print(f&quot; &#123;公司&#125;：&#123;数值:.2f&#125;&quot;)# 显示财务等级print(f&quot;
🏆 财务等级评定：&quot;)for 公司, 等级 in 财务比率结果[[&#x27;公司&#x27;, &#x27;财务等级&#x27;]].values: print(f&quot; &#123;公司&#125;：&#123;等级&#125;&quot;)# 生成财务比率雷达图from math import piplt.figure(figsize=(10, 10))# 选择几个关键比率做雷达图雷达图指标 = [&#x27;销售毛利率&#x27;, &#x27;销售净利率&#x27;, &#x27;净资产收益率&#x27;, &#x27;流动比率&#x27;, &#x27;综合财务评分&#x27;]雷达图数据 = 财务比率结果[雷达图指标].values# 标准化数据（0-100分）for i, 指标 in enumerate(雷达图指标): if 指标 == &#x27;流动比率&#x27;: # 特殊处理，超过2的按100分算 雷达图数据[:, i] = np.minimum(雷达图数据[:, i] / 2 * 100, 100) elif 指标 not in [&#x27;综合财务评分&#x27;]: # 百分比指标直接乘以100 雷达图数据[:, i] = 雷达图_data[:, i]角度 = np.linspace(0, 2 * pi, len(雷达图指标), endpoint=False).tolist()角度 += 角度[:1] # 闭合图形# 为每家公司绘制雷达图颜色 = [&#x27;red&#x27;, &#x27;blue&#x27;, &#x27;green&#x27;, &#x27;orange&#x27;, &#x27;purple&#x27;]for i, (公司, 数据) in enumerate(zip(财务比率结果[&#x27;公司&#x27;], 雷达图数据)): 值 = 数据.tolist() 值 += 值[:1] # 闭合图形 plt.polar(角度, 值, &#x27;o-&#x27;, linewidth=2, label=公司, color=颜色[i]) plt.fill(角度, 值, alpha=0.25, color=颜色[i])plt.xticks(角度[:-1], 雷达图指标)plt.ylim(0, 100)plt.title(&#x27;财务比率雷达图&#x27;, fontsize=16, pad=20)plt.legend(loc=&#x27;upper right&#x27;, bbox_to_anchor=(1.3, 1.0))plt.tight_layout()plt.savefig(&#x27;财务比率雷达图.png&#x27;, dpi=300, bbox_inches=&#x27;tight&#x27;)plt.close()print(&quot;✅ 财务比率雷达图已生成！&quot;)
