导语上篇我们用Python管理个人账目，但工作中更常见的是“成堆的Excel文件”——月度报表、部门预算、项目台账…一个个手动调整格式、合并数据，简直是体力活！今天我们去芜存菁，写一个Excel批量处理器：批量改格式、批量转文件、批量合并数据。一次编写，解放双手！
本篇目标 掌握openpyxl库操作Excel单元格 实现批量格式调整（字体、颜色、列宽） 完成Excel ↔ CSV批量互转 实现多文件数据自动合并 打造带进度显示的批量处理工具
一、准备工作：安装必要库# 在命令行运行# pip install openpyxl pandasimport openpyxlfrom openpyxl.styles import Font, PatternFill, Alignmentfrom openpyxl.utils import get_column_letterimport pandas as pdimport osimport globfrom datetime import datetime
二、认识Excel的“骨架”用openpyxl操作Excel，先理解三层结构：
Workbook：整个Excel文件（工作簿） Worksheet：工作表（Sheet） Cell：单元格
# ========== 探索Excel结构 ==========def explore_excel(file_path): &quot;&quot;&quot;查看Excel文件结构&quot;&quot;&quot; wb = openpyxl.load_workbook(file_path) print(f&quot;📊 Excel文件包含 &#123;len(wb.sheetnames)&#125; 个工作表:&quot;) for i, name in enumerate(wb.sheetnames, 1): print(f&quot; &#123;i&#125;. &#123;name&#125;&quot;) # 查看第一个表的数据 ws = wb.active # 获取活动工作表 print(f&quot;
表名: &#123;ws.title&#125;&quot;) print(f&quot;最大行数: &#123;ws.max_row&#125;&quot;) print(f&quot;最大列数: &#123;ws.max_column&#125;&quot;) # 读取A1单元格 cell = ws[&#x27;A1&#x27;] print(f&quot;A1单元格值: &#123;cell.value&#125;&quot;) print(f&quot;A1单元格类型: &#123;type(cell.value)&#125;&quot;) wb.close()# 创建一个测试文件来演示def create_test_excel(): &quot;&quot;&quot;创建测试Excel&quot;&quot;&quot; wb = openpyxl.Workbook() ws = wb.active ws.title = &quot;销售数据&quot; # 写入标题 data = [ [&quot;日期&quot;, &quot;产品&quot;, &quot;销售额&quot;, &quot;成本&quot;, &quot;利润&quot;], [&quot;2026-01-01&quot;, &quot;产品A&quot;, 5000, 3000, 2000], [&quot;2026-01-02&quot;, &quot;产品B&quot;, 8000, 4500, 3500] ] for row in data: ws.append(row) wb.save(&quot;测试数据.xlsx&quot;) print(&quot;✅ 创建测试文件: 测试数据.xlsx&quot;) return &quot;测试数据.xlsx&quot;# 运行测试# test_file = create_test_excel()# explore_excel(test_file)
三、自动化重复操作：批量美化格式例如需要统一的格式：标题加粗、数字用千分位、利润标红…手动调10个文件眼睛都花了！ # ========== 批量格式美化 ==========def beautify_excel(file_path): &quot;&quot;&quot;美化单个Excel文件&quot;&quot;&quot; wb = openpyxl.load_workbook(file_path) ws = wb.active print(f&quot;🎨 正在美化: &#123;file_path&#125;&quot;) # 1. 标题行加粗、背景色 header_fill = PatternFill(start_color=&quot;4472C4&quot;, end_color=&quot;4472C4&quot;, fill_type=&quot;solid&quot;) header_font = Font(bold=True, color=&quot;FFFFFF&quot;, size=12) for col in range(1, ws.max_column + 1): cell = ws.cell(row=1, column=col) cell.fill = header_fill cell.font = header_font cell.alignment = Alignment(horizontal=&quot;center&quot;, vertical=&quot;center&quot;) # 2. 数字列添加千分位符 for row in range(2, ws.max_row + 1): for col in [3, 4, 5]: # 假设第3、4、5列是数字 cell = ws.cell(row=row, column=col) if isinstance(cell.value, (int, float)): cell.number_format = &#x27;#,##0.00&#x27; # 千分位保留2位小数 # 3. 利润列自动标红（负利润） for row in range(2, ws.max_row + 1): profit_cell = ws.cell(row=row, column=5) if isinstance(profit_cell.value, (int, float)) and profit_cell.value &lt; 0: profit_cell.font = Font(color=&quot;FF0000&quot;, bold=True) # 4. 自动调整列宽 for col in range(1, ws.max_column + 1): max_length = 0 column_letter = get_column_letter(col) for row in range(1, ws.max_row + 1): cell = ws.cell(row=row, column=col) try: if cell.value: max_length = max(max_length, len(str(cell.value))) except: pass # 设置列宽（字符数+2） ws.column_dimensions[column_letter].width = min(max_length + 2, 50) # 5. 添加边框 from openpyxl.styles import Border, Side thin_border = Border( left=Side(style=&#x27;thin&#x27;), right=Side(style=&#x27;thin&#x27;), top=Side(style=&#x27;thin&#x27;), bottom=Side(style=&#x27;thin&#x27;) ) for row in range(1, ws.max_row + 1): for col in range(1, ws.max_column + 1): ws.cell(row=row, column=col).border = thin_border # 保存 new_path = file_path.replace(&#x27;.xlsx&#x27;, &#x27;_美化.xlsx&#x27;) wb.save(new_path) wb.close() print(f&quot;✅ 美化完成，保存为: &#123;new_path&#125;&quot;)# 测试美化# beautify_excel(&quot;测试数据.xlsx&quot;)
四、批量格式转换4.1 Excel批量转CSVCSV更轻量，适合数据交换： # ========== Excel转CSV ==========def excel_to_csv(excel_path): &quot;&quot;&quot;单个Excel转CSV&quot;&quot;&quot; try: # 读取Excel的第一个sheet df = pd.read_excel(excel_path, sheet_name=0) # 生成CSV文件名 csv_path = excel_path.replace(&#x27;.xlsx&#x27;, &#x27;.csv&#x27;).replace(&#x27;.xls&#x27;, &#x27;.csv&#x27;) # 保存为CSV df.to_csv(csv_path, index=False, encoding=&#x27;utf-8-sig&#x27;) # utf-8-sig防止中文乱码 print(f&quot;✅ &#123;excel_path&#125; -&gt; &#123;csv_path&#125;&quot;) return True except Exception as e: print(f&quot;❌ 转换失败 &#123;excel_path&#125;: &#123;e&#125;&quot;) return Falsedef batch_excel_to_csv(folder_path): &quot;&quot;&quot;批量转换文件夹内所有Excel&quot;&quot;&quot; print(f&quot;
📂 开始批量转换: &#123;folder_path&#125;&quot;) # 查找所有Excel文件 excel_files = glob.glob(os.path.join(folder_path, &quot;*.xlsx&quot;)) + \ glob.glob(os.path.join(folder_path, &quot;*.xls&quot;)) if not excel_files: print(&quot;⚠️ 未找到Excel文件&quot;) return success = 0 for file in excel_files: if excel_to_csv(file): success += 1 print(f&quot;
📊 完成！成功转换 &#123;success&#125;/&#123;len(excel_files)&#125; 个文件&quot;)# 测试转换# 先创建几个测试文件def create_test_files(): os.makedirs(&quot;测试文件夹&quot;, exist_ok=True) for i in range(3): wb = openpyxl.Workbook() ws = wb.active ws.append([&quot;日期&quot;, f&quot;数据&#123;i+1&#125;&quot;]) for row in range(5): ws.append([f&quot;2026-01-&#123;row+1&#125;&quot;, (row+1)*100]) wb.save(f&quot;测试文件夹/报表_&#123;i+1&#125;.xlsx&quot;) print(&quot;✅ 创建测试文件完成&quot;)# create_test_files()# batch_excel_to_csv(&quot;测试文件夹&quot;)
4.2 CSV批量转Excel反向转换同样简单： # ========== CSV转Excel ==========def csv_to_excel(csv_path): &quot;&quot;&quot;单个CSV转Excel&quot;&quot;&quot; try: df = pd.read_csv(csv_path) excel_path = csv_path.replace(&#x27;.csv&#x27;, &#x27;.xlsx&#x27;) df.to_excel(excel_path, index=False, engine=&#x27;openpyxl&#x27;) print(f&quot;✅ &#123;csv_path&#125; -&gt; &#123;excel_path&#125;&quot;) return True except Exception as e: print(f&quot;❌ 转换失败 &#123;csv_path&#125;: &#123;e&#125;&quot;) return Falsedef batch_csv_to_excel(folder_path): &quot;&quot;&quot;批量转换CSV到Excel&quot;&quot;&quot; print(f&quot;
📂 开始批量转换: &#123;folder_path&#125;&quot;) csv_files = glob.glob(os.path.join(folder_path, &quot;*.csv&quot;)) if not csv_files: print(&quot;⚠️ 未找到CSV文件&quot;) return success = 0 for file in csv_files: if csv_to_excel(file): success += 1 print(f&quot;
📊 完成！成功转换 &#123;success&#125;/&#123;len(csv_files)&#125; 个文件&quot;)
五、多文件数据合并最常见的场景：合并各部门的月度报表、汇总各项目成本… # ========== 多文件数据合并 ==========def merge_excels(file_list, output_path=&quot;合并结果.xlsx&quot;): &quot;&quot;&quot; 合并多个Excel文件的数据（垂直合并） file_list: Excel文件路径列表 &quot;&quot;&quot; print(f&quot;
🔗 开始合并 &#123;len(file_list)&#125; 个文件...&quot;) all_data = [] for i, file_path in enumerate(file_list, 1): print(f&quot; [&#123;i&#125;/&#123;len(file_list)&#125;] 读取: &#123;os.path.basename(file_path)&#125;&quot;) try: # 读取每个文件的第一个sheet df = pd.read_excel(file_path) # 添加来源标记 df[&#x27;来源文件&#x27;] = os.path.basename(file_path) all_data.append(df) except Exception as e: print(f&quot; ❌ 读取失败: &#123;e&#125;&quot;) if not all_data: print(&quot;⚠️ 没有成功读取任何文件&quot;) return # 合并所有数据 merged_df = pd.concat(all_data, ignore_index=True) # 保存结果 merged_df.to_excel(output_path, index=False, engine=&#x27;openpyxl&#x27;) print(f&quot;
✅ 合并完成！共 &#123;len(merged_df)&#125; 行数据&quot;) print(f&quot;📊 保存为: &#123;output_path&#125;&quot;) # 显示前5行预览 print(&quot;
预览前5行：&quot;) print(merged_df.head().to_string()) return merged_dfdef merge_all_in_folder(folder_path, output_path=None): &quot;&quot;&quot;合并文件夹内所有Excel文件&quot;&quot;&quot; excel_files = glob.glob(os.path.join(folder_path, &quot;*.xlsx&quot;)) + \ glob.glob(os.path.join(folder_path, &quot;*.xls&quot;)) if not excel_files: print(&quot;⚠️ 未找到Excel文件&quot;) return if output_path is None: output_path = os.path.join(folder_path, &quot;合并结果.xlsx&quot;) return merge_excels(excel_files, output_path)# 测试合并# merge_all_in_folder(&quot;测试文件夹&quot;)
六、完整项目：Excel批量处理器整合所有功能，打造一个带菜单的工具： # ========== Excel批量处理器 - 完整版 ==========import osimport globimport openpyxlimport pandas as pdfrom openpyxl.styles import Font, PatternFill, Alignment, Border, Sidefrom openpyxl.utils import get_column_letterfrom datetime import datetimedef show_menu(): &quot;&quot;&quot;显示菜单&quot;&quot;&quot; print(&quot;
&quot; + &quot;=&quot; * 55) print(&quot;Excel批量处理器 v1.0&quot;) print(&quot;=&quot; * 55) print(&quot;1. 批量美化Excel格式&quot;) print(&quot;2. Excel批量转CSV&quot;) print(&quot;3. CSV批量转Excel&quot;) print(&quot;4. 合并多个Excel文件&quot;) print(&quot;5. 退出&quot;) print(&quot;=&quot; * 55)def get_folder_path(): &quot;&quot;&quot;获取文件夹路径&quot;&quot;&quot; path = input(&quot;
请输入文件夹路径（直接回车使用当前目录）: &quot;).strip() if not path: path = os.getcwd() if not os.path.isdir(path): print(&quot;❌ 路径不存在！&quot;) return None return pathdef batch_beautify(): &quot;&quot;&quot;批量美化&quot;&quot;&quot; folder = get_folder_path() if not folder: return excel_files = glob.glob(os.path.join(folder, &quot;*.xlsx&quot;)) if not excel_files: print(&quot;⚠️ 未找到Excel文件&quot;) return print(f&quot;
🎨 开始批量美化 &#123;len(excel_files)&#125; 个文件...&quot;) for file in excel_files: try: beautify_excel(file) except Exception as e: print(f&quot;处理失败: &#123;e&#125;&quot;) print(&quot;
✅ 全部美化完成！&quot;)def batch_excel_to_csv(): &quot;&quot;&quot;批量Excel转CSV&quot;&quot;&quot; folder = get_folder_path() if folder: batch_excel_to_csv_impl(folder)def batch_csv_to_excel(): &quot;&quot;&quot;批量CSV转Excel&quot;&quot;&quot; folder = get_folder_path() if folder: batch_csv_to_excel_impl(folder)def merge_files(): &quot;&quot;&quot;合并文件&quot;&quot;&quot; folder = get_folder_path() if folder: output = input(&quot;输出文件名（默认：合并结果.xlsx）: &quot;).strip() or &quot;合并结果.xlsx&quot; merge_all_in_folder(folder, output)def main(): while True: show_menu() choice = input(&quot;
请选择功能（1-5）: &quot;).strip() if choice == &quot;1&quot;: batch_beautify() elif choice == &quot;2&quot;: batch_excel_to_csv() elif choice == &quot;3&quot;: batch_excel_to_csv() elif choice == &quot;4&quot;: merge_files() elif choice == &quot;5&quot;: print(&quot;👋 感谢使用，再见！&quot;) break else: print(&quot;请输入1-5之间的数字！&quot;)# ============= 实现函数 =============def beautify_excel(file_path): &quot;&quot;&quot;美化单个文件&quot;&quot;&quot; wb = openpyxl.load_workbook(file_path) ws = wb.active # 标题样式 header_fill = PatternFill(start_color=&quot;4472C4&quot;, end_color=&quot;4472C4&quot;, fill_type=&quot;solid&quot;) header_font = Font(bold=True, color=&quot;FFFFFF&quot;, size=12) for col in range(1, ws.max_column + 1): cell = ws.cell(row=1, column=col) cell.fill = header_fill cell.font = header_font cell.alignment = Alignment(horizontal=&quot;center&quot;) # 数字格式 for row in range(2, ws.max_row + 1): for col in range(1, ws.max_column + 1): cell = ws.cell(row=row, column=col) if isinstance(cell.value, (int, float)): cell.number_format = &#x27;#,##0.00&#x27; # 列宽自适应 for col in range(1, ws.max_column + 1): max_len = 0 col_letter = get_column_letter(col) for row in range(1, ws.max_row + 1): val = ws.cell(row=row, column=col).value if val: max_len = max(max_len, len(str(val))) ws.column_dimensions[col_letter].width = min(max_len + 2, 50) # 边框 thin_border = Border( left=Side(style=&#x27;thin&#x27;), right=Side(style=&#x27;thin&#x27;), top=Side(style=&#x27;thin&#x27;), bottom=Side(style=&#x27;thin&#x27;) ) for row in range(1, ws.max_row + 1): for col in range(1, ws.max_column + 1): ws.cell(row=row, column=col).border = thin_border new_path = file_path.replace(&#x27;.xlsx&#x27;, &#x27;_美化.xlsx&#x27;) wb.save(new_path) wb.close() print(f&quot; ✅ &#123;os.path.basename(file_path)&#125;&quot;)def batch_excel_to_csv_impl(folder_path): &quot;&quot;&quot;Excel转CSV实现&quot;&quot;&quot; excel_files = glob.glob(os.path.join(folder_path, &quot;*.xlsx&quot;)) + \ glob.glob(os.path.join(folder_path, &quot;*.xls&quot;)) if not excel_files: print(&quot;⚠️ 未找到Excel文件&quot;) return print(f&quot;
