四、年度汇算准备# ========== 年度汇算清缴 ==========class TaxYearCalculator: &quot;&quot;&quot;年度个税计算器&quot;&quot;&quot; def __init__(self, deduction_manager: SpecialDeductionManager): self.dm = deduction_manager self.records = [] def add_monthly_record(self, month: int, income: float, insurance: float, tax_paid: float): &quot;&quot;&quot;添加月度数据&quot;&quot;&quot; self.records.append(&#123; &quot;月份&quot;: month, &quot;收入&quot;: income, &quot;五险一金&quot;: insurance, &quot;已缴个税&quot;: tax_paid &#125;) print(f&quot;✅ 已记录 &#123;month&#125;月数据&quot;) def generate_annual_report(self): &quot;&quot;&quot;生成年度汇算报告&quot;&quot;&quot; if not self.records: print(&quot;⚠️ 暂无月度数据&quot;) return print(&quot;
