五、完整项目代码# ========== 个人税务助手 - 完整版 ==========import jsonimport pandas as pdfrom datetime import datetimefrom typing import Dictimport os# 2025年个税税率表TAX_BRACKETS = [ (0, 36000, 0.03, 0), (36000, 144000, 0.10, 2520), (144000, 300000, 0.20, 16920), (300000, 420000, 0.25, 31920), (420000, 660000, 0.30, 52920), (660000, 960000, 0.35, 85920), (960000, float(&#x27;inf&#x27;), 0.45, 181920)]class SpecialDeductionManager: &quot;&quot;&quot;专项附加扣除管理&quot;&quot;&quot; DEDUCTION_STANDARDS = &#123; &quot;子女教育&quot;: 2000, &quot;继续教育&quot;: 400, &quot;大病医疗&quot;: 0, &quot;住房贷款利息&quot;: 1000, &quot;住房租金&quot;: 1500, &quot;赡养老人&quot;: 3000, &quot;3岁以下婴幼儿照护&quot;: 2000 &#125; def __init__(self, data_file=&quot;deductions.json&quot;): self.data_file = data_file self.deductions = self.load_deductions() def load_deductions(self): if os.path.exists(self.data_file): try: with open(self.data_file, &#x27;r&#x27;, encoding=&#x27;utf-8&#x27;) as f: return json.load(f) except: pass return &#123;&#125; def save_deductions(self): with open(self.data_file, &#x27;w&#x27;, encoding=&#x27;utf-8&#x27;) as f: json.dump(self.deductions, f, ensure_ascii=False, indent=2) def add_deduction(self, category: str, details: str, amount: float = None): if category not in self.DEDUCTION_STANDARDS: print(f&quot;❌ 无效类别: &#123;category&#125;&quot;) return False if amount is None: amount = self.DEDUCTION_STANDARDS[category] self.deductions[category] = &#123; &quot;金额&quot;: amount, &quot;详情&quot;: details, &quot;添加时间&quot;: datetime.now().strftime(&#x27;%Y-%m-%d&#x27;) &#125; self.save_deductions() print(f&quot;✅ 已添加 &#123;category&#125;: ¥&#123;amount&#125;/月&quot;) return True def remove_deduction(self, category: str): if category in self.deductions: del self.deductions[category] self.save_deductions() print(f&quot;✅ 已删除 &#123;category&#125;&quot;) else: print(f&quot;⚠️ 未找到 &#123;category&#125;&quot;) def list_deductions(self): if not self.deductions: print(&quot;📭 暂无扣除项&quot;) return &#123;&#125; total = 0 print(