导语前面我们写的代码都是“一股脑”顺序执行，像记流水账。但现实世界的财务系统不是这样的：员工、部门、工资单、报销单…每个都是“独立个体”，互相协作。今天咱们用财务最熟悉的公司组织架构，来理解面向对象编程（OOP）：把代码拆成一个个“部门”，每个部门有自己的“职责”和“账本”，既能独立工作又能互相配合。
本篇目标 用公司组织架构理解“类”和“对象” 掌握封装：保护数据不被随意篡改 理解继承：子公司继承总公司制度 体会多态：不同部门对同一指令的不同处理 实战：构建可扩展的员工管理系统
一、不用安装，直接开干面向对象编程是Python的内置功能，无需额外安装库。准备好我们的老朋友就行：# 纯Python，无需安装import jsonfrom datetime import datetimefrom typing import List, Dictimport os
二、类和对象：用公司组织架构理解2.1 什么是类？什么是对象？类（Class） = 公司部门章程定义了“员工应该有什么属性（姓名、工号、薪资），能做什么（上班、请假、报销）” 对象（Object） = 具体的某个员工根据章程创建的“活生生的人”，比如“张三，工号1001，薪资15000” # ========== 定义&quot;员工&quot;类（部门章程） ==========class Employee: &quot;&quot;&quot; 员工类 - 就像一个公司的《员工手册》 规定了所有员工应该有的信息和方法 &quot;&quot;&quot; # 类属性：所有员工共享（就像公司的公积金比例） company_name = &quot;智慧财务科技有限公司&quot; social_insurance_rate = 0.105 # 五险一金比例 def __init__(self, name: str, employee_id: str, department: str, base_salary: float): &quot;&quot;&quot; 初始化方法：新员工入职时调用 就像新员工填写入职登记表 &quot;&quot;&quot; self.name = name # 实例属性：姓名 self.employee_id = employee_id # 工号 self.department = department # 部门 self.base_salary = base_salary # 基本工资 self.onboard_date = datetime.now().strftime(&#x27;%Y-%m-%d&#x27;) # 入职日期 self.is_active = True # 是否在职 print(f&quot;✅ 新员工入职成功：&#123;name&#125;（&#123;employee_id&#125;）&quot;) def get_monthly_salary(self) -&gt; float: &quot;&quot;&quot; 计算月薪（税后估算） 这是一个&quot;方法&quot;，员工可以&quot;做&quot;的计算 &quot;&quot;&quot; insurance = self.base_salary * self.social_insurance_rate taxable = self.base_salary - insurance - 5000 # 起征点 if taxable &lt;= 0: tax = 0 elif taxable &lt;= 36000: tax = taxable * 0.03 else: tax = taxable * 0.10 - 2520 # 简化计算 return self.base_salary - insurance - tax def take_leave(self, days: int): &quot;&quot;&quot;请假&quot;&quot;&quot; if days &lt;= 0: print(&quot;❌ 请假天数必须大于0&quot;) return if days &gt; 10: print(f&quot;⚠️ &#123;self.name&#125;请假&#123;days&#125;天，需要CEO审批！&quot;) else: print(f&quot;✅ &#123;self.name&#125;（&#123;self.department&#125;）请假&#123;days&#125;天已批准&quot;) def __str__(self): &quot;&quot;&quot;打印员工信息&quot;&quot;&quot; return f&quot;【员工】&#123;self.name&#125; | 工号:&#123;self.employee_id&#125; | 部门:&#123;self.department&#125; | 薪资:¥&#123;self.base_salary:,.2f&#125;&quot;# 测试：创建几个员工对象print(&quot;=&quot; * 50)print(&quot;员工入职模拟&quot;)print(&quot;=&quot; * 50)# 根据&quot;员工手册&quot;（类）创建具体员工（对象）emp1 = Employee(&quot;张三&quot;, &quot;E1001&quot;, &quot;财务部&quot;, 15000)emp2 = Employee(&quot;李四&quot;, &quot;E1002&quot;, &quot;销售部&quot;, 12000)emp3 = Employee(&quot;王五&quot;, &quot;E1003&quot;, &quot;技术部&quot;, 20000)# 调用对象方法print(f&quot;
&#123;emp1&#125;&quot;)print(f&quot;实际月薪：¥&#123;emp1.get_monthly_salary():,.2f&#125;&quot;)emp1.take_leave(3)print(f&quot;
&#123;emp2&#125;&quot;)emp2.take_leave(15) # 触发长假期提醒
三、封装：财务室的保险箱封装 = 保险箱 + 权限管理内部数据（工资明细）不能随便改，必须通过“规定流程”（方法）访问 # ========== 封装演示：薪资保密 ==========class SalaryManager: &quot;&quot;&quot; 薪资管理器：封装了敏感数据 就像财务部的保险柜，密码只有特定人能开 &quot;&quot;&quot; def __init__(self): self.__salary_data = &#123;&#125; # 私有属性：双下划线开头，外部无法直接访问 self.__access_log = [] # 访问日志，也是私有的 def add_salary_record(self, emp_id: str, month: str, amount: float): &quot;&quot;&quot;添加薪资记录（只有这个方法能操作数据）&quot;&quot;&quot; key = f&quot;&#123;emp_id&#125;_&#123;month&#125;&quot; self.__salary_data[key] = &#123; &#x27;金额&#x27;: amount, &#x27;录入时间&#x27;: datetime.now().strftime(&#x27;%Y-%m-%d %H:%M:%S&#x27;) &#125; print(f&quot;✅ 薪资记录已加密保存&quot;) def get_salary(self, emp_id: str, month: str, requester: str) -&gt; float: &quot;&quot;&quot; 获取薪资：需要记录谁在查 就像财务部要求查工资必须登记 &quot;&quot;&quot; key = f&quot;&#123;emp_id&#125;_&#123;month&#125;&quot; if key in self.__salary_data: # 记录访问日志 self.__access_log.append(&#123; &#x27;查询人&#x27;: requester, &#x27;员工&#x27;: emp_id, &#x27;月份&#x27;: month, &#x27;查询时间&#x27;: datetime.now().strftime(&#x27;%Y-%m-%d %H:%M:%S&#x27;) &#125;) return self.__salary_data[key][&#x27;金额&#x27;] else: print(&quot;⚠️ 未找到该员工薪资记录&quot;) return 0 def show_access_log(self): &quot;&quot;&quot;查看访问日志（管理员权限）&quot;&quot;&quot; print(&quot;
&quot; + &quot;=&quot; * 40) print(&quot;薪资查询访问日志&quot;) print(&quot;=&quot; * 40) for log in self.__access_log: print(f&quot;&#123;log[&#x27;查询时间&#x27;]&#125; | &#123;log[&#x27;查询人&#x27;]&#125; 查询了 &#123;log[&#x27;员工&#x27;]&#125; 的 &#123;log[&#x27;月份&#x27;]&#125; 工资&quot;)# 测试封装salary_mgr = SalaryManager()salary_mgr.add_salary_record(&quot;E1001&quot;, &quot;2025-01&quot;, 12500)# 只能通过方法访问salary = salary_mgr.get_salary(&quot;E1001&quot;, &quot;2025-01&quot;, &quot;人事专员小王&quot;)print(f&quot;查询到薪资：¥&#123;salary:,.2f&#125;&quot;)# 无法直接访问私有属性（会报错）# print(salary_mgr.__salary_data) # 报错！# 查看访问日志salary_mgr.show_access_log()
四、继承：总公司和子公司继承 = 子公司继承总公司制度 + 自己特色销售部员工也是员工，但有额外的“提成”属性 # ========== 继承演示：不同部门员工 ==========class SalesEmployee(Employee): &quot;&quot;&quot; 销售部员工：继承自Employee，增加销售提成 就像子公司有自己的特殊规定 &quot;&quot;&quot; def __init__(self, name: str, employee_id: str, base_salary: float, commission_rate: float = 0.05): # 调用父类的初始化方法（继承总公司的入职流程） super().__init__(name, employee_id, &quot;销售部&quot;, base_salary) self.commission_rate = commission_rate # 提成比例 self.monthly_sales = 0 # 本月销售额 def record_sales(self, amount: float): &quot;&quot;&quot;记录销售额&quot;&quot;&quot; self.monthly_sales += amount print(f&quot;✅ &#123;self.name&#125;本月销售额增加¥&#123;amount:,.2f&#125;，累计¥&#123;self.monthly_sales:,.2f&#125;&quot;) def get_monthly_salary(self) -&gt; float: &quot;&quot;&quot; 重写父类方法：销售薪资 = 基本工资 + 提成 - 税费 这就是多态：同样的&quot;计算工资&quot;指令，销售和财务执行方式不同 &quot;&quot;&quot; base_salary = super().get_monthly_salary() # 先算基本工资税后 commission = self.monthly_sales * self.commission_rate # 提成部分也扣税（简化） commission_tax = commission * 0.10 if commission &gt; 0 else 0 total_salary = base_salary + commission - commission_tax print(f&quot;💰 &#123;self.name&#125;薪资构成：底薪¥&#123;base_salary:,.2f&#125; + 提成¥&#123;commission:,.2f&#125; - 税费¥&#123;commission_tax:,.2f&#125;&quot;) return total_salary def __str__(self): &quot;&quot;&quot;重写父类的字符串表示&quot;&quot;&quot; return f&quot;【销售精英】&#123;self.name&#125; | 工号:&#123;self.employee_id&#125; | 提成比例:&#123;self.commission_rate:.1%&#125; | 本月业绩:¥&#123;self.monthly_sales:,.2f&#125;&quot;class TechEmployee(Employee): &quot;&quot;&quot; 技术部员工：有项目奖金 &quot;&quot;&quot; def __init__(self, name: str, employee_id: str, base_salary: float, project_bonus: float = 0): super().__init__(name, employee_id, &quot;技术部&quot;, base_salary) self.project_bonus = project_bonus def get_monthly_salary(self) -&gt; float: &quot;&quot;&quot;技术部薪资：基本工资 + 项目奖金&quot;&quot;&quot; base_salary = super().get_monthly_salary() total = base_salary + self.project_bonus print(f&quot;💰 &#123;self.name&#125;薪资构成：底薪¥&#123;base_salary:,.2f&#125; + 项目奖金¥&#123;self.project_bonus:,.2f&#125;&quot;) return total# 测试继承print(&quot;
&quot; + &quot;=&quot; * 50)print(&quot;不同部门员工测试&quot;)print(&quot;=&quot; * 50)sales_emp = SalesEmployee(&quot;赵六&quot;, &quot;E2001&quot;, 8000, commission_rate=0.08)sales_emp.record_sales(50000) # 本月卖5万sales_emp.record_sales(30000) # 又卖3万print(f&quot;
&#123;sales_emp&#125;&quot;)print(f&quot;实际月薪：¥&#123;sales_emp.get_monthly_salary():,.2f&#125;&quot;)tech_emp = TechEmployee(&quot;孙七&quot;, &quot;E3001&quot;, 18000, project_bonus=5000)print(f&quot;
&#123;tech_emp&#125;&quot;)print(f&quot;实际月薪：¥&#123;tech_emp.get_monthly_salary():,.2f&#125;&quot;)
五、多态：同一条指令，不同反应多态 = 不同部门对“报销”的不同审批流程都是调用apply_reimbursement()方法，但财务部和销售部的内部实现完全不同 # ========== 多态演示：报销流程 ==========class Department: &quot;&quot;&quot;部门基类&quot;&quot;&quot; def __init__(self, name: str, manager: str): self.name = name self.manager = manager def apply_reimbursement(self, employee: Employee, amount: float, reason: str): &quot;&quot;&quot; 申请报销：各个部门有不同规则 这就是多态：同样的方法名，不同部门有不同实现 &quot;&quot;&quot; raise NotImplementedError(&quot;子类必须实现此方法&quot;)class FinanceDepartment(Department): &quot;&quot;&quot;财务部：报销审核最严&quot;&quot;&quot; def apply_reimbursement(self, employee: Employee, amount: float, reason: str): print(f&quot;
【财务部报销审核】&quot;) print(f&quot;申请人: &#123;employee.name&#125;&quot;) print(f&quot;金额: ¥&#123;amount:,.2f&#125;&quot;) print(f&quot;事由: &#123;reason&#125;&quot;) if amount &gt; 5000: print(&quot;⚠️ 金额超过¥5000，需要CFO额外审批&quot;) return False else: print(&quot;✅ 审核通过，3个工作日内打款&quot;) return Trueclass SalesDepartment(Department): &quot;&quot;&quot;销售部：为了业绩，报销灵活&quot;&quot;&quot; def apply_reimbursement(self, employee: Employee, amount: float, reason: str): print(f&quot;
【销售部报销审核】&quot;) print(f&quot;申请人: &#123;employee.name&#125;（本月业绩¥&#123;employee.monthly_sales if hasattr(employee, &#x27;monthly_sales&#x27;) else 0:,.2f&#125;）&quot;) # 销售业绩好的员工，报销额度自动提高 if hasattr(employee, &#x27;monthly_sales&#x27;) and employee.monthly_sales &gt; 100000: print(&quot;🎉 业绩优秀，报销快速通道！&quot;) print(&quot;✅ 审核通过，1个工作日内打款&quot;) return True if amount &gt; 10000: print(&quot;⚠️ 金额较大，需要经理审批&quot;) return False else: print(&quot;✅ 审核通过&quot;) return Trueclass TechDepartment(Department): &quot;&quot;&quot;技术部：关注是否合理&quot;&quot;&quot; def apply_reimbursement(self, employee: Employee, amount: float, reason: str): print(f&quot;
【技术部报销审核】&quot;) print(f&quot;申请人: &#123;employee.name&#125;&quot;) print(f&quot;事由: &#123;reason&#125;&quot;) # 检查是否包含技术关键词 tech_keywords = [&#x27;服务器&#x27;, &#x27;域名&#x27;, &#x27;软件&#x27;, &#x27;技术书籍&#x27;, &#x27;培训&#x27;] if any(keyword in reason for keyword in tech_keywords): print(&quot;✅ 技术相关支出，优先批准&quot;) return True else: print(&quot;ℹ️ 非技术支出，按标准流程审批&quot;) return amount &lt;= 3000# 测试多态print(&quot;
&quot; + &quot;=&quot; * 50)print(&quot;报销审批测试（多态）&quot;)print(&quot;=&quot; * 50)# 创建部门对象finance_dept = FinanceDepartment(&quot;财务部&quot;, &quot;张经理&quot;)sales_dept = SalesDepartment(&quot;销售部&quot;, &quot;李经理&quot;)tech_dept = TechDepartment(&quot;技术部&quot;, &quot;王经理&quot;)# 张三（财务部）申请报销finance_dept.apply_reimbursement(emp1, 8000, &quot;年度审计服务费&quot;)# 赵六（销售部）申请报销sales_dept.apply_reimbursement(sales_emp, 12000, &quot;客户招待费&quot;)# 孙七（技术部）申请报销tech_dept.apply_reimbursement(tech_emp, 2500, &quot;购买技术书籍&quot;)tech_dept.apply_reimbursement(tech_emp, 2500, &quot;团队聚餐费&quot;)# 同样的&quot;apply_reimbursement&quot;调用，不同部门有不同实现！
六、实战：构建员工管理系统整合所有概念，做一个能用的系统。 # ========== 员工管理系统 - 完整版 ==========class EmployeeManagementSystem: &quot;&quot;&quot; 员工管理系统：使用面向对象方式管理 &quot;&quot;&quot; def __init__(self, data_file=&quot;employees.json&quot;): self.data_file = data_file self.employees: List[Employee] = [] self.departments: Dict[str, Department] = &#123;&#125; self.load_data() self.init_departments() def init_departments(self): &quot;&quot;&quot;初始化各部门&quot;&quot;&quot; self.departments[&quot;财务部&quot;] = FinanceDepartment(&quot;财务部&quot;, &quot;张经理&quot;) self.departments[&quot;销售部&quot;] = SalesDepartment(&quot;销售部&quot;, &quot;李经理&quot;) self.departments[&quot;技术部&quot;] = TechDepartment(&quot;技术部&quot;, &quot;王经理&quot;) def add_employee(self): &quot;&quot;&quot;添加员工&quot;&quot;&quot; print(&quot;
&quot; + &quot;=&quot; * 40) print(&quot;添加新员工&quot;) print(&quot;=&quot; * 40) name = input(&quot;姓名: &quot;).strip() emp_id = input(&quot;工号: &quot;).strip() dept = input(&quot;部门（财务部/销售部/技术部）: &quot;).strip() salary = float(input(&quot;基本工资: &quot;).strip()) if dept == &quot;销售部&quot;: commission = float(input(&quot;提成比例（如0.08表示8%）: &quot;).strip()) emp = SalesEmployee(name, emp_id, salary, commission) elif dept == &quot;技术部&quot;: bonus = float(input(&quot;项目奖金: &quot;).strip()) emp = TechEmployee(name, emp_id, salary, bonus) else: emp = Employee(name, emp_id, dept, salary) self.employees.append(emp) print(f&quot;
✅ 员工添加成功！&quot;) print(emp) def list_employees(self): &quot;&quot;&quot;列出所有员工&quot;&quot;&quot; print(&quot;
&quot; + &quot;=&quot; * 50) print(&quot;员工列表&quot;) print(&quot;=&quot; * 50) if not self.employees: print(&quot;📭 暂无员工数据&quot;) return for i, emp in enumerate(self.employees, 1): print(f&quot;
&#123;i&#125;. &#123;emp&#125;&quot;) def calculate_all_salaries(self): &quot;&quot;&quot;计算所有员工本月薪资&quot;&quot;&quot; print(&quot;
&quot; + &quot;=&quot; * 50) print(&quot;薪资计算&quot;) print(&quot;=&quot; * 50) if not self.employees: print(&quot;⚠️ 暂无员工数据&quot;) return total_salary = 0 for emp in self.employees: salary = emp.get_monthly_salary() total_salary += salary print(f&quot; &#123;emp.name&#125;: ¥&#123;salary:,.2f&#125;&quot;) print(f&quot;
💰 本月工资总支出: ¥&#123;total_salary:,.2f&#125;&quot;) def reimbursement_request(self): &quot;&quot;&quot;报销申请&quot;&quot;&quot; print(&quot;
&quot; + &quot;=&quot; * 40) print(&quot;报销申请&quot;) print(&quot;=&quot; * 40) if not self.employees: print(&quot;⚠️ 暂无员工数据&quot;) return # 选择员工 self.list_employees() idx = int(input(&quot;选择员工编号（数字）: &quot;).strip()) - 1 if idx &lt; 0 or idx &gt;= len(self.employees): print(&quot;❌ 编号错误&quot;) return emp = self.employees[idx] amount = float(input(&quot;报销金额: &quot;).strip()) reason = input(&quot;报销事由: &quot;).strip() # 获取员工所在部门进行审批 if emp.department in self.departments: self.departments[emp.department].apply_reimbursement(emp, amount, reason) else: print(&quot;⚠️ 该部门暂无审批流程&quot;) def save_data(self): &quot;&quot;&quot;保存数据到JSON&quot;&quot;&quot; data = &#123; &#x27;employees&#x27;: [], &#x27;update_time&#x27;: datetime.now().strftime(&#x27;%Y-%m-%d %H:%M:%S&#x27;) &#125; for emp in self.employees: emp_data = &#123; &#x27;name&#x27;: emp.name, &#x27;employee_id&#x27;: emp.employee_id, &#x27;department&#x27;: emp.department, &#x27;base_salary&#x27;: emp.base_salary, &#x27;type&#x27;: type(emp).__name__ # 保存类型，用于后续加载 &#125; # 保存子类特有属性 if isinstance(emp, SalesEmployee): emp_data[&#x27;commission_rate&#x27;] = emp.commission_rate emp_data[&#x27;monthly_sales&#x27;] = emp.monthly_sales elif isinstance(emp, TechEmployee): emp_data[&#x27;project_bonus&#x27;] = emp.project_bonus data[&#x27;employees&#x27;].append(emp_data) with open(self.data_file, &#x27;w&#x27;, encoding=&#x27;utf-8&#x27;) as f: json.dump(data, f, ensure_ascii=False, indent=2) print(f&quot;✅ 数据已保存到 &#123;self.data_file&#125;&quot;) def load_data(self): &quot;&quot;&quot;从JSON加载数据&quot;&quot;&quot; if not os.path.exists(self.data_file): return try: with open(self.data_file, &#x27;r&#x27;, encoding=&#x27;utf-8&#x27;) as f: data = json.load(f) self.employees = [] for emp_data in data.get(&#x27;employees&#x27;, []): emp_type = emp_data.get(&#x27;type&#x27;, &#x27;Employee&#x27;) if emp_type == &#x27;SalesEmployee&#x27;: emp = SalesEmployee( emp_data[&#x27;name&#x27;], emp_data[&#x27;employee_id&#x27;], emp_data[&#x27;base_salary&#x27;], emp_data.get(&#x27;commission_rate&#x27;, 0.05) ) emp.monthly_sales = emp_data.get(&#x27;monthly_sales&#x27;, 0) elif emp_type == &#x27;TechEmployee&#x27;: emp = TechEmployee( emp_data[&#x27;name&#x27;], emp_data[&#x27;employee_id&#x27;], emp_data[&#x27;base_salary&#x27;], emp_data.get(&#x27;project_bonus&#x27;, 0) ) else: emp = Employee( emp_data[&#x27;name&#x27;], emp_data[&#x27;employee_id&#x27;], emp_data[&#x27;department&#x27;], emp_data[&#x27;base_salary&#x27;] ) self.employees.append(emp) print(f&quot;📂 已加载 &#123;len(self.employees)&#125; 名员工数据&quot;) except Exception as e: print(f&quot;❌ 加载数据失败: &#123;e&#125;&quot;)def main(): &quot;&quot;&quot;主菜单&quot;&quot;&quot; ems = EmployeeManagementSystem() while True: print(&quot;
&quot; + &quot;=&quot; * 55) print(&quot;员工管理系统&quot;) print(&quot;=&quot; * 55) print(&quot;1. 添加员工&quot;) print(&quot;2. 查看员工列表&quot;) print(&quot;3. 计算全体薪资&quot;) print(&quot;4. 报销申请&quot;) print(&quot;5. 保存数据&quot;) print(&quot;6. 退出&quot;) print(&quot;=&quot; * 55) choice = input(&quot;请选择功能: &quot;).strip() if choice == &quot;1&quot;: ems.add_employee() elif choice == &quot;2&quot;: ems.list_employees() input(&quot;
按回车键继续...&quot;) elif choice == &quot;3&quot;: ems.calculate_all_salaries() input(&quot;
按回车键继续...&quot;) elif choice == &quot;4&quot;: ems.reimbursement_request() input(&quot;
按回车键继续...&quot;) elif choice == &quot;5&quot;: ems.save_data() input(&quot;
按回车键继续...&quot;) elif choice == &quot;6&quot;: print(&quot;👋 感谢使用，数据已自动保存！&quot;) ems.save_data() break else: print(&quot;请输入1-6之间的数字！&quot;)if __name__ == &quot;__main__&quot;: main()
七、知识点加油站7.1 OOP三大特性速查&quot;&quot;&quot;封装 (Encapsulation):- __private_attr 私有属性- public_method() 公共方法- 数据保护，防止误修改继承 (Inheritance):- class Child(Parent): 子类继承父类- super().__init__() 调用父类方法- 代码复用，逻辑分层多态 (Polymorphism):- 同名方法，不同实现- 子类重写父类方法- 接口统一，行为多样&quot;&quot;&quot;
7.2 isinstance()和type()的区别emp = SalesEmployee(&quot;张三&quot;, &quot;E1001&quot;, 8000)type(emp) == SalesEmployee # True，精确匹配isinstance(emp, SalesEmployee) # True，是销售员工isinstance(emp, Employee) # True，也是员工（继承关系）
八、总结 ✅ 用公司架构理解类和对象 ✅ 封装保护敏感薪资数据 ✅ 继承实现不同部门员工 ✅ 多态实现差异化报销流程 ✅ 完整的员工管理系统
