.cs2-filter {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 10px 16px;
  padding: 14px 18px;
  margin: 0 0 20px;
  background: var(--card-bg-color, var(--content-bg-color));
  border: 1px solid var(--border-color);
  border-radius: 8px;
  font-size: .95em;
}
.cs2-filter .cs2-title { font-weight: bold; }
.cs2-filter label {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  color: var(--text-color-2);
}
.cs2-filter select {
  max-width: 200px;
  padding: 5px 10px;
  color: var(--text-color);
  background: var(--content-bg-color);
  border: 1px solid var(--border-color);
  border-radius: 4px;
}
.cs2-filter select:focus { border-color: var(--link-color); outline: none; }
.cs2-filter .cs2-reset {
  padding: 5px 14px;
  cursor: pointer;
  color: var(--btn-default-color);
  background: var(--btn-default-bg);
  border: 1px solid var(--btn-default-border-color);
  border-radius: 4px;
}
.cs2-filter .cs2-reset:hover {
  color: var(--btn-default-hover-color);
  background: var(--btn-default-hover-bg);
  border-color: var(--btn-default-hover-border-color);
}
.cs2-filter .cs2-hint {
  width: 100%;
  font-size: .85em;
  color: var(--text-color-2);
  opacity: .8;
}



document.addEventListener('DOMContentLoaded', function () {
  document.querySelectorAll('.cs2-filter').forEach(function (box) {
    var selects = box.querySelectorAll('select');
    var throwSel = selects[0], targetSel = selects[1];

    // 扫描本地图内容：到下一个 h1/h2/h3 为止；h4 记为地点分组
    var items = [], sections = [], cur = null;
    var node = box.nextElementSibling;
    while (node && !/^H[123]$/.test(node.tagName)) {
      if (node.tagName === 'H4') {
        cur = { el: node, items: [] };
        sections.push(cur);
      } else if (node.tagName === 'DETAILS') {
        var parts = node.querySelector('summary').textContent
          .split('-').map(function (s) { return s.trim(); });
        if (parts.length >= 3) {
          var it = { el: node, throwLoc: parts[0], target: parts[1], section: cur };
          items.push(it);
          if (cur) cur.items.push(it);
        }
      }
      node = node.nextElementSibling;
    }

    // 填充下拉框（去重 + 排序）
    function fill(sel, key) {
      Array.from(new Set(items.map(function (i) { return i[key]; }))).sort()
        .forEach(function (v) {
          var op = document.createElement('option');
          op.value = v; op.textContent = v;
          sel.appendChild(op);
        });
    }
    fill(throwSel, 'throwLoc');
    fill(targetSel, 'target');

    function render() {
      var t = throwSel.value, g = targetSel.value;
      var active = t || g;   // 有任一条件即进入筛选模式
      items.forEach(function (it) {
        var show = !active || ((!t || it.throwLoc === t) && (!g || it.target === g));
        it.el.style.display = show ? '' : 'none';
        if (active && show) it.el.setAttribute('open', '');       // 匹配项直接展开
        else it.el.removeAttribute('open');                        // 退出筛选时全部收起
      });
      // 地点小标题（h4）下若没有匹配项，也一并隐藏
      sections.forEach(function (sec) {
        var any = sec.items.some(function (it) { return it.el.style.display !== 'none'; });
        sec.el.style.display = (any || !active) ? '' : 'none';
      });
    }

    var resetBtn = box.querySelector('.cs2-reset');
    if (resetBtn) resetBtn.onclick = function () {
      throwSel.value = '';
      targetSel.value = '';
      render();
    };

    throwSel.onchange = render;
    targetSel.onchange = render;
  });
});

作品简介
作品主要讲述了就读水明艺术大学附属高中的神田空太，一年级的夏天时在宿舍中养猫，而被校长叫去问话，校长让他在丢掉猫与从此搬到”樱花庄”中作选择。身为爱猫一族的空太，暂时选择了流落到因聚集各种怪人而恶名昭著的“樱花庄”。 隔年春天，随着世界级天才画家椎名真白搬进了樱花庄，神田空太开始过起被这名缺乏常识的少女耍得团团转的日子。







