    book:null, rendition:null, toc:[], spine:[], docs:[],
    currentTocIdx:0, currentCfi:null, currentPct:0,
    cur:null, timeout:null,

    open: function(id){
      var c = document.querySelector('[data-epub-id="' + id + '"]');
      if (!c) return;
      this.cur = { path:c.dataset.epubPath, title:c.dataset.epubTitle,
