    },

    resetView: function(){
      if (this.timeout){ clearTimeout(this.timeout); this.timeout = null; }
      if (this.book){ try { this.book.destroy(); } catch(e){} }
      this.book = null; this.rendition = null; this.toc = []; this.spine = []; this.docs = [];
