:root{
  --hr-bg:#ffffff; --hr-panel:#f5f6f8; --hr-panel-2:#e9ecf2;
  --hr-bar:#1b1d21; --hr-bar-text:#f2f3f5;
  --hr-text:#2b2f36; --hr-muted:#767c86; --hr-border:#dfe3ea;
  --hr-accent:#5b8ff9; --hr-accent-text:#ffffff;
  --hr-overlay:rgba(0,0,0,.88);
  --hr-font:1.05em; --hr-line:1.8;
  --hr-z:100000; --hr-radius:12px;
}
@media (prefers-color-scheme:dark){
  :root{ --hr-bg:#1c1f24; --hr-panel:#24272e; --hr-panel-2:#30343c;
    --hr-bar:#121417; --hr-text:#e6e8ec; --hr-muted:#9aa1ac; --hr-border:#3a3f48; }
}
html[data-theme="dark"]{
  --hr-bg:#1c1f24; --hr-panel:#24272e; --hr-panel-2:#30343c;
  --hr-bar:#121417; --hr-text:#e6e8ec; --hr-muted:#9aa1ac; --hr-border:#3a3f48;
}
body[data-hr-theme="light"]{ --hr-bg:#ffffff; --hr-panel:#f5f6f8; --hr-panel-2:#e9ecf2;
  --hr-text:#2b2f36; --hr-muted:#767c86; --hr-border:#dfe3ea; }
body[data-hr-theme="sepia"]{ --hr-bg:#f6efdf; --hr-panel:#ece2cc; --hr-panel-2:#e2d5b8;
  --hr-text:#4a3f2f; --hr-muted:#8a7b61; --hr-border:#d8c9a9; }
body[data-hr-theme="dark"]{ --hr-bg:#17191d; --hr-panel:#21242a; --hr-panel-2:#2c3038;
  --hr-text:#e6e8ec; --hr-muted:#9aa1ac; --hr-border:#3a3f48; }
body[data-hr-font="s"]{ --hr-font:.92em; }
body[data-hr-font="m"]{ --hr-font:1.05em; }
body[data-hr-font="l"]{ --hr-font:1.24em; }
body[data-hr-line="tight"]{ --hr-line:1.55; }
body[data-hr-line="normal"]{ --hr-line:1.8; }
body[data-hr-line="loose"]{ --hr-line:2.15; }

.hr-btn{ display:inline-flex; align-items:center; justify-content:center; gap:.42em;
  padding:6px 12px; border-radius:8px; font-size:.85em; text-decoration:none;
  border:1px solid transparent; cursor:pointer; background:var(--hr-panel-2); color:var(--hr-text);
  white-space:nowrap; transition:opacity .18s, transform .18s, background .18s; }
.hr-btn:hover{ opacity:.85; }
.hr-btn:active{ transform:scale(.97); }
.hr-btn:focus-visible{ outline:2px solid var(--hr-accent); outline-offset:2px; }
.hr-btn.primary{ background:var(--hr-accent); color:var(--hr-accent-text); }
.hr-btn svg{ flex:none; }
.hr-icon-btn{ display:inline-flex; align-items:center; justify-content:center;
  min-width:32px; height:32px; padding:0 7px; border:0; border-radius:7px;
  background:rgba(255,255,255,.10); color:var(--hr-bar-text); cursor:pointer;
  font-size:1em; transition:background .18s; }
.hr-icon-btn:hover{ background:rgba(255,255,255,.22); }
.hr-icon-btn:focus-visible{ outline:2px solid var(--hr-accent); outline-offset:2px; }

.hr-modal{ display:none; position:fixed; inset:0; z-index:var(--hr-z);
  width:100vw; height:100vh; height:100dvh;
  background:var(--hr-overlay); flex-direction:column;
  /* 横屏/小高度时仍能整体滚动，避免底部被视口裁掉且滚不动 */
  overflow-y:auto; overflow-x:hidden; overscroll-behavior:contain; }
.hr-modal.active{ display:flex; }
.hr-modal:fullscreen{ width:100vw; height:100vh; height:100dvh; background:var(--hr-bg); }
.hr-modal:focus{ outline:none; }
.hr-bar{ height:52px; flex:none; display:flex; align-items:center; gap:7px; padding:0 14px;
  background:var(--hr-bar); color:var(--hr-bar-text); border-bottom:1px solid rgba(255,255,255,.08); }
.hr-bar .hr-title{ margin-left:auto; font-size:.9em; opacity:.9; max-width:42%;
  overflow:hidden; text-overflow:ellipsis; white-space:nowrap; }
.hr-main{ flex:1 1 auto; min-height:0; display:flex; overflow:hidden; position:relative; }
.hr-toc{ width:280px; min-width:280px; display:none; flex-direction:column; overflow:hidden;
  background:var(--hr-panel); color:var(--hr-text); border-right:1px solid var(--hr-border); }
.hr-toc.active{ display:flex; }
.hr-toc-header{ padding:14px 16px; font-weight:600; font-size:.95em;
  background:var(--hr-panel-2); border-bottom:1px solid var(--hr-border); }
.hr-toc-list{ flex:1; overflow-y:auto; padding:8px 0; }
.hr-toc-item{ display:block; padding:8px 18px; color:var(--hr-text); text-decoration:none;
  font-size:.88em; cursor:pointer; border-bottom:1px solid var(--hr-border);
  white-space:nowrap; overflow:hidden; text-overflow:ellipsis; }
.hr-toc-item:hover{ background:var(--hr-panel-2); }
.hr-toc-item.active{ background:var(--hr-accent); color:var(--hr-accent-text); }
.hr-view{ flex:1 1 auto; min-width:0; min-height:0; position:relative;
  background:var(--hr-bg); color:var(--hr-text);
  overflow-x:hidden; overflow-y:auto; -webkit-overflow-scrolling:touch; }
.hr-stage{ width:100%; min-height:100%; }
.hr-center{ position:absolute; top:50%; left:50%; transform:translate(-50%,-50%);
  text-align:center; color:var(--hr-text); z-index:5; }
.hr-center .hr-err{ color:#e05b53; font-size:.86em; margin-top:6px; }

.hr-progress-wrap{ flex:none; height:34px; display:flex; align-items:center; gap:10px;
  padding:0 14px; background:var(--hr-bar); color:var(--hr-bar-text); font-size:.78em; }
.hr-progress{ flex:1; height:6px; border-radius:99px; background:rgba(255,255,255,.16);
  cursor:pointer; overflow:hidden; }
.hr-progress-fill{ height:100%; width:0; border-radius:99px; background:var(--hr-accent);
  transition:width .18s; }
.hr-progress-label{ min-width:3.6em; }

.hr-settings{ position:absolute; top:52px; right:14px; width:246px; max-width:calc(100vw - 28px);
  display:none; max-height:calc(100vh - 68px); max-height:calc(100dvh - 68px); overflow-y:auto;
  background:var(--hr-panel); color:var(--hr-text); border:1px solid var(--hr-border);
  border-radius:12px; box-shadow:0 12px 32px rgba(0,0,0,.28); padding:14px;
  z-index:calc(var(--hr-z) + 2); }
.hr-settings.active{ display:block; }
.hr-set-row{ display:flex; align-items:center; justify-content:space-between; gap:8px;
  margin-bottom:11px; font-size:.85em; }
.hr-set-row:last-child{ margin-bottom:0; }
.hr-set-label{ color:var(--hr-muted); white-space:nowrap; }
.hr-seg{ display:flex; gap:4px; }
.hr-seg button{ padding:4px 8px; border:1px solid var(--hr-border); border-radius:6px;
  background:transparent; color:var(--hr-text); font-size:.9em; cursor:pointer; }
.hr-seg button:hover{ background:var(--hr-panel-2); }
.hr-seg button.active{ background:var(--hr-accent); color:var(--hr-accent-text);
  border-color:var(--hr-accent); }
.hr-seg button:focus-visible{ outline:2px solid var(--hr-accent); outline-offset:1px; }

.hr-card{ border-radius:var(--hr-radius); overflow:hidden;
  background:var(--hr-bg); border:1px solid var(--hr-border);
  box-shadow:0 2px 10px rgba(0,0,0,.07); transition:transform .2s, box-shadow .2s; }
.hr-card:hover{ transform:translateY(-3px); box-shadow:0 6px 20px rgba(0,0,0,.12); }
/* 两个 reader 共用的续读样式：列表顶部主入口 + 对应卡片的高亮 */
.hr-card.has-progress{ border-color:var(--hr-accent); box-shadow:0 0 0 1px var(--hr-accent); }
.hr-resume{ display:inline-flex; align-items:center; margin:0 0 14px; }

@media (max-width:768px){
  .hr-bar{ height:48px; padding:0 10px; gap:4px; }
  .hr-bar .hr-title{ max-width:34%; font-size:.82em; }
  .hr-toc{ position:absolute; z-index:calc(var(--hr-z) + 1); height:100%;
    width:min(78vw,260px); min-width:0; box-shadow:2px 0 12px rgba(0,0,0,.2); }
  .hr-settings{ top:48px; right:8px; }
}
/* 手机横屏 / 矮窗口：压缩固定栏，给正文留出可滚动空间 */
@media (max-height:560px){
  .hr-bar{ height:40px; padding:0 8px; gap:3px; }
  .hr-bar .hr-title{ font-size:.78em; max-width:30%; }
  .hr-icon-btn{ min-width:28px; height:28px; }
  .hr-progress-wrap{ height:26px; padding:0 10px; }
  .hr-settings{ top:40px; right:8px; max-height:calc(100dvh - 48px); }
  .hr-toc-header{ padding:8px 12px; }
}
@media (max-height:420px){
  .hr-bar .hr-title{ display:none; }
  .hr-progress-hint{ display:none; }
}
@media (prefers-reduced-motion:reduce){
  .hr-card, .hr-btn, .hr-progress-fill{ transition:none; }
  .hr-card:hover{ transform:none; }
}



(function(){
  var KEY = 'hexoReaderSettings';
  var DEFAULTS = { theme:'auto', font:'m', line:'normal' };
  var READ_ICON = "";

  function readSettings(){
    try { return Object.assign({}, DEFAULTS, JSON.parse(localStorage.getItem(KEY) || '{}')); }
    catch(e){ return Object.assign({}, DEFAULTS); }
  }
  // auto 主题解析成具体配色，供 EPUB iframe 使用（iframe 继承不到页面的 CSS 变量）
  function effectiveTheme(s){
    if (s.theme !== 'auto') return s.theme;
    var dark = document.documentElement.getAttribute('data-theme') === 'dark'
      || (window.matchMedia && window.matchMedia('(prefers-color-scheme:dark)').matches);
    return dark ? 'dark' : 'light';
  }
  function resolvedSettings(){
    var s = readSettings();
    return { theme:effectiveTheme(s), font:s.font, line:s.line, raw:s };
  }
  function applySettings(){
    var s = readSettings(), b = document.body;
    if (s.theme === 'auto') b.removeAttribute('data-hr-theme');
    else b.setAttribute('data-hr-theme', s.theme);
    b.setAttribute('data-hr-font', s.font);
    b.setAttribute('data-hr-line', s.line);
    document.querySelectorAll('.hr-seg button').forEach(function(btn){
      var on = btn.dataset.value === s[btn.dataset.field];
      btn.classList.toggle('active', on);
      btn.setAttribute('aria-pressed', on ? 'true' : 'false');
    });
    if (window.HexoEpubReader && window.HexoEpubReader.refresh) window.HexoEpubReader.refresh();
    if (window.HexoTxtReader && window.HexoTxtReader.refresh) window.HexoTxtReader.refresh();
  }
  function setSetting(field, value){
    var s = readSettings(); s[field] = value;
    try { localStorage.setItem(KEY, JSON.stringify(s)); } catch(e){}
    applySettings();
  }

  function progressGet(kind, key){
    try { return localStorage.getItem('hexoReader:' + kind + ':' + key); } catch(e){ return null; }
  }
  function progressSet(kind, key, value){
    try {
      localStorage.setItem('hexoReader:' + kind + ':' + key, String(value));
      // 记住「最近读的是哪一本」，供 EPUB 多卷页面的顶部续读条定位
      localStorage.setItem('hexoReaderLast:' + kind, String(key));
    } catch(e){}
  }
  function progressLast(kind){
    try { return localStorage.getItem('hexoReaderLast:' + kind); } catch(e){ return null; }
  }

  // 两个 reader 共用的顶部续读条：同一套样式、图标与「继续阅读 · X」文案
  function insertResume(anchor, text, handler){
    if (!anchor || !anchor.parentNode) return null;
    var prev = anchor.previousElementSibling;
    if (prev && prev.classList && prev.classList.contains('hr-resume')) return null;
    var btn = document.createElement('button');
    btn.type = 'button';
    btn.className = 'hr-btn primary hr-resume';
    btn.innerHTML = READ_ICON;
    var label = document.createElement('span');
    label.textContent = text;
    btn.appendChild(label);
    btn.onclick = handler;
    anchor.parentNode.insertBefore(btn, anchor);
    return btn;
  }

  function activeModal(){ return document.querySelector('.hr-modal.active'); }

  function requestFull(el){
    if (document.fullscreenElement || !el || !el.requestFullscreen) return;
    try {
      var p = el.requestFullscreen();
      if (p && p.catch) p.catch(function(){});
    } catch(e){}
  }
  function exitFull(el){
    if (document.fullscreenElement !== el || !document.exitFullscreen) return;
    try {
      var p = document.exitFullscreen();
      if (p && p.catch) p.catch(function(){});
    } catch(e){}
  }
  function toggleFull(){
    var m = activeModal();
    if (!m) return;
    if (document.fullscreenElement === m) exitFull(m);
    else requestFull(m);
  }

  function openModal(el){
    document.querySelectorAll('.hr-modal.active').forEach(function(m){
      if (m !== el) m.classList.remove('active');
    });
    // 阅读器是随文章一起注入的，DOM 原本落在正文容器里。
    // NexT 的正文列会给 position:fixed 建立包含块，留在里面会被压成正文宽度
    // （只显示左边一小条）。点「阅读」时挂到 body 直属，fixed 才相对视口铺满。
    if (el.parentNode !== document.body) document.body.appendChild(el);
    if (!document.body.dataset.hrScrollSaved){
      document.body.dataset.hrScrollSaved = '1';
      document.body.dataset.hrOverflow = document.body.style.overflow || '';
    }
    document.body.style.overflow = 'hidden';
    el.classList.add('active');
    applySettings();
    // 所有端点「阅读」都直接进入全屏，不再有「只待在正文中」的非全屏状态
    requestFull(el);
    var f = el.querySelector('[data-hr-autofocus]');
    if (f) f.focus();
  }
  function closeModal(el){
    exitFull(el);
    el.classList.remove('active');
    document.body.style.overflow = document.body.dataset.hrOverflow || '';
    delete document.body.dataset.hrScrollSaved;
    delete document.body.dataset.hrOverflow;
    var p = el.querySelector('.hr-settings');
    if (p) p.classList.remove('active');
  }

  function closest(el, sel){
    while (el && el.nodeType === 1){
      if (el.matches && el.matches(sel)) return el;
      el = el.parentElement;
    }
    return null;
  }

  document.addEventListener('click', function(e){
    var seg = closest(e.target, '.hr-seg button');
    if (seg){ setSetting(seg.dataset.field, seg.dataset.value); return; }
    var t = closest(e.target, '[data-hr-settings-toggle]');
    if (t){
      var m = activeModal();
      var p = m && m.querySelector('.hr-settings');
      if (p) p.classList.toggle('active');
    }
  });

  document.addEventListener('keydown', function(e){
    var m = activeModal();
    if (!m) return;
    var r = m.dataset.reader === 'epub' ? window.HexoEpubReader : window.HexoTxtReader;
    if (!r) return;
    if (e.key === 'ArrowLeft'){ e.preventDefault(); r.prev(); }
    else if (e.key === 'ArrowRight'){ e.preventDefault(); r.next(); }
    else if (e.key === 'Escape'){ e.preventDefault(); r.close(); }
  });

  window.HexoReaderCore = {
    settings: { get:readSettings, set:setSetting, apply:applySettings,
                resolved:resolvedSettings, effectiveTheme:effectiveTheme },
    progress: { get:progressGet, set:progressSet, last:progressLast },
    activeModal: activeModal,
    openModal: openModal,
    closeModal: closeModal,
    insertResume: insertResume,
    fullscreen: { enter:requestFull, exit:exitFull, toggle:toggleFull }
  };

  applySettings();
})();



.epub-grid{ display:grid; grid-template-columns:repeat(auto-fill,minmax(260px,1fr)); gap:18px; margin:1.5em 0; }
.epub-card{ display:flex; }
.epub-cover{ width:110px; min-width:110px; aspect-ratio:2/3; height:auto; position:relative; overflow:hidden;
  display:flex; align-items:center; justify-content:center; color:#fff; font-size:1.5em; font-weight:700;
  background:linear-gradient(135deg, hsl(var(--epub-hue,220),62%,55%), hsl(calc(var(--epub-hue,220) + 42),58%,40%)); }
.epub-cover img{ position:absolute; inset:0; width:100%; height:100%; object-fit:cover; }
.epub-placeholder{ position:absolute; inset:0; align-items:center; justify-content:center; letter-spacing:.05em; }
.epub-vol{ position:absolute; top:6px; left:6px; z-index:2; background:#e05b53; color:#fff;
  padding:2px 7px; border-radius:5px; font-size:.72em; font-weight:700; box-shadow:0 2px 4px rgba(0,0,0,.25); }
.epub-body{ padding:14px; flex:1; min-width:0; display:flex; flex-direction:column; gap:6px; }
.epub-title{ margin:0; font-size:1.05em; line-height:1.35; color:var(--hr-text); }
.epub-date,.epub-meta{ margin:0; font-size:.8em; color:var(--hr-muted);
  display:flex; align-items:center; gap:.35em; }
.epub-meta{ font-variant-numeric:tabular-nums; }
.epub-actions{ display:flex; gap:8px; margin-top:auto; padding-top:8px; }
.epub-actions .hr-btn{ flex:1; }
.hexo-epub-view .hr-stage{ height:100%; }
#hexo-epub-stage{ width:100%; height:100%; }
.hexo-epub-fallback p{ margin:0 0 10px; color:var(--hr-text); font-size:.9em; }
.hexo-epub-fallback .hr-btn{ margin:4px; }
@media (max-width:768px){
  .epub-grid{ grid-template-columns:1fr; }
  .epub-cover{ width:84px; min-width:84px; }
  .epub-body{ padding:12px; }
  .epub-actions{ flex-wrap:wrap; }
}



