(function(){
  var SCALE = {"font":{"s":".92em","m":"1.05em","l":"1.24em"},"line":{"tight":"1.55","normal":"1.8","loose":"2.15"},"theme":{"light":{"bg":"#ffffff","fg":"#2b2f36"},"sepia":{"bg":"#f6efdf","fg":"#4a3f2f"},"dark":{"bg":"#17191d","fg":"#e6e8ec"}}};
  var READ_ICON = "";
  var LIBS = [
    { name:'JSZip', test:function(){ return typeof JSZip !== 'undefined'; },
      urls:['https://cdn.jsdelivr.net/npm/jszip@3.10.1/dist/jszip.min.js',
            'https://unpkg.com/jszip@3.10.1/dist/jszip.min.js'] },
    { name:'ePub', test:function(){ return typeof ePub !== 'undefined'; },
      urls:['https://cdn.jsdelivr.net/npm/epubjs@0.3.88/dist/epub.min.js',
            'https://unpkg.com/epubjs@0.3.88/dist/epub.min.js'] }
  ];
  var libsPromise = null;

  function loadScript(url){
    return new Promise(function(resolve, reject){
      var s = document.createElement('script');
      s.src = url; s.async = false;
      s.onload = resolve;
      s.onerror = function(){ s.remove(); reject(new Error('CDN 不可用')); };
      document.head.appendChild(s);
    });
  }
  function loadOne(lib){
    if (lib.test()) return Promise.resolve();
    var i = 0;
    function attempt(){
      if (i >= lib.urls.length) return Promise.reject(new Error(lib.name + ' 加载失败'));
      return loadScript(lib.urls[i++]).then(function(){
        if (!lib.test()) throw new Error('文件无效');
      }).catch(attempt);
    }
    return attempt();
  }
  function ensureLibs(){
    if (!libsPromise){
      libsPromise = loadOne(LIBS[0]).then(function(){ return loadOne(LIBS[1]); });
    }
    return libsPromise.catch(function(e){ libsPromise = null; throw e; });
  }

  function el(id){ return document.getElementById(id); }
  var modal = el('hexo-epub-modal');

  /* ---------- 正文主题：把设置写成 iframe  上的 CSS 变量 ----------
     样式表 append 到 head 末尾（书的 CSS 之后），全部用 !important，
     改设置时只更新变量值，已渲染的 iframe 立即生效，无需重绘、不丢位置。 */
  var EPUB_SKIN_CSS = [
    'html{ background:var(--hr-epub-bg) !important; color:var(--hr-epub-fg) !important;',
    ' font-size:var(--hr-epub-font) !important; line-height:var(--hr-epub-line) !important; }',
    'body{ background:var(--hr-epub-bg) !important; color:var(--hr-epub-fg) !important;',
    ' font-size:1em !important; line-height:var(--hr-epub-line) !important;',
    ' font-family:system-ui,-apple-system,"Segoe UI","Microsoft YaHei",sans-serif !important;',
    ' margin:0 auto !important; padding:0 1.2em !important; max-width:100% !important; }',
    'body p,body div,body span,body li,body td,body blockquote,body section,body article,',
    'body h1,body h2,body h3,body h4,body h5,body h6{',
    ' color:var(--hr-epub-fg) !important; line-height:var(--hr-epub-line) !important;',
    ' font-size:1em !important; font-family:inherit !important; }',
    'body h1{ font-size:1.6em !important; } body h2{ font-size:1.4em !important; }',
    'body h3{ font-size:1.2em !important; }',
    'body a{ color:var(--hr-epub-link,#5b8ff9) !important; }',
    'img,svg{ max-width:100% !important; height:auto !important; }'
  ].join('');

  function currentSkin(){
    var s = window.HexoReaderCore.settings.resolved();
    var t = SCALE.theme[s.theme] || SCALE.theme.light;
    return {
      bg:t.bg, fg:t.fg, link:'#5b8ff9',
      font:SCALE.font[s.font] || SCALE.font.m,
      line:SCALE.line[s.line] || SCALE.line.normal
    };
  }

  function applySkinToDoc(doc, skin){
    if (!doc || !doc.head || !doc.documentElement) return;
    var style = doc.querySelector('style[data-hr-epub-skin]');
    if (!style){
      style = doc.createElement('style');
      style.setAttribute('data-hr-epub-skin', '1');
      style.textContent = EPUB_SKIN_CSS;
      // 必须放在书内样式之后，才能覆盖书自带的 !important 配色/字号
      doc.head.appendChild(style);
    }
    var root = doc.documentElement.style;
    root.setProperty('--hr-epub-bg', skin.bg);
    root.setProperty('--hr-epub-fg', skin.fg);
    root.setProperty('--hr-epub-link', skin.link);
    root.setProperty('--hr-epub-font', skin.font);
    root.setProperty('--hr-epub-line', skin.line);
    if (doc.body){
      doc.body.style.backgroundColor = skin.bg;
      doc.body.style.color = skin.fg;
    }
  }

