    open: function(id){
      var c = document.querySelector('[data-epub-id="' + id + '"]');
      if (!c) return;
      this.cur = { path:c.dataset.epubPath, title:c.dataset.epubTitle,
                   key:c.dataset.bookKey || c.dataset.epubPath };
      el('hexo-epub-tit').textContent = this.cur.title;
      this.resetView();
      window.HexoReaderCore.openModal(modal);
      this.start();
    },

    resetView: function(){
      if (this.timeout){ clearTimeout(this.timeout); this.timeout = null; }
      if (this.book){ try { this.book.destroy(); } catch(e){} }
      this.book = null; this.rendition = null; this.toc = []; this.spine = []; this.docs = [];
      this.currentTocIdx = 0; this.currentCfi = null; this.currentPct = 0;
      el('hexo-epub-stage').innerHTML = '';
      el('hexo-epub-toc-list').innerHTML = '';
      el('hexo-epub-toc').classList.remove('active');
      el('hexo-epub-load').style.display = 'block';
      el('hexo-epub-err').textContent = '';
      el('hexo-epub-fallback').style.display = 'none';
      el('hexo-epub-fallback-link').href = this.cur ? this.cur.path : '#';
      this.setProgress(0, '');
    },

    start: function(){
      var self = this;
      if (!this.cur) return;
      el('hexo-epub-load').style.display = 'block';
      el('hexo-epub-load').firstChild.textContent = '正在加载阅读器…';
      el('hexo-epub-fallback').style.display = 'none';
      ensureLibs().then(function(){
        el('hexo-epub-load').firstChild.textContent = '正在加载书籍…';
        return fetch(self.cur.path);
      }).then(function(res){
        if (!res.ok) throw new Error('HTTP ' + res.status);
        return res.arrayBuffer();
